    /// <summary>Helper: create a DefinitionRegistry with the social defs registered.</summary>
    static DefinitionRegistry CreateSocialDefs()
    {
        var log = Microsoft.Extensions.Logging.LoggerFactory.Create(b => { }).CreateLogger("test");
        var reg = new DefinitionRegistry(log);

        reg.RegisterFromDef("S_USER_BLOCK_LIST", @"
array blockList
- ref name
- ref myNote
- uint32 id
- int32 level
- int32 class
- string name
- string myNote
");
        reg.RegisterFromDef("S_FRIEND_GROUP_LIST", @"
array groups
- ref name
- int32 index
- string name
");
        // S_FRIEND_LIST is the 100.02 layout from V100Definitions - the def FILE
        // (S_FRIEND_LIST.2) is the patch-101 one and carries an extra int32. T30.
        V100Definitions.EnsureRegistered(reg);
        reg.RegisterFromDef("S_WHISPER", @"
ref name
ref recipient
ref message
uint64 gameId
bool isWorldEventTarget
bool gm
bool founder
string name
string recipient
string message
");
        return reg;
    }

