    // ==================== T34: the routing tests MULTIPLAYER-DESIGN section 6 needs ====================
    //
    // These assert the behaviour status/MULTIPLAYER-DESIGN.md section 6 specifies. The current
    // WorldBridge does not have it, so six of the eight are RED ON PURPOSE - they are the
    // executable form of the diffs, written before the diffs so that applying them has a pass
    // condition. WorldBridge.cs is human-owned; Cowork does not edit it.
    //
    // While RoutingDiffsApplied is false the six report PENDING instead of throwing, so
    // `dotnet run --project src\TeraSharp.Arbiter.Tests` stays usable as a merge gate. A pending
    // test that unexpectedly PASSES fails loudly - that is the signal that section 6 has landed
    // and this flag should be flipped.
    //
    // TWO EXISTING TESTS CONTRADICT THESE AND MUST GO when section 6 is applied:
    //   TunnelRouting_unknown_key_broadcasts  - pins the broadcast fallback that
    //       Routing_recipient_with_no_session_is_dropped_not_broadcast forbids once 2+ sessions
    //       are registered. Delete it, or narrow it to the single-session case.
    //   AllocateTunnelKey_pinned_to_5         - pins the constant that
    //       Routing_two_sessions_get_distinct_tickets forbids. Delete it.
    //
    /// <summary>Flip to true the moment MULTIPLAYER-DESIGN.md section 6 is applied to
    /// WorldBridge.cs; the six pending tests below then become hard failures again.</summary>
    public static bool RoutingDiffsApplied = true;   // WorldBridge swap applied 2026-09-15 00:20

    static void PendingUntilRoutingDiffs(string name, Action body)
    {
        if (RoutingDiffsApplied) { body(); return; }
        try { body(); }
        catch (Exception ex)
        {
            var first = ex.Message.Split('\n')[0];
            Console.WriteLine($"        PENDING (MULTIPLAYER-DESIGN section 6): {name}: {first}");
            return;
        }
        throw new Exception(
            $"{name} PASSES against the current WorldBridge - MULTIPLAYER-DESIGN.md section 6 "
            + "must have landed. Set Tests.RoutingDiffsApplied = true and delete "
            + "TunnelRouting_unknown_key_broadcasts + AllocateTunnelKey_pinned_to_5.");
    }

    /// <summary>
    /// A real SA_BYPASS_TO_CLIENT payload for N recipients. Unlike BuildTestTunnelPayload this
    /// sets userListBytes = 16*N and packetOffset = 22 + userListBytes, which is what the wire
    /// actually carries (Arb_part_016.c:8636); with one recipient the two agree.
    ///   [0] u32 userListOffset = 22   [4] u32 userListBytes = 16*N
    ///   [8] u32 packetOffset = 22+16N [12] u32 packetLength
    ///   [16] N x { [+0] u32 planetId  [+4] u32 (unread)  [+8] u32 ticket  [+12] u32 seq&lt;&lt;19 }
    /// </summary>
    static byte[] BuildTunnelFrame(byte[] clientPkt, params (uint ticket, uint seq)[] to)
    {
        // T38: the layout now lives in World/TunnelFrames.cs, which round-trips all 4169
        // captured 0x13F7 frames byte for byte. This helper stays as the tuple-shaped front
        // end the routing tests below were written against.
        var recipients = new TunnelRecipient[to.Length];
        for (int i = 0; i < to.Length; i++) recipients[i] = TunnelFrames.To(to[i].ticket, to[i].seq);
        return TunnelFrames.BuildBypassToClient(clientPkt, recipients);
    }

    static byte[] ClientPkt(byte tag) => new byte[] { 4, 0, tag, 0x00 };

    /// <summary>Bridge + a dummy link. Tunnel frames never touch the link beyond its Id.</summary>
    static (WorldBridge bridge, WorldLink link, Socket sock) TunnelHarness()
    {
        var log = QuietLog();
        var bridge = new WorldBridge(WorldReplayTable.Load("/nonexistent", log), log);
        var sock = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
        return (bridge, new WorldLink(1, sock, bridge, log), sock);
    }

    [Test] public static void Routing_two_recipient_frame_splits_to_both_sessions()
        => PendingUntilRoutingDiffs(nameof(Routing_two_recipient_frame_splits_to_both_sessions), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // One frame, two recipients - the shape World uses the moment two players can see
            // each other. The Arbiter refcounts one BypassPacketInfo by recipient count and
            // posts one job per live session (Arb_part_062.c:3736).
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient,
                BuildTunnelFrame(ClientPkt(0xAA), (0, 0), (1, 0)));

            Hex.True(a.Count == 1 && b.Count == 1,
                $"both sessions get the packet: A={a.Count} B={b.Count}");
            Hex.Eq(a[0], ClientPkt(0xAA), "A's copy");
            Hex.Eq(b[0], ClientPkt(0xAA), "B's copy");
            Hex.True(!ReferenceEquals(a[0], b[0]),
                "each session must get its own array - GameSession.Send encrypts in place with a "
                + "stateful cipher, so a shared buffer corrupts the second session's stream");
        }
    });

    [Test] public static void Routing_packet_offset_follows_the_user_list_length()
        => PendingUntilRoutingDiffs(nameof(Routing_packet_offset_follows_the_user_list_length), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var got = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, got.Add);
            bridge.RegisterTunnelRoute(1, _ => { });

            // With two recipients the header is 48 bytes, not 32: payload[8]-6 == 16+userListBytes.
            // Reading from a fixed 32 lands inside the SECOND UserList entry.
            var frame = BuildTunnelFrame(ClientPkt(0xBB), (0, 0), (1, 0));
            Hex.True(BitConverter.ToUInt32(frame, 4) == 32, "userListBytes = 16 * 2");
            Hex.True(BitConverter.ToUInt32(frame, 8) - 6 == 48, "the packet starts at payload+48");

            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, frame);
            Hex.True(got.Count == 1, $"A got {got.Count} packets");
            Hex.Eq(got[0], ClientPkt(0xBB),
                "the client packet must come from payload[8]-6, not a hardcoded 32");
        }
    });

    [Test] public static void Routing_each_recipient_has_its_own_sequence()
        => PendingUntilRoutingDiffs(nameof(Routing_each_recipient_has_its_own_sequence), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // Sequence lives in each UserList entry (entry+12 >> 19), not once per frame. Here A
            // is at seq 1 while B is at seq 0, so A's packet must be held and B's delivered.
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient,
                BuildTunnelFrame(ClientPkt(0xC1), (0, 1), (1, 0)));
            Hex.True(a.Count == 0, $"A's seq 1 must wait for seq 0, got {a.Count}");
            Hex.True(b.Count == 1, $"B's seq 0 delivers immediately, got {b.Count}");

            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient,
                BuildTunnelFrame(ClientPkt(0xC0), (0, 0)));
            Hex.True(a.Count == 2, $"A drains both once seq 0 arrives, got {a.Count}");
            Hex.True(a[0][2] == 0xC0 && a[1][2] == 0xC1, "and in sequence order");
        }
    });

    [Test] public static void Routing_recipient_with_no_session_is_dropped_not_broadcast()
        => PendingUntilRoutingDiffs(nameof(Routing_recipient_with_no_session_is_dropped_not_broadcast), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // The real Arbiter backs the refcount out for a recipient with no live session
            // (Arb_part_062.c:3800) - it does not hand the packet to somebody else. With two
            // players the broadcast fallback means A sees packets addressed to B.
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient,
                BuildTunnelFrame(ClientPkt(0xDD), (99, 0)));
            Hex.True(a.Count == 0 && b.Count == 0,
                $"an unknown ticket must be dropped, not broadcast: A={a.Count} B={b.Count}");

            // ...and a mixed frame delivers only to the live recipient.
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient,
                BuildTunnelFrame(ClientPkt(0xDE), (0, 0), (99, 0)));
            Hex.True(a.Count == 1 && b.Count == 0,
                $"only the live recipient is served: A={a.Count} B={b.Count}");
        }
    });

    [Test] public static void Routing_two_sessions_get_distinct_tickets()
        => PendingUntilRoutingDiffs(nameof(Routing_two_sessions_get_distinct_tickets), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            // PacketBypassManager::BypassStart (FUN_1405afaf0, Arb_part_048.c:9296) probes
            // linearly from a monotonic cursor; two live users can never share a Ticket, because
            // it is the index of the ClientSession* table slot the packet is routed through.
            uint k1 = bridge.AllocateTunnelKey();
            bridge.RegisterTunnelRoute(k1, _ => { });
            uint k2 = bridge.AllocateTunnelKey();
            Hex.True(k1 != k2, $"two sessions must not share a Ticket (both got {k1})");

            bridge.RegisterTunnelRoute(k2, _ => { });
            uint k3 = bridge.AllocateTunnelKey();
            Hex.True(k3 != k1 && k3 != k2, $"nor a third ({k3} collides with {k1}/{k2})");
        }
    });

    [Test] public static void Routing_reset_for_one_player_keeps_the_others_pending_packets()
        => PendingUntilRoutingDiffs(nameof(Routing_reset_for_one_player_keeps_the_others_pending_packets), () =>
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // B has an out-of-order packet waiting.
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xB1), (1, 1)));
            Hex.True(b.Count == 0, "B's seq 1 is pending");

            // A enters the world, which resets A's sequence. Once MULTIPLAYER-DESIGN.md section
            // 6(4) lands this line becomes bridge.ResetTunnelSequence(0) and the test goes green;
            // the assertion - one player's reset must not discard another's queue - is the same
            // either way, because sequence numbers are per-Ticket.
            bridge.ResetTunnelSequence(0);   // keyed reset landed 2026-09-15 (section 6(4))

            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xB0), (1, 0)));
            Hex.True(b.Count == 2, $"B should drain both, got {b.Count} - a global reset threw its queue away");
            Hex.True(b[0][2] == 0xB0 && b[1][2] == 0xB1, "and in order");
        }
    });

    // --- the two that already pass: regression locks, so section 6 cannot break them ---

    [Test] public static void Routing_out_of_order_two_players_do_not_block_each_other()
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // Single-recipient frames, so this exercises the routing that already works. A is
            // missing seq 1; B is complete. B must not wait behind A.
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xA0), (0, 0)));
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xA2), (0, 2)));
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xB0), (1, 0)));
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xB1), (1, 1)));

            Hex.True(a.Count == 1, $"A holds seq 2 waiting for seq 1, got {a.Count}");
            Hex.True(b.Count == 2, $"B is unaffected, got {b.Count}");
            Hex.True(b[0][2] == 0xB0 && b[1][2] == 0xB1, "B's packets are in order");
        }
    }

    [Test] public static void Routing_leave_frees_only_the_leaving_ticket()
    {
        var (bridge, link, sock) = TunnelHarness();
        using (sock)
        {
            var a = new List<byte[]>(); var b = new List<byte[]>();
            bridge.RegisterTunnelRoute(0, a.Add);
            bridge.RegisterTunnelRoute(1, b.Add);

            // SA_LEAVE_WORLD frees one Ticket (Handler_SA_LEAVE_WORLD -> BypassEnd, and
            // GameSession calls UnregisterPlayer off 0x1393). The other player keeps streaming.
            bridge.UnregisterTunnelRoute(0);
            bridge.HandleFrame(link, WorldBridge.OpTunnelToClient, BuildTunnelFrame(ClientPkt(0xB0), (1, 0)));
            Hex.True(b.Count == 1, $"B still receives, got {b.Count}");
            Hex.True(a.Count == 0, "and the departed session receives nothing");
        }
    }

    // ===================== T35: PartyManager (status/PARTY-DESIGN.md) =====================
    //
    // Parties are Arbiter-owned in-memory state. These drive PartyManager's two entry points and
    // then push every emitted client action through the REAL .def codec, so the scenario is
    // checked end to end rather than against a layout written down twice. No capture contains a
    // party frame, so the A->W bytes are golden against PARTY-DESIGN.md section 5.1 (which came
    // from the decompiled writers), and the client packets are round-tripped through
    // DefinitionWriter -> DefinitionReader.

    static PartyManager NewPartyManager() => new(QuietLog());

    static PartyManager.PartyPlayer P(uint ticket, int dbId, string name, int cls = 12) =>
        new(Ticket: ticket, UserDbId: dbId, Name: name, Level: 65, Class: cls, Race: 4, Gender: 1,
            GameId: 0x80000AF00000UL | (uint)dbId, Laurel: 3, AwakenGrade: 1);

    /// <summary>An SA_JOIN_PARTY frame: World telling us member+invitee agreed.</summary>
    static byte[] SaJoinPartyPayload(int memberDbId, int inviteeDbId, long partyId = 0,
        bool raid = false, int maxMembers = 5)
    {
        var p = new byte[0x56 - 6];
        void U32(int frameOff, int v) => BitConverter.GetBytes(v).CopyTo(p, frameOff - 6);
        U32(0x06, PartyManager.PlanetId); U32(0x0A, PartyManager.PlanetId); U32(0x0E, memberDbId);
        U32(0x12, PartyManager.PlanetId); U32(0x16, inviteeDbId);
        BitConverter.GetBytes(0x80000AF00000UL | (uint)inviteeDbId).CopyTo(p, 0x1E - 6);
        U32(0x26, 65); U32(0x2A, 12); U32(0x2E, 4); U32(0x32, 1); U32(0x36, -1);
        p[0x3A - 6] = 1; p[0x3B - 6] = 1;                       // alive, online
        U32(0x3C, 3); U32(0x40, 1);                             // achievement, awaken
        BitConverter.GetBytes(partyId).CopyTo(p, 0x44 - 6);
        U32(0x4C, -1);                                          // partyType
        p[0x50 - 6] = 0; p[0x51 - 6] = (byte)(raid ? 1 : 0);
        U32(0x52, maxMembers);
        return p;
    }

    static byte[] SaLeavePartyPayload(long partyId, int memberDbId)
    {
        var p = new byte[0x1A - 6];
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 0);
        BitConverter.GetBytes(partyId).CopyTo(p, 4);
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 12);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 16);
        return p;
    }

    static byte[] SaPartyActorPayload(int memberDbId)
    {
        var p = new byte[0x12 - 6];
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 0);
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 4);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 8);
        return p;
    }

    static byte[] SaExtendPartyPayload(int memberDbId, bool raid)
    {
        var p = new byte[0x13 - 6];
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 0);
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 4);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 8);
        p[12] = (byte)(raid ? 1 : 0);
        return p;
    }

    static byte[] SaChangeLootingPayload(int memberDbId, in PartyPackets.LootSettings s)
    {
        var p = new byte[0x25 - 6];
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 0);
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 4);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 8);
        BitConverter.GetBytes(s.Method).CopyTo(p, 12);
        BitConverter.GetBytes(s.RareGradeForDicing).CopyTo(p, 16);
        BitConverter.GetBytes(s.RareItemDistributionMethod).CopyTo(p, 20);
        p[24] = (byte)(s.EquipmentForDicing ? 1 : 0);
        p[25] = (byte)(s.FindClassForDicing ? 1 : 0);
        BitConverter.GetBytes(s.BoundOnLootItemDistributionMethod).CopyTo(p, 26);
        p[30] = (byte)(s.ForbidLootingInBattle ? 1 : 0);
        return p;
    }

    static byte[] SaBypassToGroupPayload(long groupId, int groupType, int originatorDbId, byte[] clientPkt)
    {
        var p = new byte[0x22 - 6 + clientPkt.Length];
        BitConverter.GetBytes((uint)0x22).CopyTo(p, 0);
        BitConverter.GetBytes((uint)clientPkt.Length).CopyTo(p, 4);
        BitConverter.GetBytes(groupType).CopyTo(p, 8);
        BitConverter.GetBytes(groupId).CopyTo(p, 12);
        BitConverter.GetBytes(PartyManager.PlanetId).CopyTo(p, 20);
        BitConverter.GetBytes(originatorDbId).CopyTo(p, 24);
        clientPkt.CopyTo(p, 0x22 - 6);
        return p;
    }

    static readonly PartyPackets.LootSettings RoundRobinLoot = new(
        Method: 1, RareGradeForDicing: 4, RareItemDistributionMethod: 1,
        EquipmentForDicing: true, FindClassForDicing: false,
        BoundOnLootItemDistributionMethod: 1, ForbidLootingInBattle: true);

    static string Names(PartyActions a) =>
        string.Join(",", a.ToClients.Select(c => $"{c.Ticket}:{c.PacketName}"));
    static string WorldOps(PartyActions a) =>
        string.Join(",", a.ToWorld.Select(w => $"0x{w.Opcode:X4}"));

    [Test] public static void Party_id_has_the_planet_shape()
    {
        var pm = NewPartyManager();
        long first = pm.NextPartyId(), second = pm.NextPartyId();
        // (PlanetId << 16 | PlanetInnerId) << 32 | ++counter. PlanetId 2800 = 0x0AF0.
        Hex.True(first == 0x0AF0000100000001L, $"first party id should be 0x0AF0000100000001, got 0x{first:X}");
        Hex.True(second == 0x0AF0000100000002L, $"and then ...0002, got 0x{second:X}");
        Hex.True((int)(first >> 48) == PartyManager.PlanetId, "the top 16 bits are the PlanetId");
    }

    [Test] public static void Party_apply_needs_a_target_who_is_online_and_an_applicant_with_no_party()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test"));

        var self = pm.OnClientPacket(10, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(1));
        Hex.True(self.IsEmpty && self.Rejected != null, $"applying to yourself: {self.Rejected}");
        var gone = pm.OnClientPacket(10, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(99));
        Hex.True(gone.IsEmpty && gone.Rejected!.Contains("not online"), $"offline target: {gone.Rejected}");

        // The real answer is S_OTHER_USER_APPLY_PARTY to the TARGET, and nothing to World.
        var ok = pm.OnClientPacket(10, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(2));
        Hex.True(ok.ToWorld.Count == 0, "C_APPLY_PARTY never reaches World");
        Hex.True(ok.ToClients.Count == 1 && ok.ToClients[0].Ticket == 11
                 && ok.ToClients[0].PacketName == "S_OTHER_USER_APPLY_PARTY", Names(ok));
        Hex.True(pm.HasApplication(1, 2), "the pending application is recorded");

        var denied = pm.OnClientPacket(11, PartyManager.C_PARTY_APPLICATION_DENIED, BitConverter.GetBytes(1));
        Hex.True(denied.IsEmpty && denied.Rejected == null, "a decline is silent");
        Hex.True(!pm.HasApplication(1, 2), "and clears the edge");
    }

    [Test] public static void Party_join_creates_the_party_and_mirrors_the_whole_member_list()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test"));

        var a = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        // T64: AS_DO_CREATE_PARTY, then one 0x15CD and one 0x13AD per member - the order
        // cap_social.log seq 748..753 has them in.
        Hex.True(WorldOps(a) == "0x139E,0x15CD,0x15CD,0x13AD,0x13AD", WorldOps(a));
        Hex.True(a.ToClients.Count == 2 && a.ToClients.All(c => c.PacketName == "S_PARTY_MEMBER_LIST"), Names(a));

        // AS_DO_CREATE_PARTY: 0x32 fixed payload bytes then N x 0xA0 raw member records.
        var body = a.ToWorld[0].Payload;
        Hex.True(body.Length == 0x32 + 2 * PartyPackets.MemberBasicInfoSize, $"0x139E is 0x32+2*0xA0, got {body.Length}");
        Hex.True(BitConverter.ToUInt32(body, 4) == 2 * (uint)PartyPackets.MemberBasicInfoSize,
            "the list header is a BYTE LENGTH - T64, cap_social.log seq 748");
        var party = pm.FindByMember(1);
        Hex.True(party != null && BitConverter.ToInt64(body, 8) == party!.Id, "the PartyId matches the manager's");
        Hex.True(BitConverter.ToInt32(body, 0x18) == 1, "+1E ManagerDbId is the inviter, not the invitee");
        var m0 = PartyPackets.ParseMemberBasicInfo(body, 0x32);
        var m1 = PartyPackets.ParseMemberBasicInfo(body, 0x32 + PartyPackets.MemberBasicInfoSize);
        Hex.True(m0!.Value.Name == "dob" && m1!.Value.Name == "Test", $"{m0?.Name}/{m1?.Name} in slot order");
        Hex.True(m0!.Value.CanInvite && !m1!.Value.CanInvite, "only the manager carries AuthorityAboutInvitation");

        // A second join adds one member rather than recreating the party.
        pm.Register(P(12, 3, "Testtwo"));
        var b = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 3));
        Hex.True(b.ToWorld.Count == 1 && b.ToWorld[0].Opcode == PartyPackets.AS_DO_ADD_PARTY_MEMBER, WorldOps(b));
        Hex.True(b.ToClients.Count == 3, $"all three get the refreshed list: {Names(b)}");
        Hex.True(pm.FindByMember(3)!.Id == party!.Id, "and they are in the same party");
    }

    [Test] public static void Party_join_is_refused_when_the_invitee_already_has_a_party()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test")); pm.Register(P(12, 3, "Testtwo"));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        var again = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(3, 2));
        Hex.True(again.IsEmpty && again.Rejected!.Contains("already in a party"), $"{again.Rejected}");
        Hex.True(pm.PartyCount == 1, $"no second party was made: {pm.PartyCount}");
    }

    [Test] public static void Party_slot_indices_are_stable_and_capacity_is_5_then_30()
    {
        var pm = NewPartyManager();
        for (int i = 1; i <= 6; i++) pm.Register(P((uint)(10 + i), i, "p" + i));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        var party = pm.FindByMember(1)!;
        for (int i = 3; i <= 5; i++) pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, i));
        Hex.True(party.Count == 5, $"a party holds 5, has {party.Count}");

        var full = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 6));
        Hex.True(full.Rejected != null && full.Rejected.Contains("full"), $"the sixth is refused: {full.Rejected}");

        // Slot indices are wire-visible (S_PARTY_MEMBER_LIST.slot, AS_DO_SWAP_PARTY) so a
        // departure must leave a hole, not shuffle everyone up.
        int slotOf5 = party.IndexOf(5);
        pm.OnWorldFrame(PartyPackets.SA_LEAVE_PARTY, SaLeavePartyPayload(party.Id, 3));
        Hex.True(party.IndexOf(5) == slotOf5, "slot indices do not shift when someone leaves");
        Hex.True(party.Slots[2] == null, "the vacated slot stays empty");

        pm.OnWorldFrame(PartyPackets.SA_EXTEND_PARTY, SaExtendPartyPayload(1, raid: true));
        Hex.True(party.Raid && party.MaxMembers == 30, $"a raid holds 30, MaxMembers={party.MaxMembers}");
    }

    [Test] public static void Party_dismiss_is_manager_only_and_needs_Worlds_blessing()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test"));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));

        var notManager = pm.OnClientPacket(11, PartyPackets.C_DISMISS_PARTY, Array.Empty<byte>());
        Hex.True(notManager.IsEmpty && notManager.Rejected!.Contains("manager"), $"{notManager.Rejected}");

        // The manager's request is exactly AS_DISMISS_PARTY [i64 UserPDId][i32 onlineCount] -
        // a REQUEST; nothing changes until World answers.
        var req = pm.OnClientPacket(10, PartyPackets.C_DISMISS_PARTY, Array.Empty<byte>());
        Hex.True(req.ToClients.Count == 0, "the request tells no client anything");
        Hex.Eq(req.ToWorld[0].Payload, "F0 0A 00 00 01 00 00 00  02 00 00 00", "AS_DISMISS_PARTY");
        Hex.True(pm.PartyCount == 1, "and the party still exists");

        var done = pm.OnWorldFrame(PartyPackets.SA_DISMISS_PARTY, SaPartyActorPayload(1));
        Hex.True(done.ToClients.Count == 2 && done.ToClients.All(c => c.PacketName == "S_LEAVE_PARTY"), Names(done));
        Hex.True(done.ToWorld.Count == 1 && done.ToWorld[0].Opcode == PartyPackets.AS_DO_DISMISS_PARTY, WorldOps(done));
        Hex.True(pm.PartyCount == 0 && pm.FindByMember(1) == null, "the party is gone");
    }

    [Test] public static void Party_last_member_standing_dissolves_the_party()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test"));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        var id = pm.FindByMember(1)!.Id;

        // PartyManager::New_CreateParty refuses fewer than two members, so one is not a party.
        var a = pm.OnWorldFrame(PartyPackets.SA_LEAVE_PARTY, SaLeavePartyPayload(id, 2));
        Hex.True(a.ToClients.Any(c => c.Ticket == 11 && c.PacketName == "S_LEAVE_PARTY"), Names(a));
        Hex.True(a.ToClients.Any(c => c.Ticket == 10 && c.PacketName == "S_LEAVE_PARTY_MEMBER"), Names(a));
        Hex.True(a.ToClients.Any(c => c.Ticket == 10 && c.PacketName == "S_LEAVE_PARTY"), "and the survivor is dropped too");
        Hex.True(a.ToWorld.Select(w => w.Opcode).SequenceEqual(new[]
            { PartyPackets.AS_DO_REMOVE_PARTY_MEMBER, PartyPackets.AS_DO_DISMISS_PARTY }), WorldOps(a));
        Hex.True(pm.PartyCount == 0, "the party is gone");
    }

    [Test] public static void Party_offline_member_keeps_the_slot()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test")); pm.Register(P(12, 3, "Testtwo"));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 3));
        var party = pm.FindByMember(1)!;
        int slot = party.IndexOf(3);

        // PartyMemberInfo+0x70 is an Online flag, not a removal.
        var bye = pm.Unregister(12);
        Hex.True(party.IndexOf(3) == slot && party.Count == 3, "the member keeps the slot");
        Hex.True(party.Slots[slot]!.Value.Online == false, "but is marked offline");
        Hex.True(bye.ToClients.Count == 2 && bye.ToClients.All(c => c.PacketName == "S_LOGOUT_PARTY_MEMBER"), Names(bye));

        pm.Register(P(20, 3, "Testtwo"));
        Hex.True(party.Slots[slot]!.Value.Online, "coming back online restores the flag");
    }

    [Test] public static void Party_bypass_to_group_fans_out_and_skips_the_originator()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test")); pm.Register(P(12, 3, "Testtwo"));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 3));
        var id = pm.FindByMember(1)!.Id;
        var pkt = Hex.B("08 00 6B 7D 01 02 03 04");     // an S_CHAT-shaped stand-in

        // Party::BroadcastPacket skips the originator unless GroupType == 1:
        //   if (param_2 != 1) { if (planet == param_3 && db == param_4) goto skip; }
        var skip = pm.OnWorldFrame(PartyPackets.SA_BYPASS_TO_GROUP, SaBypassToGroupPayload(id, 0, 1, pkt));
        Hex.True(skip.ToWorld.Count == 0, "a fan-out never goes back to World");
        Hex.True(skip.ToClients.Count == 2 && skip.ToClients.All(c => c.IsRaw), Names(skip));
        Hex.True(skip.ToClients.Select(c => c.Ticket).OrderBy(x => x).SequenceEqual(new uint[] { 11, 12 }),
            "everyone but the originator");
        Hex.Eq(skip.ToClients[0].RawPacket!, pkt, "the packet is passed through untouched");

        var all = pm.OnWorldFrame(PartyPackets.SA_BYPASS_TO_GROUP, SaBypassToGroupPayload(id, 1, 1, pkt));
        Hex.True(all.ToClients.Count == 3, $"GroupType 1 includes the originator: {Names(all)}");

        var nobody = pm.OnWorldFrame(PartyPackets.SA_BYPASS_TO_GROUP, SaBypassToGroupPayload(0x1234, 0, 1, pkt));
        Hex.True(nobody.IsEmpty && nobody.Rejected!.Contains("no party"), $"{nobody.Rejected}");

        // An offline member simply has nowhere to send to.
        pm.Unregister(12);
        var two = pm.OnWorldFrame(PartyPackets.SA_BYPASS_TO_GROUP, SaBypassToGroupPayload(id, 1, 1, pkt));
        Hex.True(two.ToClients.Count == 2, $"offline members are skipped: {Names(two)}");
    }

    [Test] public static void Party_end_to_end_invite_accept_loot_leave_dismiss()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test")); pm.Register(P(12, 3, "Testtwo"));
        var log = new List<string>();
        void Step(string what, PartyActions a)
        {
            Hex.True(a.Rejected == null, $"{what} rejected: {a.Rejected}");
            log.Add($"{what} -> [{Names(a)}] [{WorldOps(a)}]");
        }

        // 1. Test applies to dob. Arbiter-only; the target gets S_OTHER_USER_APPLY_PARTY.
        Step("apply", pm.OnClientPacket(11, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(1)));
        // 2. dob accepts -> World completes the handshake and tells us.
        Step("accept", pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2)));
        var party = pm.FindByMember(1)!;
        Step("accept2", pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 3)));
        // 3. The manager asks for round-robin; World has to agree.
        Step("loot-request", pm.OnClientPacket(10, PartyPackets.C_PARTY_LOOTING_METHOD,
            PartyPackets.BuildSPartyLootingMethodBody(RoundRobinLoot)));
        Step("loot-applied", pm.OnWorldFrame(PartyPackets.SA_CHANGE_LOOTING_METHOD,
            SaChangeLootingPayload(1, RoundRobinLoot)));
        // 4. Testtwo leaves; the party survives with two.
        Step("leave", pm.OnWorldFrame(PartyPackets.SA_LEAVE_PARTY, SaLeavePartyPayload(party.Id, 3)));
        // 5. dob dismisses.
        Step("dismiss-request", pm.OnClientPacket(10, PartyPackets.C_DISMISS_PARTY, Array.Empty<byte>()));
        Step("dismiss", pm.OnWorldFrame(PartyPackets.SA_DISMISS_PARTY, SaPartyActorPayload(1)));

        var expected = new[]
        {
            "apply -> [10:S_OTHER_USER_APPLY_PARTY] []",
            "accept -> [10:S_PARTY_MEMBER_LIST,11:S_PARTY_MEMBER_LIST] [0x139E,0x15CD,0x15CD,0x13AD,0x13AD]",
            "accept2 -> [10:S_PARTY_MEMBER_LIST,11:S_PARTY_MEMBER_LIST,12:S_PARTY_MEMBER_LIST] [0x139F]",
            "loot-request -> [] [0x13BB]",
            "loot-applied -> [10:S_PARTY_LOOTING_METHOD,11:S_PARTY_LOOTING_METHOD,12:S_PARTY_LOOTING_METHOD] [0x13A6]",
            "leave -> [12:S_LEAVE_PARTY,10:S_LEAVE_PARTY_MEMBER,11:S_LEAVE_PARTY_MEMBER,10:S_PARTY_MEMBER_LIST,11:S_PARTY_MEMBER_LIST] [0x13A0]",
            "dismiss-request -> [] [0x13BA]",
            "dismiss -> [10:S_LEAVE_PARTY,11:S_LEAVE_PARTY] [0x13A1]",
        };
        for (int i = 0; i < expected.Length; i++)
            Hex.True(log[i] == expected[i], $"step {i}\n   expected: {expected[i]}\n   actual:   {log[i]}");
        Hex.True(pm.PartyCount == 0, "and nothing is left behind");
        Hex.True(party.Loot == RoundRobinLoot, "the loot settings were applied when World agreed, not before");
    }

    [Test] public static void Party_end_to_end_client_packets_go_through_the_real_def_codec()
    {
        var defs = LoadDefinitionsOrSkip();
        if (defs == null) return;

        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob")); pm.Register(P(11, 2, "Test"));
        var all = new List<ClientAction>();
        all.AddRange(pm.OnClientPacket(11, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(1)).ToClients);
        var join = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        all.AddRange(join.ToClients);
        all.AddRange(pm.OnWorldFrame(PartyPackets.SA_CHANGE_LOOTING_METHOD,
            SaChangeLootingPayload(1, RoundRobinLoot)).ToClients);
        var party = pm.FindByMember(1)!;
        all.AddRange(pm.OnWorldFrame(PartyPackets.SA_DISMISS_PARTY, SaPartyActorPayload(1)).ToClients);

        // Every def-driven action must survive the real writer, and the ones with a reader-safe
        // shape must round-trip back to the same values.
        foreach (var c in all)
        {
            if (c.IsRaw) continue;
            var def = defs.Get(c.PacketName);
            Hex.True(def != null, $"no def for {c.PacketName} - the wiring would log and drop it");
            var bytes = new TeraSharp.Arbiter.Protocol.DefinitionWriter().Write(def!, c.Fields!);
            Hex.True(bytes.Length >= 0, $"{c.PacketName} wrote {bytes.Length} bytes");
            var back = new TeraSharp.Arbiter.Protocol.DefinitionReader(bytes).Read(def!);
            Hex.True(back != null, $"{c.PacketName} did not read back");
        }

        // S_PARTY_LOOTING_METHOD is seven scalars with no ref block, so its bytes are pinned.
        var loot = all.First(c => c.PacketName == "S_PARTY_LOOTING_METHOD");
        var lootBytes = new TeraSharp.Arbiter.Protocol.DefinitionWriter()
            .Write(defs.Get("S_PARTY_LOOTING_METHOD")!, loot.Fields!);
        Hex.Eq(lootBytes, PartyPackets.BuildSPartyLootingMethodBody(RoundRobinLoot),
            "the codec and PartyPackets agree on S_PARTY_LOOTING_METHOD");

        // S_PARTY_MEMBER_LIST has the array; check the fields survive the trip.
        var listAction = join.ToClients.First(c => c.PacketName == "S_PARTY_MEMBER_LIST");
        var listDef = defs.Get("S_PARTY_MEMBER_LIST")!;
        var listBytes = new TeraSharp.Arbiter.Protocol.DefinitionWriter().Write(listDef, listAction.Fields!);
        var read = new TeraSharp.Arbiter.Protocol.DefinitionReader(listBytes).Read(listDef);
        Hex.True(Convert.ToUInt64(read["id"]) == (ulong)party.Id, $"id round-tripped: {read["id"]}");
        Hex.True(Convert.ToUInt32(read["memberLimit"]) == 5, $"memberLimit: {read["memberLimit"]}");
        var members = (System.Collections.IList)read["members"];
        Hex.True(members.Count == 2, $"two members read back, got {members.Count}");
    }


    // =======================================================================================
    // T36 - the guild codec. Research: status/GUILD-DESIGN.md.
    //
    // No guild has ever existed on the tap, so there is exactly one byte of guild ground truth
    // in the captures: the empty DBS_INIT_GUILD_DATA the real Arbiter answers World's
    // SDB_INIT_GUILD with (data/cap_guild.bin). Everything else here is pinned against the
    // Arbiter's own PDL dumper guards and writers, which is what the .def corrections rest on.
    // =======================================================================================

    /// <summary>
    /// Two independent facts about the split: no two guild opcodes collide (a copy/paste in a
    /// 70-constant block is otherwise invisible), and MinClientLength answers 0 for exactly the
    /// ten guild C_ packets WorldServer owns - answering one of those in the Arbiter would
    /// double-handle it, because World answers it too.
    /// </summary>
    [Test] public static void Guild_opcode_table_is_consistent_with_the_arbiter_world_split()
    {
        ushort[] worldSide =
        {
            GuildPackets.C_LEAVE_GUILD, GuildPackets.C_BANISH_GUILD_MEMBER, GuildPackets.C_DESTROY_GUILD,
            GuildPackets.C_CHANGE_GUILD_CHIEF, GuildPackets.C_CREATE_GUILDGROUP, GuildPackets.C_CHANGE_GUILDGROUP,
            GuildPackets.C_REMOVE_GUILDGROUP, GuildPackets.C_SET_GUILDGROUP_AUTHORITY,
            GuildPackets.C_CHECK_NEW_GUILDNAME, GuildPackets.C_REQUEST_USABLE_GUILD_NAME,
        };
        foreach (var op in worldSide)
            Hex.True(!GuildPackets.ArbiterHandlesClientPacket(op),
                $"0x{op:X4} is a WorldServer-side guild packet - the Arbiter must tunnel it, not answer it");

        ushort[] arbiterSide =
        {
            GuildPackets.C_APPLY_GUILD, GuildPackets.C_ACCEPT_GUILD_APPLY, GuildPackets.C_GUILD_APPLY_LIST,
            GuildPackets.C_GUILD_APPLY_LIST_PAGE, GuildPackets.C_INVITE_USER_TO_GUILD,
            GuildPackets.C_REJECT_INVITE_USER_TO_GUILD, GuildPackets.C_CHANGE_GUILDNAME,
            GuildPackets.C_CHECK_CHANGE_GUILDNAME, GuildPackets.C_UPDATE_GUILD_LOGO,
            GuildPackets.C_GET_USER_GUILD_LOGO, GuildPackets.C_UPDATE_GUILD_TITLE,
            GuildPackets.C_REQUEST_GUILD_INFO, GuildPackets.C_REQUEST_GUILD_MEMBER_LIST,
            GuildPackets.C_GET_GUILD_HISTORY, GuildPackets.C_SET_GUILD_JOIN_CONDITION,
            GuildPackets.C_REQUEST_GUILD_INFO_BEFORE_APPLY_GUILD, GuildPackets.C_REQUEST_COOLTIME_TO_JOIN_GUILD,
        };
        foreach (var op in arbiterSide)
            Hex.True(GuildPackets.ArbiterHandlesClientPacket(op), $"0x{op:X4} has an Arbiter handler");

        var all = new List<ushort>();
        all.AddRange(worldSide);
        all.AddRange(arbiterSide);
        foreach (var f in typeof(GuildPackets).GetFields(
                     System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static))
            if (f.IsLiteral && f.FieldType == typeof(ushort) &&
                (f.Name.StartsWith("S_") || f.Name.StartsWith("AS_") || f.Name.StartsWith("SA_") ||
                 f.Name.StartsWith("DBS_") || f.Name.StartsWith("SDB_")))
                all.Add((ushort)f.GetRawConstantValue()!);

        var seen = new HashSet<ushort>();
        foreach (var op in all)
            Hex.True(seen.Add(op), $"guild opcode 0x{op:X4} is declared twice");
        Hex.True(all.Count >= 70, $"expected the full guild opcode table, got {all.Count}");
    }

    /// <summary>
    /// The SA_ guild handlers kill the link on a short frame ("Arbiter &lt;-&gt; World PDL Version
    /// Mismatch! Bye :(") exactly like the party ones, so the sizes have to be the handler's.
    /// Our parsers return null one byte below and succeed at the documented size.
    /// </summary>
    [Test] public static void Guild_SA_frame_sizes_are_the_handler_guards()
    {
        (ushort op, int frame)[] want =
        {
            (GuildPackets.SA_LOAD_GUILD, 0x12), (GuildPackets.SA_DESTROY_GUILD, 0x12),
            (GuildPackets.SA_LEAVE_GUILD, 0x1A), (GuildPackets.SA_BANISH_GUILD_MEMBER, 0x1A),
            (GuildPackets.SA_CHANGE_GUILD_CHIEF, 0x16), (GuildPackets.SA_SET_GUILDGROUP_AUTHORITY, 0x1E),
            (GuildPackets.SA_CREATE_GUILD_GROUP, 0x16), (GuildPackets.SA_REMOVE_GUILD_GROUP, 0x16),
            (GuildPackets.SA_CHANGE_GUILDGROUP, 0x1A), (GuildPackets.SA_UPDATE_GUILD_MEMBER, 0x0E),
        };
        foreach (var (op, frame) in want)
            Hex.True(GuildPackets.MinFrameLength(op) == frame,
                $"0x{op:X4} min frame 0x{GuildPackets.MinFrameLength(op):X2} != 0x{frame:X2}");

        // one byte short of the payload the guard implies -> null, not an exception
        Hex.True(GuildPackets.ParseSaGuildAction(new byte[11]) == null, "SA_LOAD_GUILD short frame rejected");
        Hex.True(GuildPackets.ParseSaGuildAction(new byte[12]) != null, "SA_LOAD_GUILD exact frame accepted");
        Hex.True(GuildPackets.ParseSaLeaveGuild(new byte[19]) == null, "SA_LEAVE_GUILD short frame rejected");
        Hex.True(GuildPackets.ParseSaChangeGuildChief(new byte[15]) == null, "SA_CHANGE_GUILD_CHIEF short frame rejected");
        Hex.True(GuildPackets.ParseSaSetGuildGroupAuthority(new byte[23]) == null, "SA_SET_GUILDGROUP_AUTHORITY short frame rejected");
        Hex.True(GuildPackets.ParseSaChangeGuildGroup(new byte[19]) == null, "SA_CHANGE_GUILDGROUP short frame rejected");
        Hex.True(GuildPackets.ParseSaUpdateGuildMember(new byte[7]) == null, "SA_UPDATE_GUILD_MEMBER short frame rejected");
    }

    /// <summary>SA_LEAVE_GUILD / SA_BANISH_GUILD_MEMBER: the name offset comes FIRST, before the
    /// i64 ArbiterUser, and it is frame-relative - payload index = frame offset - 6.</summary>
    [Test] public static void Guild_SA_LEAVE_GUILD_reads_the_documented_offsets()
    {
        var name = "Banished";
        var p = new byte[20 + (name.Length + 1) * 2];
        BitConverter.GetBytes(6 + 20).CopyTo(p, 0);              // frame 0x1A
        BitConverter.GetBytes(0x0AF0000100000002L).CopyTo(p, 4);
        BitConverter.GetBytes(7).CopyTo(p, 12);
        BitConverter.GetBytes(11).CopyTo(p, 16);
        for (int i = 0; i < name.Length; i++)
        {
            p[20 + i * 2] = (byte)name[i];
            p[21 + i * 2] = (byte)(name[i] >> 8);
        }
        var got = GuildPackets.ParseSaLeaveGuild(p);
        Hex.True(got != null, "SA_LEAVE_GUILD parsed");
        Hex.True(got!.Value.memberName == name, $"memberName '{got.Value.memberName}' != '{name}'");
        Hex.True(got.Value.arbiterUser == 0x0AF0000100000002L, "arbiterUser @frame 0x0A");
        Hex.True(got.Value.guildDbId == 7 && got.Value.memberDbId == 11, "guildDbId @0x12, memberDbId @0x16");
    }

    /// <summary>S_ADD_GUILD_GROUP and S_UPDATE_GUILD_GROUP are byte-identical: one ref slot,
    /// two i32, fixed part 0x0E.</summary>
    [Test] public static void Guild_S_ADD_GUILD_GROUP_body_layout()
    {
        var b = GuildPackets.BuildSGuildGroupBody(3, 0x7F, "Officer");
        Hex.True(BitConverter.ToUInt16(b, 0) == 0x0E, $"name ref = 0x{BitConverter.ToUInt16(b, 0):X2}, want 0x0E");
        Hex.True(BitConverter.ToInt32(b, 2) == 3, "GroupId @packet 0x06");
        Hex.True(BitConverter.ToInt32(b, 6) == 0x7F, "Authority @packet 0x0A");
        Hex.True(b.Length == 0x0E - 4 + ("Officer".Length + 1) * 2, $"body length {b.Length}");
    }

    /// <summary>
    /// S_ADD_GUILD_MEMBER.1.def computes 0x33; the dumper guard (Arb_part_018.c:6159,
    /// `if (0x37 &lt; param_2)`) says 0x38. The .def is missing `int32 gender` at 0x2A and the
    /// trailing `byte cityWarCompensationStatus`. This pins both.
    /// </summary>
    [Test] public static void Guild_S_ADD_GUILD_MEMBER_has_gender_and_a_second_trailing_bool()
    {
        var m = new GuildPackets.GuildMemberWire(11, "dob", 1, 2, 3, 4, 60, 5, 6, 1, 0,
            0x1122334455667788L, true, false, false);
        var b = GuildPackets.BuildSAddGuildMemberBody(m);
        Hex.True(BitConverter.ToUInt16(b, 0) == 0x38, $"fixed part 0x{BitConverter.ToUInt16(b, 0):X2}, want 0x38");
        Hex.True(BitConverter.ToInt32(b, 0x26 - 4) == 0, "State @packet 0x26");
        Hex.True(BitConverter.ToInt32(b, 0x2A - 4) == 1, "gender @packet 0x2A - the field the .def drops");
        Hex.True(BitConverter.ToInt64(b, 0x2E - 4) == 0x1122334455667788L, "LastLogoutTime @packet 0x2E");
        Hex.True(b[0x36 - 4] == 1 && b[0x37 - 4] == 0, "IsWorldEventTarget @0x36, CityWarCompensationStatus @0x37");
        Hex.True(b.Length >= 0x38 - 4, "body reaches the documented fixed size");
    }

    /// <summary>
    /// S_UPDATE_GUILD_MEMBER is S_ADD_GUILD_MEMBER plus `bool IsInGuildWarCombatState` in the
    /// middle of the trailer: three bools, fixed part 0x39 (dumper guard `0x38 &lt; param_2`).
    /// The .def has two and computes 0x38.
    /// </summary>
    [Test] public static void Guild_S_UPDATE_GUILD_MEMBER_has_three_trailing_bools()
    {
        var m = new GuildPackets.GuildMemberWire(11, "dob", 1, 2, 3, 4, 60, 5, 6, 1, 0,
            0L, true, false, true);
        var b = GuildPackets.BuildSUpdateGuildMemberBody(m);
        Hex.True(b.Length + 4 == 0x39, $"fixed part 0x{b.Length + 4:X2}, want 0x39");
        Hex.True(b[0x36 - 4] == 1, "IsWorldEventTarget @0x36");
        Hex.True(b[0x37 - 4] == 1, "IsInGuildWarCombatState @0x37 - the byte the .def drops");
        Hex.True(b[0x38 - 4] == 0, "CityWarCompensationStatus @0x38");
    }

    /// <summary>
    /// A `bytes` field reserves TWO slots in the order (offset, count) - the reverse of an
    /// array's (count, offset). S_GET_USER_GUILD_LOGO is the proof: Arb_part_046.c:12743-12744
    /// writes the cursor into the first slot and the length into the second.
    /// </summary>
    [Test] public static void Guild_bytes_header_is_offset_then_count()
    {
        var logo = new byte[20];
        for (int i = 0; i < logo.Length; i++) logo[i] = (byte)i;
        var b = GuildPackets.BuildSGetUserGuildLogoBody(7, 9, logo);
        Hex.True(BitConverter.ToUInt16(b, 0) == 0x10, $"logo offset = 0x{BitConverter.ToUInt16(b, 0):X2}, want 0x10");
        Hex.True(BitConverter.ToUInt16(b, 2) == 20, "logo count = 20");
        Hex.True(BitConverter.ToInt32(b, 4) == 7 && BitConverter.ToInt32(b, 8) == 9,
            "UserDbId @packet 0x08, GuildDbId @packet 0x0C");
        Hex.Eq(b[12..32], logo, "the logo bytes sit at the advertised offset");
    }

    /// <summary>S_GUILD_APPLY_LIST: fixed part 0x11, element stride 0x1C, and the last element's
    /// `next` is 0. The per-element strings sit between one element and the next, which is what
    /// makes the stride check meaningful.</summary>
    [Test] public static void Guild_S_GUILD_APPLY_LIST_element_stride_is_0x1C()
    {
        var rows = new List<GuildPackets.GuildApplyRow>
        {
            new(101, 2, 60, 1700000000L, "alice", "hi"),
            new(102, 3, 55, 1700000001L, "bob", "me too"),
        };
        var b = GuildPackets.BuildSGuildApplyListBody(true, 1, 1, rows);
        Hex.True(BitConverter.ToUInt16(b, 0) == 2, "array count slot @packet 0x04");
        int arr = BitConverter.ToUInt16(b, 2);
        Hex.True(arr == 0x11, $"array offset 0x{arr:X2} == fixed part 0x11");
        Hex.True(b[4] == 1, "InviteAuthority @packet 0x08");
        Hex.True(BitConverter.ToInt32(b, 5) == 1 && BitConverter.ToInt32(b, 9) == 1, "CurPageNum @0x09, TotalPageCount @0x0D");

        int e0 = arr - 4;
        Hex.True(BitConverter.ToUInt16(b, e0) == arr, "element 0 self-offset");
        int next = BitConverter.ToUInt16(b, e0 + 2);
        int expectedSpan = 0x1C + ("alice".Length + 1) * 2 + ("hi".Length + 1) * 2;
        Hex.True(next - arr == expectedSpan, $"element 0 spans {next - arr}, want stride 0x1C + both strings ({expectedSpan})");
        Hex.True(BitConverter.ToInt32(b, e0 + 8) == 101, "UserDbId @element+0x08");
        Hex.True(BitConverter.ToInt64(b, e0 + 0x14) == 1700000000L, "DateTime @element+0x14");
        Hex.True(BitConverter.ToUInt16(b, next - 4 + 2) == 0, "the last element's next is 0");
    }

    /// <summary>S_GUILD_HISTORY: fixed part 0x10, element stride 0x14.</summary>
    [Test] public static void Guild_S_GUILD_HISTORY_element_stride_is_0x14()
    {
        var rows = new List<GuildPackets.GuildHistoryRow>
        {
            new(5L, 11, "dob", "@guild:11"),
            new(6L, 12, "eve", "@guild:12"),
        };
        var b = GuildPackets.BuildSGuildHistoryBody(1, 3, rows);
        Hex.True(BitConverter.ToUInt16(b, 0) == 2, "array count");
        int arr = BitConverter.ToUInt16(b, 2);
        Hex.True(arr == 0x10, $"array offset 0x{arr:X2} == fixed part 0x10");
        Hex.True(BitConverter.ToInt32(b, 4) == 1 && BitConverter.ToInt32(b, 8) == 3, "ViewPage @0x08, LastPage @0x0C");
        int e0 = arr - 4;
        int next = BitConverter.ToUInt16(b, e0 + 2);
        int expectedSpan = 0x14 + ("dob".Length + 1) * 2 + ("@guild:11".Length + 1) * 2;
        Hex.True(next - arr == expectedSpan, $"element 0 spans {next - arr}, want {expectedSpan}");
        Hex.True(BitConverter.ToInt64(b, e0 + 8) == 5L && BitConverter.ToInt32(b, e0 + 0x10) == 11,
            "LogTime @element+0x08, ActionType @element+0x10");
    }

    /// <summary>An empty array writes count 0 AND offset 0 - not a dangling offset past the end,
    /// which is what a naive writer produces and what makes the client walk into the strings.</summary>
    [Test] public static void Guild_empty_array_writes_count_zero_and_offset_zero()
    {
        var b = GuildPackets.BuildSGuildApplyListBody(false, 1, 1, new List<GuildPackets.GuildApplyRow>());
        Hex.True(BitConverter.ToUInt16(b, 0) == 0, "count 0");
        Hex.True(BitConverter.ToUInt16(b, 2) == 0, "offset 0");
        Hex.True(b.Length + 4 == 0x11, $"fixed part 0x{b.Length + 4:X2}, want 0x11");
    }

    /// <summary>
    /// Inter-server string offsets are FRAME-relative, not payload-relative. Proof is in the
    /// capture: the DBS_INIT_GUILD_DATA in data/cap_guild.bin advertises its blob at 19 and the
    /// blob starts at payload index 13, i.e. 19 - 6.
    /// </summary>
    [Test] public static void Guild_AS_frames_use_frame_relative_string_offsets()
    {
        var p = GuildPackets.BuildAsGuildString(42, "LOGO-7");
        Hex.True(BitConverter.ToInt32(p, 0) == 0x0E, $"string offset 0x{BitConverter.ToInt32(p, 0):X2}, want frame 0x0E");
        Hex.True(BitConverter.ToInt32(p, 4) == 42, "GuildDbId @frame 0x0A");
        Hex.Eq(p[8..20], System.Text.Encoding.Unicode.GetBytes("LOGO-7"), "the wstring sits at the advertised frame offset");

        var g = GuildPackets.BuildAsCreateGuildGroup(42, 3, "Officer", 0x7F);
        Hex.True(BitConverter.ToInt32(g, 0) == 0x16, $"group name offset 0x{BitConverter.ToInt32(g, 0):X2}, want frame 0x16");
        Hex.True(BitConverter.ToInt32(g, 8) == 3 && BitConverter.ToInt32(g, 12) == 0x7F,
            "GuildGroupId @frame 0x0E, Authority @frame 0x12");
    }

    /// <summary>AS_ADD_GUILDMEMBER's fixed part is 0x4F: eleven i32, an i64, a bool and two more
    /// i64 - the .def stops after logoutTime/accountDbId and misses isWorldEventTarget (0x3E)
    /// and lastJoinGuildTime (0x47).</summary>
    [Test] public static void Guild_AS_ADD_GUILDMEMBER_fixed_part_is_0x4F()
    {
        var p = GuildPackets.BuildAsAddGuildMember(42, 11, "dob", 1, 2, 3, 60, 5, 6, 1, 0, 4,
            7L, true, 99L, 123L);
        Hex.True(BitConverter.ToInt32(p, 0) == 0x4F, $"name offset 0x{BitConverter.ToInt32(p, 0):X2}, want frame 0x4F");
        Hex.True(BitConverter.ToInt32(p, 0x2A - 6) == 1, "gender @frame 0x2A");
        Hex.True(BitConverter.ToInt64(p, 0x36 - 6) == 7L, "LogoutTime @frame 0x36");
        Hex.True(p[0x3E - 6] == 1, "IsWorldEventTarget @frame 0x3E");
        Hex.True(BitConverter.ToInt64(p, 0x3F - 6) == 99L, "AccountDbId @frame 0x3F");
        Hex.True(BitConverter.ToInt64(p, 0x47 - 6) == 123L, "LastJoinGuildTime @frame 0x47");
    }

    /// <summary>AS_LOAD_GUILD_DATA / AS_UPDATE_GUILD_DATA carry the raw 0x23A0-byte record, not a
    /// wstring: the writer reserves an (offset, count) pair and calls the raw-bytes helper.</summary>
    [Test] public static void Guild_AS_LOAD_GUILD_DATA_carries_the_raw_blob()
    {
        var blob = GuildPackets.BuildEmptyGuildDataBlob();
        Hex.True(blob.Length == GuildPackets.GuildDataSize, $"GuildData is 0x{blob.Length:X4}, want 0x23A0");
        var p = GuildPackets.BuildAsGuildData(blob);
        Hex.True(BitConverter.ToInt32(p, 0) == 0x0E, "blob offset == frame 0x0E");
        Hex.True(BitConverter.ToInt32(p, 4) == GuildPackets.GuildDataSize, "blob length == 0x23A0");
        Hex.Eq(p[8..], blob, "the blob is copied through unchanged");
    }

    /// <summary>Every Arbiter-side client parser answers a short body with null instead of
    /// throwing - the real handler logs GET_CLIENT_BUFFER_BUFSIZE_MISMATCH and drops it.</summary>
    [Test] public static void Guild_client_parsers_reject_short_bodies()
    {
        Hex.True(GuildPackets.ParseCApplyGuild(new byte[3]) == null, "C_APPLY_GUILD short");
        Hex.True(GuildPackets.ParseCAcceptGuildApply(new byte[4]) == null, "C_ACCEPT_GUILD_APPLY short");
        Hex.True(GuildPackets.ParseCInviteUserToGuild(new byte[6]) == null, "C_INVITE_USER_TO_GUILD short");
        Hex.True(GuildPackets.ParseCGetUserGuildLogo(new byte[7]) == null, "C_GET_USER_GUILD_LOGO short");
        Hex.True(GuildPackets.ParseCRequestGuildInfo(new byte[7]) == null, "C_REQUEST_GUILD_INFO short");
        Hex.True(GuildPackets.ParseCSetGuildJoinCondition(new byte[0x11]) == null, "C_SET_GUILD_JOIN_CONDITION short");
        Hex.True(GuildPackets.ParseCRequestGuildInfoBeforeApply(new byte[5]) == null, "C_REQUEST_GUILD_INFO_BEFORE_APPLY short");
        Hex.True(GuildPackets.ParseCUpdateGuildLogo(new byte[3]) == null, "C_UPDATE_GUILD_LOGO short");

        // and the exact minimum is accepted
        Hex.True(GuildPackets.ParseCAcceptGuildApply(new byte[5]) != null, "C_ACCEPT_GUILD_APPLY at 9 total");
        Hex.True(GuildPackets.ParseCInviteUserToGuild(new byte[7]) != null, "C_INVITE_USER_TO_GUILD at 0x0B total");
        Hex.True(GuildPackets.ParseCSetGuildJoinCondition(new byte[0x12]) != null, "C_SET_GUILD_JOIN_CONDITION at 0x16 total");
    }

    /// <summary>
    /// C_UPDATE_GUILD_LOGO.1.def says `string logoImage`, which would make the packet 6 bytes.
    /// The handler (FUN_1404f1010) demands 8 and passes `param_2[3]` - the u16 at packet 0x06 -
    /// to Guild::UpdateGuildLogo as the byte COUNT, rejecting `8000 &lt; len`. It is a bytes field.
    /// </summary>
    [Test] public static void Guild_C_UPDATE_GUILD_LOGO_is_a_bytes_field_not_a_string()
    {
        Hex.True(GuildPackets.MinClientLength(GuildPackets.C_UPDATE_GUILD_LOGO) == 8,
            "the handler's guard is 8, which a single string ref cannot reach");

        var logo = new byte[64];
        for (int i = 0; i < logo.Length; i++) logo[i] = (byte)(i * 3);
        var body = new byte[4 + logo.Length];
        BitConverter.GetBytes((ushort)(4 + 4)).CopyTo(body, 0);   // packet offset of the data
        BitConverter.GetBytes((ushort)logo.Length).CopyTo(body, 2);
        logo.CopyTo(body, 4);
        var got = GuildPackets.ParseCUpdateGuildLogo(body);
        Hex.True(got != null, "logo parsed");
        Hex.Eq(got!, logo, "logo bytes round-trip");

        // the 8000-byte cap the real handler enforces before it binds the varbinary
        var tooBig = new byte[4];
        BitConverter.GetBytes((ushort)8).CopyTo(tooBig, 0);
        BitConverter.GetBytes((ushort)(GuildPackets.GuildLogoMaxBytes + 1)).CopyTo(tooBig, 2);
        Hex.True(GuildPackets.ParseCUpdateGuildLogo(tooBig) == null, "a logo over 8000 bytes is refused");
    }

    /// <summary>C_SET_GUILD_JOIN_CONDITION carries five fields, not four: the .def's `message`
    /// ref lands at 0x04 and the four i32 follow unaligned from 0x06.</summary>
    [Test] public static void Guild_C_SET_GUILD_JOIN_CONDITION_reads_five_fields()
    {
        var intro = "LFM";
        var body = new byte[0x12 + (intro.Length + 1) * 2];
        BitConverter.GetBytes((ushort)(0x12 + 4)).CopyTo(body, 0);
        BitConverter.GetBytes(20).CopyTo(body, 2);
        BitConverter.GetBytes(65).CopyTo(body, 6);
        BitConverter.GetBytes(2).CopyTo(body, 0x0A);
        BitConverter.GetBytes(3).CopyTo(body, 0x0E);
        System.Text.Encoding.Unicode.GetBytes(intro).CopyTo(body, 0x12);
        var got = GuildPackets.ParseCSetGuildJoinCondition(body);
        Hex.True(got != null, "parsed");
        Hex.True(got!.Value.introduction == intro, $"introduction '{got.Value.introduction}'");
        Hex.True(got.Value.minLevel == 20 && got.Value.maxLevel == 65, "min/max level @0x06/0x0A");
        Hex.True(got.Value.joinType == 2 && got.Value.preference == 3, "joinType @0x0E, preference @0x12");
    }

    /// <summary>
    /// The one piece of guild ground truth we have. Our builder reproduces the real Arbiter's
    /// empty DBS_INIT_GUILD_DATA byte for byte EXCEPT the two alignment holes inside GuildData,
    /// which the real one ships uninitialised - arb_world.log leaks 0xB379 at blob 0x024A.
    /// </summary>
    [Test] public static void Guild_DBS_INIT_GUILD_DATA_reproduces_the_capture_except_the_padding_holes()
    {
        var cap = LoadTsisOrSkip("cap_guild.bin");
        if (cap == null) return;
        Hex.True(cap.TryGetValue(2, out var capture), "cap_guild.bin seq 2 is the DBS_INIT_GUILD_DATA");

        var ours = GuildPackets.BuildEmptyDbsInitGuildData();
        Hex.True(ours.Length == capture!.Length, $"payload {ours.Length} != capture {capture.Length}");

        var differ = new List<int>();
        for (int i = 0; i < ours.Length; i++) if (ours[i] != capture[i]) differ.Add(i);

        var allowed = new HashSet<int>();
        foreach (var hole in GuildPackets.GuildDataPaddingHoles) { allowed.Add(13 + hole); allowed.Add(13 + hole + 1); }
        foreach (var d in differ)
            Hex.True(allowed.Contains(d),
                $"payload byte 0x{d:X4} differs from the capture and is not one of GuildData's padding holes");

        Hex.True(differ.Count == 2, $"arb_world.log leaks exactly 2 uninitialised bytes, saw {differ.Count}");
        Hex.True(differ[0] == 13 + GuildPackets.GdPadAfterTitle,
            $"the leak is the hole after GuildTitle (blob 0x{GuildPackets.GdPadAfterTitle:X4})");

        // and the header the real Arbiter writes
        Hex.True(BitConverter.ToInt32(capture, 0) == 19, "GuildData offset == frame 19");
        Hex.True(BitConverter.ToInt32(capture, 4) == GuildPackets.GuildDataSize, "GuildData length == 0x23A0");
        Hex.True(BitConverter.ToInt32(capture, 8) == 9139, "GuildLogoId offset == frame 9139");
        Hex.True(capture[12] == 0, "Success == 0 - this is the 'no guilds' terminator");

        var back = GuildPackets.ParseDbsInitGuildData(capture);
        Hex.True(back != null && !back.Value.Success && back.Value.GuildData.Length == GuildPackets.GuildDataSize
                 && back.Value.GuildLogoId.Length == 0, "the capture round-trips through our parser");
    }

    /// <summary>
    /// Cross-check on the GuildData offset map: the map comes from the spLoadAllGuild column
    /// binds in the decompile, the values come from a live capture, and they agree. The captured
    /// blob's only meaningful non-zero bytes are GuildLevel 1, three 1970-01-01 timestamps and
    /// the join condition 1/70/1.
    /// </summary>
    [Test] public static void Guild_GuildData_offsets_agree_with_the_captured_blob()
    {
        var cap = LoadTsisOrSkip("cap_guild.bin");
        if (cap == null) return;
        var blob = GuildPackets.ParseDbsInitGuildData(cap![2])!.Value.GuildData;

        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildLevel) == 1, "GuildLevel @0x0064 == 1");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdJoinMinLevel) == 1, "JoinMinLevel @0x235C == 1");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdJoinMaxLevel) == 70, "JoinMaxLevel @0x2360 == 70");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildJoinType) == 1, "GuildJoinType @0x2364 == 1");

        var epoch = GuildPackets.BuildEpochTimestamp();
        foreach (var at in new[] { GuildPackets.GdLastIncentiveTime, GuildPackets.GdGuildWarAcceptableToggleTime,
                                   GuildPackets.GdUnknownTime2348 })
            Hex.Eq(blob[at..(at + 16)], epoch, $"tagTIMESTAMP_STRUCT at blob 0x{at:X4} is the 1970-01-01 default");

        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildDbId) == 0, "GuildDbId @0x0000 == 0 (no guild)");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildLogoLength) == 0, "GuildLogoLength @0x024C == 0");

        // everything else is zero apart from the fields above and the two padding holes
        var zeroed = (byte[])blob.Clone();
        void Clear(int at, int len) { for (int i = 0; i < len; i++) zeroed[at + i] = 0; }
        Clear(GuildPackets.GdGuildLevel, 4);
        Clear(GuildPackets.GdJoinMinLevel, 4); Clear(GuildPackets.GdJoinMaxLevel, 4); Clear(GuildPackets.GdGuildJoinType, 4);
        Clear(GuildPackets.GdLastIncentiveTime, 16); Clear(GuildPackets.GdGuildWarAcceptableToggleTime, 16);
        Clear(GuildPackets.GdUnknownTime2348, 16);
        foreach (var hole in GuildPackets.GuildDataPaddingHoles) Clear(hole, 2);
        foreach (var b in zeroed) Hex.True(b == 0, "the rest of the default GuildData is zero");
    }

    /// <summary>
    /// The ten guild .def corrections, driven through the real parser and writer. Each assertion
    /// is an offset the Arbiter's own dumper guard proves, and each one is a byte the shipped
    /// .def gets wrong - so this test fails the day someone "fixes" the defs back.
    /// </summary>
    [Test] public static void Guild_corrected_defs_produce_the_decompiled_offsets()
    {
        static List<string> Trace(string name, Dictionary<string, object> data)
        {
            var def = DefinitionParser.ParseText(name, GuildPackets.CorrectedDefs[name]);
            var w = new DefinitionWriter { Trace = new List<string>() };
            w.Write(def, data);
            return w.Trace!;
        }
        static void At(List<string> trace, string field, int packetOffset)
            => Hex.True(trace.Contains($"{field}@{packetOffset}"),
                $"{field} should sit at packet 0x{packetOffset:X2}; trace = {string.Join(", ", trace)}");

        var member = new Dictionary<string, object>
        {
            ["memberDbId"] = 11, ["name"] = "dob", ["worldId"] = 1, ["guardId"] = 2, ["sectionId"] = 3,
            ["groupId"] = 4, ["userLevel"] = 60, ["race"] = 5, ["userClass"] = 6, ["state"] = 0,
            ["status"] = 0, ["gender"] = 1, ["lastLogoutTime"] = 0L, ["isWorldEventTarget"] = true,
            ["isInGuildWarCombatState"] = false, ["cityWarCompensationStatus"] = false,
        };

        var add = Trace("S_ADD_GUILD_MEMBER", member);
        At(add, "state", 0x26);
        At(add, "gender", 0x2A);
        At(add, "lastLogoutTime", 0x2E);
        At(add, "isWorldEventTarget", 0x36);
        At(add, "cityWarCompensationStatus", 0x37);

        var upd = Trace("S_UPDATE_GUILD_MEMBER", member);
        At(upd, "isWorldEventTarget", 0x36);
        At(upd, "isInGuildWarCombatState", 0x37);
        At(upd, "cityWarCompensationStatus", 0x38);

        foreach (var name in new[] { "S_CHECK_NEW_GUILDNAME", "S_RESULT_USABLE_GUILD_NAME",
                                     "S_CHECK_CHANGE_GUILDNAME", "S_CHANGE_GUILDNAME", "S_RESULT_RENAME_GUILD" })
        {
            var t = Trace(name, new Dictionary<string, object> { ["guildName"] = "Ere", ["usable"] = true });
            At(t, "usable", 0x06);
        }

        var log = Trace("S_GUILD_LOG", new Dictionary<string, object>
        {
            ["menuId"] = 3,
            ["logList"] = new List<Dictionary<string, object>>
            {
                new() { ["logString"] = "x", ["dateTime"] = 1L },
            },
        });
        At(log, "menuId", 0x08);

        var logo = DefinitionParser.ParseText("C_UPDATE_GUILD_LOGO", GuildPackets.CorrectedDefs["C_UPDATE_GUILD_LOGO"]);
        var logoBytes = new DefinitionWriter().Write(logo,
            new Dictionary<string, object> { ["logoImage"] = new byte[16] });
        Hex.True(BitConverter.ToUInt16(logoBytes, 0) == 0x08, "C_UPDATE_GUILD_LOGO data starts at packet 0x08");
        Hex.True(BitConverter.ToUInt16(logoBytes, 2) == 16, "C_UPDATE_GUILD_LOGO carries a byte count, not just an offset");

        var list = Trace("S_GUILD_MEMBER_LIST", new Dictionary<string, object>
        {
            ["guildDbId"] = 1, ["chiefDbId"] = 2, ["guildLevel"] = 3, ["guildExp"] = 4L, ["guildNextExp"] = 5L,
            ["guildMoney"] = 6L, ["memberCount"] = 1, ["accountCount"] = 1, ["guildSize"] = 0,
            ["guildCreateDate"] = 7L, ["ended"] = true, ["clearCache"] = false, ["showGuildWindow"] = true,
            ["guildName"] = "G", ["guildMaster"] = "M",
            ["members"] = new List<Dictionary<string, object>>(),
        });
        At(list, "showGuildWindow", 0x46);
    }

    /// <summary>
    /// The other side of the same coin: the guild .defs that ARE right. S_ADD_GUILD_GROUP,
    /// S_GET_USER_GUILD_LOGO, S_GUILD_APPLY_LIST and S_GUILD_HISTORY, driven through the shipped
    /// .def, must produce exactly what our hand-written builders produce. If they ever diverge,
    /// one of the two is wrong and this says so before a client sees it.
    /// </summary>
    [Test] public static void Guild_shipped_defs_agree_with_the_hand_written_builders()
    {
        var defs = LoadDefinitionsOrSkip();
        if (defs == null) return;

        var group = defs.Get("S_ADD_GUILD_GROUP");
        Hex.True(group != null, "S_ADD_GUILD_GROUP.1.def is present");
        Hex.Eq(new DefinitionWriter().Write(group!, new Dictionary<string, object>
               { ["id"] = 3, ["permissions"] = 0x7F, ["name"] = "Officer" }),
               GuildPackets.BuildSGuildGroupBody(3, 0x7F, "Officer"),
               "S_ADD_GUILD_GROUP: shipped .def == builder");

        var logoDef = defs.Get("S_GET_USER_GUILD_LOGO");
        Hex.True(logoDef != null, "S_GET_USER_GUILD_LOGO.1.def is present");
        var logo = new byte[20];
        for (int i = 0; i < logo.Length; i++) logo[i] = (byte)i;
        Hex.Eq(new DefinitionWriter().Write(logoDef!, new Dictionary<string, object>
               { ["playerId"] = 7, ["guildId"] = 9, ["logo"] = logo }),
               GuildPackets.BuildSGetUserGuildLogoBody(7, 9, logo),
               "S_GET_USER_GUILD_LOGO: shipped .def == builder");

        var applyDef = defs.Get("S_GUILD_APPLY_LIST");
        Hex.True(applyDef != null, "S_GUILD_APPLY_LIST.2.def is present");
        Hex.Eq(new DefinitionWriter().Write(applyDef!, new Dictionary<string, object>
               {
                   ["unk"] = (byte)1, ["unk2"] = 1, ["unk3"] = 1,
                   ["apps"] = new List<Dictionary<string, object>>
                   {
                       new() { ["playerId"] = 101u, ["class"] = 2u, ["level"] = 60u, ["time"] = 1700000000L,
                               ["name"] = "alice", ["message"] = "hi" },
                       new() { ["playerId"] = 102u, ["class"] = 3u, ["level"] = 55u, ["time"] = 1700000001L,
                               ["name"] = "bob", ["message"] = "me too" },
                   },
               }),
               GuildPackets.BuildSGuildApplyListBody(true, 1, 1, new List<GuildPackets.GuildApplyRow>
               {
                   new(101, 2, 60, 1700000000L, "alice", "hi"),
                   new(102, 3, 55, 1700000001L, "bob", "me too"),
               }),
               "S_GUILD_APPLY_LIST: shipped .def == builder");

        var histDef = defs.Get("S_GUILD_HISTORY");
        Hex.True(histDef != null, "S_GUILD_HISTORY.1.def is present");
        Hex.Eq(new DefinitionWriter().Write(histDef!, new Dictionary<string, object>
               {
                   ["page"] = 1, ["pages"] = 3,
                   ["events"] = new List<Dictionary<string, object>>
                   {
                       new() { ["date"] = 5L, ["event"] = 11, ["initiator"] = "dob", ["description"] = "@guild:11" },
                       new() { ["date"] = 6L, ["event"] = 12, ["initiator"] = "eve", ["description"] = "@guild:12" },
                   },
               }),
               GuildPackets.BuildSGuildHistoryBody(1, 3, new List<GuildPackets.GuildHistoryRow>
               {
                   new(5L, 11, "dob", "@guild:11"),
                   new(6L, 12, "eve", "@guild:12"),
               }),
               "S_GUILD_HISTORY: shipped .def == builder");
    }


    // =======================================================================================
    // T41 - ActionDispatcher. One place PartyManager's and GuildHandlers' action lists turn
    // into sends. The sends go through IClientSink, so these tests use a recording fake and
    // never need a socket; ActionDispatcher.ForSessions binds the same interface to the real
    // GameSession, whose Send / SendByDef / SendRawBody have exactly these signatures.
    // =======================================================================================

    /// <summary>Records what was sent and by which of the three routes.</summary>
    sealed class FakeSink : IClientSink
    {
        public readonly List<string> Log = new();
        public readonly List<byte[]> Bodies = new();
        /// <summary>Simulates a socket that has already gone away underneath us.</summary>
        public bool Throws;

        public void SendByDef(string packetName, IReadOnlyDictionary<string, object> fields)
        { Boom(); Log.Add($"def:{packetName}"); }

        public void SendRawBody(string packetName, byte[] body)
        { Boom(); Log.Add($"body:{packetName}:{body.Length}"); Bodies.Add(body); }

        public void Send(byte[] framedPacket)
        { Boom(); Log.Add($"raw:{framedPacket.Length}"); }

        private void Boom() { if (Throws) throw new InvalidOperationException("socket is gone"); }
    }

    /// <summary>An IArbiterClientAction the tests can build in any shape - the real two are each
    /// locked to one recipient kind and one payload kind.</summary>
    readonly record struct TestClientAction(
        Recipient To, string PacketName, IReadOnlyDictionary<string, object>? Fields,
        byte[]? RawPacket, byte[]? RawBody) : IArbiterClientAction;

    /// <summary>A scripted action set, so emission order can be stated rather than coaxed out of
    /// a manager.</summary>
    sealed class ScriptedActions : IArbiterActions
    {
        private readonly List<IArbiterAction> _ordered = new();
        public Recipient Origin { get; set; } = Recipient.None;
        public IReadOnlyList<IArbiterAction> Ordered => _ordered;
        public string? Rejected { get; set; }

        public ScriptedActions Def(Recipient to, string name, IReadOnlyDictionary<string, object>? fields = null)
        { _ordered.Add(new TestClientAction(to, name, fields ?? new Dictionary<string, object>(), null, null)); return this; }

        public ScriptedActions Raw(Recipient to, byte[] packet)
        { _ordered.Add(new TestClientAction(to, "(raw)", null, packet, null)); return this; }

        public ScriptedActions Body(Recipient to, string name, byte[] body)
        { _ordered.Add(new TestClientAction(to, name, null, null, body)); return this; }

        /// <summary>Neither fields nor bytes - a bug in an emitter, which the dispatcher must
        /// survive rather than propagate.</summary>
        public ScriptedActions Malformed(Recipient to, string name)
        { _ordered.Add(new TestClientAction(to, name, null, null, null)); return this; }

        public ScriptedActions WorldFrame(ushort op, params byte[] payload)
        { _ordered.Add(new WorldAction(op, payload)); return this; }
    }

    /// <summary>A dispatcher over a fixed session table, plus the World log it wrote to.</summary>
    sealed class DispatchHarness
    {
        public readonly Dictionary<uint, FakeSink> ByTicket = new();
        public readonly Dictionary<int, FakeSink> ByPlayer = new();
        public readonly List<(ushort Op, byte[] Payload)> WorldLog = new();
        public bool WorldRefuses;
        public ActionDispatcher Dispatcher = null!;

        public FakeSink Ticket(uint t) { var s = new FakeSink(); ByTicket[t] = s; return s; }
        public FakeSink Player(int p) { var s = new FakeSink(); ByPlayer[p] = s; return s; }

        public DispatchHarness Build(Func<string, TeraSharp.Arbiter.Protocol.PacketDef?>? resolveDef = null,
            bool relayRejections = true)
        {
            Dispatcher = new ActionDispatcher(
                t => ByTicket.TryGetValue(t, out var s) ? s : null,
                p => ByPlayer.TryGetValue(p, out var s) ? s : null,
                (op, payload) => { if (WorldRefuses) return false; WorldLog.Add((op, payload)); return true; },
                QuietLog())
            { ResolveDef = resolveDef, RelayRejections = relayRejections };
            return this;
        }
    }

    static Recipient ToTicket(uint t) => Recipient.Ticket(t);
    static Recipient ToPlayer(int p) => Recipient.Player(p);

    /// <summary>
    /// The whole point of the Ordered list: a subsystem that emits client, world, client gets
    /// them sent in that order. The two typed lists PartyActions/GuildActions also expose cannot
    /// express this - reading ToClients then ToWorld reorders every interleaving.
    /// </summary>
    [Test] public static void Dispatcher_preserves_emission_order()
    {
        var h = new DispatchHarness().Build();
        var a = h.Ticket(7);
        var b = h.Player(3);

        var r = h.Dispatcher.Dispatch(new ScriptedActions()
            .Def(ToTicket(7), "S_FIRST")
            .WorldFrame(0x1234, 1, 2)
            .Def(ToPlayer(3), "S_SECOND")
            .WorldFrame(0x5678, 3)
            .Def(ToTicket(7), "S_THIRD"), "test");

        Hex.True(r.ClientsSent == 3 && r.WorldSent == 2 && r.ClientsDropped == 0, $"counts: {r}");
        Hex.True(string.Join(",", a.Log) == "def:S_FIRST,def:S_THIRD", string.Join(",", a.Log));
        Hex.True(string.Join(",", b.Log) == "def:S_SECOND", string.Join(",", b.Log));
        Hex.True(h.WorldLog.Count == 2 && h.WorldLog[0].Op == 0x1234 && h.WorldLog[1].Op == 0x5678,
            "World frames kept their order");
        Hex.True(h.WorldLog[0].Payload.Length == 2 && h.WorldLog[1].Payload.Length == 1, "payloads intact");
    }

    /// <summary>
    /// A guild-wide broadcast names every member and most are offline. That is the normal case,
    /// not an error: the missing one is logged and skipped, everything after it still goes out,
    /// and the count says so.
    /// </summary>
    [Test] public static void Dispatcher_drops_an_unresolvable_recipient_and_keeps_going()
    {
        var h = new DispatchHarness().Build();
        var before = h.Player(1);
        var after = h.Player(3);           // player 2 is deliberately absent from the table

        var r = h.Dispatcher.Dispatch(new ScriptedActions()
            .Def(ToPlayer(1), "S_ONE").Def(ToPlayer(2), "S_TWO").Def(ToPlayer(3), "S_THREE"), "test");

        Hex.True(r.ClientsSent == 2 && r.ClientsDropped == 1, $"counts: {r}");
        Hex.True(before.Log.Count == 1 && after.Log.Count == 1, "the ones either side still got theirs");
        Hex.True(r.AnythingSent, "AnythingSent is true when two of three landed");
    }

    /// <summary>The three payload shapes take three different routes: a framed packet goes out
    /// whole, a body is framed by name, and fields are encoded.</summary>
    [Test] public static void Dispatcher_routes_raw_packets_bodies_and_fields_differently()
    {
        var h = new DispatchHarness().Build();
        var s = h.Ticket(7);

        h.Dispatcher.Dispatch(new ScriptedActions()
            .Raw(ToTicket(7), new byte[] { 8, 0, 0x4C, 0x99, 1, 2, 3, 4 })
            .Body(ToTicket(7), "S_SOMETHING", new byte[] { 9, 9, 9 })
            .Def(ToTicket(7), "S_FIELDS"), "test");

        Hex.True(string.Join(",", s.Log) == "raw:8,body:S_SOMETHING:3,def:S_FIELDS",
            string.Join(",", s.Log));
    }

    /// <summary>An action with neither fields nor bytes is a bug in the emitter. The dispatcher
    /// logs it and carries on rather than taking the connection down.</summary>
    [Test] public static void Dispatcher_drops_a_malformed_action_without_throwing()
    {
        var h = new DispatchHarness().Build();
        var s = h.Ticket(7);
        var r = h.Dispatcher.Dispatch(new ScriptedActions()
            .Malformed(ToTicket(7), "S_NOTHING").Def(ToTicket(7), "S_REAL"), "test");
        Hex.True(r.ClientsSent == 1 && r.ClientsDropped == 1, $"counts: {r}");
        Hex.True(string.Join(",", s.Log) == "def:S_REAL", string.Join(",", s.Log));
    }

    /// <summary>
    /// The hook that makes T39's .def corrections real. GameSession.SendByDef resolves from the
    /// SHIPPED registry, so without ResolveDef a guild handler emitting S_ADD_GUILD_MEMBER would
    /// put the .def's 0x33-byte body on the wire. With it, the dispatcher encodes and sends a
    /// body - and that body carries the 0x38 fixed part the Arbiter's dumper guard proves.
    /// </summary>
    [Test] public static void Dispatcher_encodes_with_the_corrected_def_when_one_resolves()
    {
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var s = h.Player(2);

        // a packet with no correction takes the ordinary SendByDef route
        h.Dispatcher.Dispatch(new ScriptedActions().Def(ToPlayer(2), "S_NO_CORRECTION_FOR_THIS"), "guild");
        Hex.True(string.Join(",", s.Log) == "def:S_NO_CORRECTION_FOR_THIS", string.Join(",", s.Log));

        s.Log.Clear();
        var member = new Dictionary<string, object>
        {
            ["memberDbId"] = 11, ["name"] = "dob", ["worldId"] = 1, ["guardId"] = 2, ["sectionId"] = 3,
            ["groupId"] = 4, ["userLevel"] = 60, ["race"] = 5, ["userClass"] = 6, ["state"] = 0,
            ["gender"] = 1, ["lastLogoutTime"] = 0L, ["isWorldEventTarget"] = false,
            ["cityWarCompensationStatus"] = false,
        };
        h.Dispatcher.Dispatch(new ScriptedActions().Def(ToPlayer(2), "S_ADD_GUILD_MEMBER", member), "guild");

        Hex.True(s.Log.Count == 1 && s.Log[0].StartsWith("body:S_ADD_GUILD_MEMBER:"),
            $"the corrected def routes through SendRawBody: {string.Join(",", s.Log)}");
        Hex.True(BitConverter.ToUInt16(s.Bodies[0], 0) == 0x38,
            $"fixed part 0x{BitConverter.ToUInt16(s.Bodies[0], 0):X2}, want 0x38 - the correction reached the wire");
    }

    /// <summary>
    /// A rejection is not a log line the player never sees: it goes back to the session that
    /// caused it, as S_SYSTEM_MESSAGE_CUSTOM - the same literal channel every Arbiter-side GM
    /// command answers on (GmCommandHandlers.SendCustom).
    /// </summary>
    [Test] public static void Dispatcher_relays_the_rejection_to_the_originator()
    {
        var h = new DispatchHarness().Build();
        var origin = h.Player(5);
        var other = h.Player(6);

        var r = h.Dispatcher.Dispatch(new ScriptedActions
        {
            Origin = ToPlayer(5),
            Rejected = "C_APPLY_GUILD: applicant is already in a guild",
        }.Def(ToPlayer(6), "S_SOMETHING_ELSE"), "guild");

        Hex.True(r.RejectionSent, "the rejection was relayed");
        Hex.True(string.Join(",", origin.Log) == $"def:{ActionDispatcher.RejectionPacket}",
            string.Join(",", origin.Log));
        Hex.True(string.Join(",", other.Log) == "def:S_SOMETHING_ELSE",
            "the other recipient got its own packet and not the rejection");
        Hex.True(ActionDispatcher.RejectionPacket == "S_SYSTEM_MESSAGE_CUSTOM"
                 && ActionDispatcher.RejectionField == "formatted",
            "the literal form GmCommands already uses");
    }

    /// <summary>An OnWorldFrame input has no originating client, so its rejection has nowhere to
    /// go. That is a log line, not an error, and nothing else in the set is affected.</summary>
    [Test] public static void Dispatcher_keeps_an_unaddressed_rejection_in_the_log()
    {
        var h = new DispatchHarness().Build();
        var s = h.Ticket(7);
        var r = h.Dispatcher.Dispatch(new ScriptedActions
        {
            Origin = Recipient.None,
            Rejected = "SA_JOIN_PARTY: short frame",
        }.Def(ToTicket(7), "S_STILL_SENT"), "party");

        Hex.True(!r.RejectionSent, "nothing to relay it to");
        Hex.True(r.ClientsSent == 1, "the rest of the set still went out");
        Hex.True(string.Join(",", s.Log) == "def:S_STILL_SENT", string.Join(",", s.Log));
    }

    /// <summary>RelayRejections = false keeps it out of the client's face entirely.</summary>
    [Test] public static void Dispatcher_can_be_told_not_to_relay_rejections()
    {
        var h = new DispatchHarness().Build(relayRejections: false);
        var origin = h.Player(5);
        var r = h.Dispatcher.Dispatch(new ScriptedActions { Origin = ToPlayer(5), Rejected = "nope" }, "guild");
        Hex.True(!r.RejectionSent && origin.Log.Count == 0, "silent");
    }

    /// <summary>A socket that died between the manager deciding and the dispatcher sending is a
    /// dropped packet, not an exception out of Dispatch.</summary>
    [Test] public static void Dispatcher_survives_a_sink_that_throws()
    {
        var h = new DispatchHarness().Build();
        var bad = h.Player(1); bad.Throws = true;
        var good = h.Player(2);

        var r = h.Dispatcher.Dispatch(new ScriptedActions()
            .Def(ToPlayer(1), "S_ONE").Def(ToPlayer(2), "S_TWO"), "test");

        Hex.True(r.ClientsSent == 1 && r.ClientsDropped == 1, $"counts: {r}");
        Hex.True(good.Log.Count == 1, "the healthy session still got its packet");
    }

    /// <summary>World refusing a frame is counted, not thrown, and does not stop the client
    /// sends that follow it.</summary>
    [Test] public static void Dispatcher_counts_a_refused_world_frame()
    {
        var h = new DispatchHarness().Build();
        h.WorldRefuses = true;
        var s = h.Ticket(7);
        var r = h.Dispatcher.Dispatch(new ScriptedActions()
            .WorldFrame(0x140A, 1, 2, 3).Def(ToTicket(7), "S_AFTER"), "guild");
        Hex.True(r.WorldFailed == 1 && r.WorldSent == 0, $"counts: {r}");
        Hex.True(r.ClientsSent == 1 && s.Log.Count == 1, "the client send after it still happened");
    }

    /// <summary>
    /// The two id spaces are genuinely separate tables: ticket 5 and player 5 are different
    /// recipients. PartyManager addresses by ticket (GameSession.TunnelKey), GuildHandlers by
    /// character db id (GameSession.PlayerId), and a dispatcher that confused them would look
    /// like it worked until two players collided.
    /// </summary>
    [Test] public static void Dispatcher_keeps_the_ticket_and_player_tables_apart()
    {
        var h = new DispatchHarness().Build();
        var byTicket = h.Ticket(5);
        var byPlayer = h.Player(5);

        h.Dispatcher.Dispatch(new ScriptedActions()
            .Def(ToTicket(5), "S_VIA_TICKET").Def(ToPlayer(5), "S_VIA_PLAYER"), "test");
        Hex.True(string.Join(",", byTicket.Log) == "def:S_VIA_TICKET", string.Join(",", byTicket.Log));
        Hex.True(string.Join(",", byPlayer.Log) == "def:S_VIA_PLAYER", string.Join(",", byPlayer.Log));
    }

    /// <summary>
    /// The real thing, party side: PartyManager's own output, unmodified, dispatched. Proves the
    /// interface extraction did not change what the manager emits, and that a ticket which is not
    /// in the session table is simply skipped.
    /// </summary>
    [Test] public static void Dispatcher_sends_a_real_PartyActions()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob"));
        pm.Register(P(11, 2, "Test"));

        var h = new DispatchHarness().Build();
        var applicant = h.Ticket(11);
        var target = h.Ticket(10);

        var apply = pm.OnClientPacket(11, PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(1));
        Hex.True(apply.Origin.Kind == RecipientKind.Ticket && apply.Origin.Id == 11,
            "the origin is the ticket that sent the packet");
        Hex.True(apply.Ordered.Count == apply.ToClients.Count + apply.ToWorld.Count,
            "Ordered holds exactly the same items as the two typed lists");

        var r = h.Dispatcher.Dispatch(apply, "party");
        Hex.True(r.ClientsSent == 1 && target.Log.Count == 1,
            $"S_OTHER_USER_APPLY_PARTY goes to the TARGET, not the applicant: {r}");
        Hex.True(applicant.Log.Count == 0, "the applicant hears nothing");

        // a World frame input: no origin, so its rejection cannot be relayed
        var bad = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY, new byte[4]);
        Hex.True(bad.Origin.Kind == RecipientKind.None, "a World frame has no origin");
        var r2 = h.Dispatcher.Dispatch(bad, "party");
        Hex.True(!r2.RejectionSent, "and its rejection stays in the log");
    }

    /// <summary>
    /// The real thing, guild side: the create -&gt; apply -&gt; accept path dispatched end to end,
    /// with the joining member offline. Order is checked against the emission order, not against
    /// the two typed lists - the accept emits S_ADD_GUILD_MEMBER to both members and only THEN
    /// the two World frames, and that is what has to reach the wire.
    /// </summary>
    [Test] public static void Dispatcher_sends_a_real_GuildActions()
    {
        using var store = GuildStore();
        var g = NewGuildHandlers(store);
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));

        var setup = new GuildActions();
        g.CreateGuild(setup, 1, "Ere");
        Hex.True(setup.Origin.Kind == RecipientKind.PlayerId && setup.Origin.Id == 1,
            "CreateGuild stamps the founder as the origin");

        var chief = h.Player(1);           // character 2 is NOT in the session table
        g.OnClientPacket(2, GuildPackets.C_APPLY_GUILD, CApplyGuildBody("Ere", "hi"));
        var accept = g.OnClientPacket(1, GuildPackets.C_ACCEPT_GUILD_APPLY, CAcceptGuildApplyBody(true, 2));

        Hex.True(accept.Ordered.Count == accept.ToClients.Count + accept.ToWorld.Count,
            "Ordered holds exactly the same items as the two typed lists");

        var r = h.Dispatcher.Dispatch(accept, "guild");
        Hex.True(r.ClientsDropped == 1, $"the joiner is offline and is skipped: {r}");
        Hex.True(r.WorldSent == 2, $"both World frames went: {r}");
        Hex.True(h.WorldLog[0].Op == GuildPackets.AS_ADD_GUILDMEMBER
                 && h.WorldLog[1].Op == GuildPackets.AS_GUILD_JOINED,
            "AS_ADD_GUILDMEMBER before AS_GUILD_JOINED, as GuildUtil::UserJoinToGuild sends them");

        // the chief's S_ADD_GUILD_MEMBER went out as a corrected body, not through SendByDef
        Hex.True(chief.Log.Count > 0 && chief.Log[0].StartsWith("body:S_ADD_GUILD_MEMBER:"),
            $"S_ADD_GUILD_MEMBER took the corrected-def route: {string.Join(",", chief.Log)}");
        Hex.True(BitConverter.ToUInt16(chief.Bodies[0], 0) == 0x38,
            "and carries the 0x38 fixed part, not the .def's 0x33");
    }

    /// <summary>The .def folder, or null with a printed note (the tests run where the repo is).</summary>
    static TeraSharp.Arbiter.Protocol.DefinitionRegistry? LoadDefinitionsOrSkip()
    {
        var root = Environment.GetEnvironmentVariable("TERASHARP_DATA") ?? @"D:\v100\TERA_SERVER.100";
        var folder = Path.Combine(root, "tera_v100_MASTER_FINAL");
        if (!Directory.Exists(folder))
        {
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            for (int i = 0; i < 10 && dir != null; i++, dir = dir.Parent)
            {
                var c = Path.Combine(dir.FullName, "tera_v100_MASTER_FINAL");
                if (Directory.Exists(c)) { folder = c; break; }
            }
        }
        if (!Directory.Exists(folder)) { Console.WriteLine("        (skipped: tera_v100_MASTER_FINAL not found)"); return null; }
        return TeraSharp.Arbiter.Protocol.DefinitionRegistry.LoadFromFolder(folder, QuietLog());
    }

    // ================================================================================
    // T30 - friends, friend groups, memos and the block list, from rows.
    //
    // Ground truth: cap_newchar_client.log (the CLIENT side of the same session as
    // cap_newchar.log), frames 304-307 - the four social packets the real Arbiter sends
    // after C_LOAD_TOPO_FIN for a brand-new character:
    //
    //   [304] S_USER_BLOCK_LIST    len=8   00 00 00 00
    //   [305] S_FRIEND_GROUP_LIST  len=24  01 00 08 00 08 00 00 00 12 00 02 00 00 00 7D 59 CB 53 00 00
    //   [306] S_FRIEND_LIST        len=32  00 00 00 00 0A 00 <profile message> 00 00
    //   [307] S_UPDATE_FRIEND_INFO len=8   00 00 00 00
    //
    // Rules and layouts: status/FRIENDS.md (every one quoted to its Handler_C_* in Arb_part_*.c).
    // ================================================================================

    /// <summary>The four captured bodies, frame header stripped.</summary>
    const string Cap304BlockList     = "00 00 00 00";
    const string Cap305FriendGroups  = "01 00 08 00 08 00 00 00 12 00 02 00 00 00 7D 59 CB 53 00 00";
    const string Cap306FriendList    = "00 00 00 00 0A 00 CA 4E 29 59 5F 4E 2F 66 09 61 EB 5F 84 76 00 4E 29 59 21 00 00 00";
    const string Cap307UpdateFriends = "00 00 00 00";

    /// <summary>
    /// The defs the social path uses, with the two 100.02 overrides from
    /// <see cref="V100Definitions"/> and the rest exactly as the def folder has them.
    /// </summary>
    static DefinitionRegistry CreateT30Defs()
    {
        var reg = new DefinitionRegistry(QuietLog());
        V100Definitions.EnsureRegistered(reg);

        reg.RegisterFromDef("S_FRIEND_GROUP_LIST", @"
array    groups
- int32  index
- string name
");
        reg.RegisterFromDef("S_USER_BLOCK_LIST", @"
array    blockList
- uint32 id
- int32  level
- int32  class
- string name
- string myNote
");
        reg.RegisterFromDef("S_ADD_BLOCKED_USER", @"
uint32 id
int32  level
int32  class
string name
string myNote
");
        reg.RegisterFromDef("S_REMOVE_BLOCKED_USER", "uint32 id\n");
        reg.RegisterFromDef("S_DELETE_FRIEND", "uint32 id\n");
        reg.RegisterFromDef("S_RESULT_CHANGE_FRIEND_MEMO", @"
int32  friendDbId
string newMemo
");
        reg.RegisterFromDef("S_CHANGE_FRIEND_STATE", @"
uint32 playerId
uint32 state
");
        reg.RegisterFromDef("C_ADD_FRIEND", @"
string name
string message
");
        reg.RegisterFromDef("C_CHANGE_FRIEND_MEMO", @"
int32  friendDbId
string newMemo
");
        reg.RegisterFromDef("C_ADD_FRIEND_GROUP", @"
ref      friends
ref      name
uint32   id
string   name
array<uint32> friends
");
        reg.RegisterFromDef("C_EDIT_FRIEND_GROUP", @"
ref      friends
ref      name
uint32   id
string   name
array    friends
- uint32 playerId
- uint32 id
");
        return reg;
    }

    /// <summary>
    /// Two characters on DIFFERENT accounts - friends between characters of one account are
    /// refused by the real Arbiter (User::CanAddFriendNoLock, SMT 441), so the shared
    /// <c>StoreWithTwoCharacters</c> helper cannot exercise any of this.
    /// </summary>
    static TeraSharp.Arbiter.Persistence.CharacterStore StoreWithTwoAccounts()
    {
        var store = new TeraSharp.Arbiter.Persistence.CharacterStore(":memory:", QuietLog());
        for (int i = 1; i <= 2; i++)
        {
            var acct = store.GetOrCreateAccount("acct" + i);
            int id = store.CreateCharacter(new TeraSharp.Arbiter.Persistence.CharacterRecord
            {
                AccountId = acct.Id, Name = "t30_" + i, Gender = 1, Race = 4, Class = 12,
                Level = 10 + i, TemplateId = 10101, Zone = 5, X = 1f, Y = 2f, Z = 3f,
                Appearance = new byte[8], Details = new byte[32], Shape = new byte[64],
                Position = i,
            });
            Hex.True(id == i, $"expected character id {i}, got {id}");
        }
        return store;
    }

    static byte[] WriteByDef(DefinitionRegistry reg, string packet, Dictionary<string, object> fields)
        => new DefinitionWriter().Write(reg.Get(packet)!, fields);

    // ---- The four login packets, byte-exact against the capture ----

    [Test] public static void T30_block_list_matches_the_capture()
    {
        using var store = StoreWithTwoAccounts();
        var reg = CreateT30Defs();
        Hex.Eq(WriteByDef(reg, "S_USER_BLOCK_LIST", SocialHandlers.BuildBlockListFields(store, 1)),
            Cap304BlockList, "S_USER_BLOCK_LIST for a character with no blocks (capture frame 304)");
    }

    [Test] public static void T30_friend_group_list_matches_the_capture()
    {
        using var store = StoreWithTwoAccounts();
        var reg = CreateT30Defs();

        // Before the seed there are no groups at all - the packet is 4 bytes, not the capture.
        Hex.Eq(WriteByDef(reg, "S_FRIEND_GROUP_LIST", SocialHandlers.BuildFriendGroupListFields(store, 1)),
            "00 00 00 00", "no groups yet");

        SocialHandlers.ProvideSampleGroup(store, 1, TeraSharp.Arbiter.Auth.LoginLanguage.Twn);   // the capture is a TW server's strings (T45)
        Hex.Eq(WriteByDef(reg, "S_FRIEND_GROUP_LIST", SocialHandlers.BuildFriendGroupListFields(store, 1)),
            Cap305FriendGroups, "S_FRIEND_GROUP_LIST after the sample group (capture frame 305)");
    }

    [Test] public static void T30_friend_list_matches_the_capture()
    {
        using var store = StoreWithTwoAccounts();
        var reg = CreateT30Defs();
        SocialHandlers.ProvideSampleGroup(store, 1, TeraSharp.Arbiter.Auth.LoginLanguage.Twn);       // also seeds the profile message (TW strings = the capture)
        Hex.Eq(WriteByDef(reg, "S_FRIEND_LIST", SocialHandlers.BuildFriendListFields(store, 1)),
            Cap306FriendList, "S_FRIEND_LIST for a brand-new character (capture frame 306)");
    }

    [Test] public static void T30_update_friend_info_is_empty_with_nobody_online()
    {
        var reg = CreateT30Defs();
        Hex.Eq(WriteByDef(reg, "S_UPDATE_FRIEND_INFO",
                new Dictionary<string, object> { ["friends"] = new List<object>() }),
            Cap307UpdateFriends, "S_UPDATE_FRIEND_INFO with no online friends (capture frame 307)");
    }

    [Test] public static void T30_sample_group_name_and_profile_are_the_captured_strings()
    {
        // The two strings come from StrFriendDataSheet (ids 100 and 200), so they are only
        // knowable from the capture - and they are what makes frames 305/306 reproduce.
        Hex.Eq(System.Text.Encoding.Unicode.GetBytes(SocialHandlers.SampleGroupNameTw),
            "7D 59 CB 53", "the sample group name is the capture's two code units");
        Hex.Eq(System.Text.Encoding.Unicode.GetBytes(SocialHandlers.DefaultProfileMessageTw),
            "CA 4E 29 59 5F 4E 2F 66 09 61 EB 5F 84 76 00 4E 29 59 21 00",
            "the default profile message is the capture's ten code units");
    }

    // ---- The 100.02 element sizes: the reason for V100Definitions ----

    [Test] public static void T30_friend_list_element_is_63_bytes_not_67()
    {
        var reg = CreateT30Defs();
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "hi");
        var body = WriteByDef(reg, "S_FRIEND_LIST", SocialHandlers.BuildFriendListFields(store, 1));

        // [0..1] count=1, [2..3] first element offset (packet-relative), [4..5] note offset.
        Hex.True(BitConverter.ToUInt16(body, 0) == 1, "one friend");
        int first = BitConverter.ToUInt16(body, 2) - 4;
        int next = BitConverter.ToUInt16(body, first + 2) - 4;    // 0 when it is the last element
        int nameOffset = BitConverter.ToUInt16(body, first + 4) - 4;
        Hex.True(next == -4, "a single element has no next");
        // The strings start right after the element, so nameOffset - first IS the stride.
        Hex.True(nameOffset - first == 63,
            $"User::SendFriendListNoLock advances 0x3f per element; got {nameOffset - first}. "
            + "67 means the S_FRIEND_LIST.2 def (patch 101+) leaked back in - see V100Definitions.");
    }

    [Test] public static void T30_update_friend_info_element_is_53_bytes_not_57()
    {
        var reg = CreateT30Defs();
        var body = WriteByDef(reg, "S_UPDATE_FRIEND_INFO", new Dictionary<string, object>
        {
            ["friends"] = new List<object>
            {
                new Dictionary<string, object>
                {
                    ["playerId"] = 2u, ["level"] = 11, ["race"] = 4, ["class"] = 12, ["gender"] = 1,
                    ["status"] = 0, ["worldId"] = 0, ["guardId"] = 0, ["sectionId"] = 0,
                    ["updated"] = true, ["isWorldEventTarget"] = false, ["summonable"] = false,
                    ["lastOnline"] = 0L, ["name"] = "t30_2",
                },
            },
        });
        int first = BitConverter.ToUInt16(body, 2) - 4;
        int nameOffset = BitConverter.ToUInt16(body, first + 4) - 4;   // here, next, then the name ref
        Hex.True(nameOffset - first == 53,
            $"User::SendUpdateFriendListInfo writes 53-byte elements; got {nameOffset - first}");
    }

    [Test] public static void T30_friend_list_round_trips_a_pending_request()
    {
        var reg = CreateT30Defs();
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "add me");

        var body = WriteByDef(reg, "S_FRIEND_LIST", SocialHandlers.BuildFriendListFields(store, 1));
        var read = new DefinitionReader(body).Read(reg.Get("S_FRIEND_LIST")!);
        var friends = (List<object>)read["friends"];
        Hex.True(friends.Count == 1, "one friend row");
        var f = (Dictionary<string, object>)friends[0];
        Hex.True(Convert.ToUInt32(f["playerId"]) == 2, "playerId");
        Hex.True(Convert.ToUInt32(f["type"]) == SocialHandlers.FriendTypeOutgoing,
            "my side of a request I sent is type 1");
        Hex.True(Convert.ToInt32(f["group"]) == SocialHandlers.UngroupedGroupId, "ungrouped");
        Hex.True((string)f["name"] == "t30_2", "friend name");
        Hex.True((string)f["myNote"] == "add me", "the greeting is stored as the memo");
        Hex.True((string)f["theirNote"] == "add me", "and on their row too");

        // The other side sees the same pair as an INCOMING request.
        var theirs = SocialHandlers.BuildFriendListFields(store, 2);
        var them = (Dictionary<string, object>)((List<object>)theirs["friends"])[0];
        Hex.True(Convert.ToUInt32(them["type"]) == SocialHandlers.FriendTypeIncoming, "their side is type 2");
    }

    // ---- The rules ----

    [Test] public static void T30_system_message_format_matches_the_capture()
    {
        // cap_newchar_client.log frame 692 decodes to exactly this.
        Hex.True(SocialHandlers.Smt(2977, "questTemplateId", "59901", "taskId", "1")
                 == "@2977\vquestTemplateId\v59901\vtaskId\v1", "parameterised form");
        Hex.True(SocialHandlers.Smt(888) == "@888", "bare form (frame 311)");
    }

    [Test] public static void T30_CanAddFriend_follows_the_decompiled_order()
    {
        using var store = StoreWithTwoAccounts();
        Hex.True(SocialHandlers.CanAddFriend(store, 1, 99) == SocialHandlers.AddFriendResult.TargetNotFound,
            "unknown character");
        Hex.True(SocialHandlers.CanAddFriend(store, 1, 1) == SocialHandlers.AddFriendResult.CannotAddSelf,
            "myself");

        // Another character on my OWN account is refused the same way (SMT 441).
        var acct = store.GetOrCreateAccount("acct1");
        int sibling = store.CreateCharacter(new TeraSharp.Arbiter.Persistence.CharacterRecord
        {
            AccountId = acct.Id, Name = "t30_sibling", Gender = 1, Race = 4, Class = 12,
            Level = 1, TemplateId = 10101, Zone = 5,
            Appearance = new byte[8], Details = new byte[32], Shape = new byte[64], Position = 2,
        });
        Hex.True(SocialHandlers.CanAddFriend(store, 1, sibling) == SocialHandlers.AddFriendResult.CannotAddSelf,
            "same account");

        Hex.True(SocialHandlers.CanAddFriend(store, 1, 2) == SocialHandlers.AddFriendResult.Ok, "clean pair");

        store.AddBlock(1, 2);
        Hex.True(SocialHandlers.CanAddFriend(store, 1, 2) == SocialHandlers.AddFriendResult.IBlockedTarget,
            "I blocked them");
        store.RemoveBlock(1, 2);
        store.AddBlock(2, 1);
        Hex.True(SocialHandlers.CanAddFriend(store, 1, 2) == SocialHandlers.AddFriendResult.TargetBlockedMe,
            "they blocked me");
        store.RemoveBlock(2, 1);

        SocialHandlers.WriteFriendRequest(store, 1, 2, "");
        Hex.True(SocialHandlers.CanAddFriend(store, 1, 2) == SocialHandlers.AddFriendResult.AlreadyFriend,
            "a pending request counts as already on the list");
    }

    [Test] public static void T30_request_then_accept_flips_both_rows_and_clears_the_memos()
    {
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "hello there");

        var mine = store.GetFriendRow(1, 2)!;
        var theirs = store.GetFriendRow(2, 1)!;
        Hex.True(mine.Type == SocialHandlers.FriendTypeOutgoing, "requester row is type 1");
        Hex.True(theirs.Type == SocialHandlers.FriendTypeIncoming, "target row is type 2");
        Hex.True(mine.Memo == "hello there" && theirs.Memo == "hello there",
            "the greeting is written to BOTH rows");

        Hex.True(SocialHandlers.AcceptFriendRequest(store, 2, 1), "the target can accept");
        Hex.True(store.GetFriendRow(1, 2)!.Type == SocialHandlers.FriendTypeMutual, "requester now mutual");
        Hex.True(store.GetFriendRow(2, 1)!.Type == SocialHandlers.FriendTypeMutual, "target now mutual");
        Hex.True(store.GetFriendRow(1, 2)!.Memo == "" && store.GetFriendRow(2, 1)!.Memo == "",
            "accepting clears both memos - the Arbiter re-adds with an empty one");
    }

    [Test] public static void T30_accepting_without_a_request_is_silently_ignored()
    {
        using var store = StoreWithTwoAccounts();
        Hex.True(!SocialHandlers.AcceptFriendRequest(store, 2, 1), "no request at all");

        SocialHandlers.WriteFriendRequest(store, 1, 2, "");
        // The REQUESTER cannot accept their own request (their row is type 1, not 2).
        Hex.True(!SocialHandlers.AcceptFriendRequest(store, 1, 2), "the requester cannot self-accept");
        Hex.True(store.GetFriendRow(1, 2)!.Type == SocialHandlers.FriendTypeOutgoing, "row untouched");
    }

    [Test] public static void T30_delete_friend_removes_both_directions_and_reports_the_prior_type()
    {
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "x");

        // Declining: the receiver deletes a type-2 row.
        Hex.True(SocialHandlers.DeleteFriendPair(store, 2, 1) == SocialHandlers.FriendTypeIncoming,
            "the prior relation selects the system message");
        Hex.True(store.GetFriendRow(1, 2) == null && store.GetFriendRow(2, 1) == null,
            "one delete removes both directions");
        Hex.True(SocialHandlers.DeleteFriendPair(store, 2, 1) == null, "deleting again does nothing");

        SocialHandlers.WriteFriendRequest(store, 1, 2, "");
        SocialHandlers.AcceptFriendRequest(store, 2, 1);
        Hex.True(SocialHandlers.DeleteFriendPair(store, 1, 2) == SocialHandlers.FriendTypeMutual,
            "unfriending a real friend reports type 0");
    }

    [Test] public static void T30_friend_groups_follow_the_index_rules()
    {
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "");
        Hex.True(store.GetFriendRow(1, 2)!.GroupId == SocialHandlers.UngroupedGroupId,
            "a new friend starts in group 1");

        store.UpsertFriendGroup(1, 3, "raid");
        store.SetFriendGroup(1, 2, 3);
        Hex.True(store.GetFriendRow(1, 2)!.GroupId == 3, "moved into group 3");

        // Deleting the group moves its members back to the ungrouped bucket (User::DeleteFriendGroup).
        Hex.True(store.DeleteFriendGroup(1, 3), "group deleted");
        Hex.True(store.GetFriendRow(1, 2)!.GroupId == SocialHandlers.UngroupedGroupId,
            "members fall back to group 1, never to a group that is gone");
        Hex.True(store.GetFriendGroups(1).Count == 0, "and the group itself is gone");
    }

    [Test] public static void T30_sample_group_is_provided_exactly_once()
    {
        using var store = StoreWithTwoAccounts();
        SocialHandlers.ProvideSampleGroup(store, 1);
        store.SetProfileMessage(1, "mine now");
        store.DeleteFriendGroup(1, SocialHandlers.SampleGroupIndex);

        SocialHandlers.ProvideSampleGroup(store, 1);      // the spIsProvideSampleFriendGroup guard
        Hex.True(store.GetFriendGroups(1).Count == 0, "a deleted sample group is not re-seeded");
        Hex.True(store.GetProfileMessage(1) == "mine now", "and the profile message is not reset");
    }

    [Test] public static void T30_memos_truncate_at_the_decompiled_limits()
    {
        using var store = StoreWithTwoAccounts();
        SocialHandlers.WriteFriendRequest(store, 1, 2, "");
        store.SetFriendMemo(1, 2, new string('a', 40));
        Hex.True(store.GetFriendRow(1, 2)!.Memo.Length == SocialHandlers.MaxFriendMemo,
            "friend memo: wcsncpy_s(.., 0x15, ..) keeps 20");

        store.AddBlock(1, 2);
