        var seq = ChatSeq(a);
        Hex.True(seq.Count == 3
            && seq[0] == (1, "S_PRIVATE_CHAT")
            && seq[1] == (2, "S_PRIVATE_CHAT")
            && seq[2] == (3, "S_PRIVATE_CHAT"),
