    // ------------------------------------------------------- the social seed

    [Test] public static void Login_language_is_recorded_per_account_and_defaults_to_eur()
    {
        TeraSharp.Arbiter.Auth.LoginLanguage.Clear();
        Hex.True(TeraSharp.Arbiter.Auth.LoginLanguage.For("nobody")
                 == TeraSharp.Arbiter.Auth.LoginLanguage.Eur, "unseen accounts default to EUR");
        Hex.True(TeraSharp.Arbiter.Auth.LoginLanguage.For(null)
                 == TeraSharp.Arbiter.Auth.LoginLanguage.Eur, "so does a null name");

        TeraSharp.Arbiter.Auth.LoginLanguage.Record("1", TeraSharp.Arbiter.Auth.LoginLanguage.Twn);
        Hex.True(TeraSharp.Arbiter.Auth.LoginLanguage.For("1")
                 == TeraSharp.Arbiter.Auth.LoginLanguage.Twn, "recorded");
        Hex.True(TeraSharp.Arbiter.Auth.LoginLanguage.For("2")
                 == TeraSharp.Arbiter.Auth.LoginLanguage.Eur, "and only for that account");
        TeraSharp.Arbiter.Auth.LoginLanguage.Clear();
    }

    /// <summary>
    /// Until T45 every character on this server was seeded with the Chinese friend-group name and
    /// greeting from cap_newchar_client.log, because they were hard-coded from that capture. The
    /// capture's own login carried language 6 (EUR) - the strings came from the TW server's
    /// string sheet, not from the packet - so the field is only a proxy, and the table defaults
    /// to English.
    /// </summary>
    [Test] public static void Social_seed_is_english_by_default_and_chinese_only_for_tw()
    {
        Hex.True(SocialHandlers.SampleGroupNameFor(TeraSharp.Arbiter.Auth.LoginLanguage.Eur) == "Friends",
            "EUR gets Friends");
        Hex.True(SocialHandlers.DefaultProfileMessageFor(TeraSharp.Arbiter.Auth.LoginLanguage.Eur) == "",
            "EUR gets no greeting at all");
        Hex.True(SocialHandlers.SampleGroupNameFor(TeraSharp.Arbiter.Auth.LoginLanguage.Usa) == "Friends",
            "so does every other unlisted language");

        Hex.True(SocialHandlers.SampleGroupNameFor(TeraSharp.Arbiter.Auth.LoginLanguage.Twn)
                 == SocialHandlers.SampleGroupNameTw, "TW still gets the captured name");
        Hex.True(SocialHandlers.DefaultProfileMessageFor(TeraSharp.Arbiter.Auth.LoginLanguage.Twn)
                 == SocialHandlers.DefaultProfileMessageTw, "and the captured greeting");

        // the captured bytes, so the TW strings cannot drift
        Hex.Eq(System.Text.Encoding.Unicode.GetBytes(SocialHandlers.SampleGroupNameTw),
            "7D 59 CB 53", "cap_newchar_client.log frame 305");

        using var store = T45Store();
        SocialHandlers.ProvideSampleGroup(store, 1, TeraSharp.Arbiter.Auth.LoginLanguage.Eur);
        var groups = store.GetFriendGroups(1);
        Hex.True(groups.Count == 1 && groups[0].Name == "Friends", "seeded in English");
        Hex.True(store.GetProfileMessage(1) == "", "and with no greeting");

        SocialHandlers.ProvideSampleGroup(store, 2, TeraSharp.Arbiter.Auth.LoginLanguage.Twn);
        var tw = store.GetFriendGroups(2);
        Hex.True(tw.Count == 1 && tw[0].Name == SocialHandlers.SampleGroupNameTw, "seeded in Chinese");
        Hex.True(store.GetProfileMessage(2) == SocialHandlers.DefaultProfileMessageTw, "with the greeting");

        // once only, whatever the language
        SocialHandlers.ProvideSampleGroup(store, 1, TeraSharp.Arbiter.Auth.LoginLanguage.Twn);
        Hex.True(store.GetFriendGroups(1)[0].Name == "Friends",
            "the seed is once per character - dbo.spIsProvideSampleFriendGroup");
    }

    // =======================================================================================
    // T49 - PartyWiring. Research: status/PARTY-DESIGN.md section 10 (and the T49 notes in 11).
    //
    // T35 left PartyManager pure and unwired. These drive the WIRING - PartyWiring's own static
    // entry points, over the T41 dispatcher with recording fakes - so what is checked is the code
    // the two human-owned lines will call, not a copy of it written a second time in the test.
    //
    // No capture contains a party frame, so the SA_ inputs are the same golden payload builders
    // T35's tests use (PARTY-DESIGN.md section 5.1, from the decompiled writers).
    // =======================================================================================

    /// <summary>
    /// The registration numbers, and the one mistake this pair exists to stop.
    /// <c>PacketDispatcher.Register</c> takes a minimum BODY length and compares it against
    /// <c>packet[4..]</c>; every guard in the decompile is a FRAME length that includes the
    /// 4-byte <c>[u16 len][u16 opcode]</c> header. Registering the frame figure would drop
    /// C_APPLY_PARTY (4-byte body vs a "min 8"), and C_DISMISS_PARTY - which has no guard and no
    /// body at all - would never run.
    /// </summary>
    [Test] public static void T49_party_registrations_use_the_body_length_not_the_frame_length()
    {
        // (name, opcode, the decompile's frame guard)
        var expected = new (string Name, ushort Op, int Frame)[]
        {
            ("C_APPLY_PARTY",              0xA889, 0x08),   // FUN_1404db920 Arb_part_040.c:19121
            ("C_PARTY_APPLICATION_DENIED", 0x4F00, 0x08),   // FUN_1404e3f60 Arb_part_041.c:5023
            ("C_DISMISS_PARTY",            0xC8B9, 0x04),   // FUN_1404def50 - no guard at all
            ("C_BAN_PARTY_MEMBER",         0x59C1, 0x0C),   // FUN_1404dbcb0 Arb_part_040.c:19255
            ("C_PARTY_LOOTING_METHOD",     0x5D24, 0x17),   // FUN_1404e40a0 Arb_part_041.c:5086
            ("C_MERGE_PARTY_TO_RAID",      0xB8D0, 0x0D),   // FUN_1404e3870 Arb_part_041.c:4724
            ("C_REQUEST_PARTY_INFO",       0xFD35, 0x08),   // FUN_1404e9b50 Arb_part_041.c:8911
        };

        Hex.True(PartyWiring.ClientOpcodes.Length == expected.Length,
            $"seven Arbiter-side party opcodes, got {PartyWiring.ClientOpcodes.Length}");

        for (int i = 0; i < expected.Length; i++)
        {
            var (name, op, frame) = expected[i];
            var (gotName, gotOp) = PartyWiring.ClientOpcodes[i];
            Hex.True(gotName == name && gotOp == op,
                $"slot {i}: expected {name} 0x{op:X4}, got {gotName} 0x{gotOp:X4}");
            Hex.True(PartyWiring.MinFrameLength(op) == frame,
                $"{name} frame guard: want 0x{frame:X2}, got 0x{PartyWiring.MinFrameLength(op):X2}");
            Hex.True(PartyWiring.MinBodyLength(op) == frame - PartyWiring.ClientHeaderSize,
                $"{name} body minimum must be the frame guard minus the 4-byte header, " +
                $"got {PartyWiring.MinBodyLength(op)} for frame 0x{frame:X2}");
            Hex.True(PartyWiring.IsArbiterSide(op), $"{name} is Arbiter-side");
        }

        // The two the party UI sends that the real Arbiter has NO handler for. They must stay
        // unregistered so PacketDispatcher keeps forwarding them to World, which answers with
        // SA_LEAVE_PARTY / SA_CHANGE_PARTY_MANAGER.
        Hex.True(!PartyWiring.IsArbiterSide(0xFFB6), "C_LEAVE_PARTY belongs to World");
        Hex.True(!PartyWiring.IsArbiterSide(0x60D6), "C_CHANGE_PARTY_MANAGER belongs to World");
        Hex.True(PartyWiring.MinBodyLength(0xFFB6) == 0 && PartyWiring.MinFrameLength(0xFFB6) == 0,
            "and neither table answers for an opcode we do not own");
    }

    /// <summary>
    /// The gate the one WorldBridge line uses. It has to be true for every W-&gt;A party opcode
    /// (so the frame reaches the manager instead of the replay table) and false for everything
    /// else (so nothing else is stolen). SA_BYPASS_TO_GROUP 0x13F8 sits one below the tunnel
    /// opcode 0x13F7, which HandleFrame answers in its own case - a gate that caught that would
    /// break every client packet World sends.
    /// </summary>
    [Test] public static void T49_the_world_frame_gate_is_exactly_the_party_opcodes()
    {
        ushort[] party =
        {
            0x1395, 0x1396, 0x1397, 0x1398, 0x1399, 0x139A, 0x139B, 0x139C, 0x139D,
            0x13AB, 0x13AC, 0x13F8,
        };
        foreach (ushort op in party)
        {
            Hex.True(PartyWiring.HandlesWorldFrame(op), $"0x{op:X4} must reach PartyManager");
            Hex.True(!WorldReplayTable.OneWayFromWorld.Contains(op),
                $"0x{op:X4} is not in the replay table's one-way set - nothing is being taken away");
            Hex.True(!DbProxyHandlers.IsHandledRequest(op),
                $"0x{op:X4} is not a DB-proxy request either");
        }
        Hex.True(party.Length == 12, "twelve W->A party opcodes");

        // the neighbours, and a sample of what else crosses that default: arm
        foreach (ushort op in new ushort[] { 0x13F7, 0x13F2, 0x13FA, 0x13AA, 0x13B6, 0x1394,
                                             0x139F, 0x13A0, 0x2809, 0x27A2, 0x1436 })
            Hex.True(!PartyWiring.HandlesWorldFrame(op), $"0x{op:X4} must NOT be gated to parties");
    }

    /// <summary>
    /// The whole point of T49: two live sessions, invite -&gt; accept -&gt; leave, every packet
    /// arriving through PartyWiring's own entry points and the real ActionDispatcher. The sinks
    /// are fakes, so no socket and no GameSession - ActionDispatcher.ForSessions binds the same
    /// IClientSink to the real one.
    /// </summary>
    [Test] public static void T49_two_sessions_invite_accept_and_leave_through_the_dispatcher()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob"));            // ticket 10, character 1 - the one invited from
        pm.Register(P(11, 2, "Test"));           // ticket 11, character 2 - the applicant

        var h = new DispatchHarness().Build();
        var leader = h.Ticket(10);
        var joiner = h.Ticket(11);

        // ---- invite: C_APPLY_PARTY arrives on ticket 11 and is answered to the TARGET ----
        var r1 = PartyWiring.DispatchClientPacket(pm, h.Dispatcher, 11,
            PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(1));
        Hex.True(r1.ClientsSent == 1 && !r1.RejectionSent, $"apply: {r1}");
        Hex.True(string.Join(",", leader.Log) == "def:S_OTHER_USER_APPLY_PARTY", string.Join(",", leader.Log));
        Hex.True(joiner.Log.Count == 0, "the applicant hears nothing back");
        Hex.True(pm.HasApplication(2, 1), "the pending edge is remembered");

        // ---- accept: World completes the handshake and tells us with SA_JOIN_PARTY ----
        leader.Log.Clear(); joiner.Log.Clear();
        var r2 = PartyWiring.DispatchWorldFrame(pm, h.Dispatcher,
            PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        var party = pm.FindByMember(1);
        Hex.True(party != null && party.Count == 2, "the party exists and holds both");
        Hex.True(party!.IsManager(1), "the inviter is the manager");
        Hex.True(!pm.HasApplication(2, 1), "and the application edge is spent");

        Hex.True(string.Join(",", leader.Log) == "def:S_PARTY_MEMBER_LIST", string.Join(",", leader.Log));
        Hex.True(string.Join(",", joiner.Log) == "def:S_PARTY_MEMBER_LIST", string.Join(",", joiner.Log));
        Hex.True(r2.WorldSent == 5 && h.WorldLog.Count == 5 && h.WorldLog[0].Op == PartyPackets.AS_DO_CREATE_PARTY
                 && h.WorldLog[1].Op == PartyPackets.AS_CHANGE_EVENT_MATCHING_STATE
                 && h.WorldLog[3].Op == PartyPackets.AS_REQUEST_REFRESH_PARTY_INFO,
            $"World gets the member list plus the T64 per-member pushes: {r2}");
        Hex.True(!r2.RejectionSent, "a World frame has no originating client to reject to");

        // ---- leave: the joiner presses the button, World answers with SA_LEAVE_PARTY ----
        leader.Log.Clear(); joiner.Log.Clear(); h.WorldLog.Clear();
        var r3 = PartyWiring.DispatchWorldFrame(pm, h.Dispatcher,
            PartyPackets.SA_LEAVE_PARTY, SaLeavePartyPayload(party.Id, 2));

        // the leaver is told they left; the other is told who left; then the party of one dissolves
        Hex.True(string.Join(",", joiner.Log) == "def:S_LEAVE_PARTY", string.Join(",", joiner.Log));
        Hex.True(string.Join(",", leader.Log) == "def:S_LEAVE_PARTY_MEMBER,def:S_LEAVE_PARTY",
            string.Join(",", leader.Log));
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x13A0,0x13A1",
            "AS_DO_REMOVE_PARTY_MEMBER then AS_DO_DISMISS_PARTY: " +
            string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));
        Hex.True(r3.ClientsDropped == 0, $"nobody was unreachable: {r3}");
        Hex.True(pm.FindByMember(1) == null && pm.FindByMember(2) == null && pm.PartyCount == 0,
            "a party that falls to one member is not a party - New_CreateParty refuses to make one");
    }

    /// <summary>
    /// A refused party command is not a log line the player never sees. PartyManager stamps the
    /// originating ticket, so ActionDispatcher relays the reason as S_SYSTEM_MESSAGE_CUSTOM - to
    /// the sender, and to nobody else.
    /// </summary>
    [Test] public static void T49_a_refused_party_command_answers_the_sender_only()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob"));
        pm.Register(P(11, 2, "Test"));

        var h = new DispatchHarness().Build();
        var sender = h.Ticket(11);
        var bystander = h.Ticket(10);

        var r = PartyWiring.DispatchClientPacket(pm, h.Dispatcher, 11,
            PartyPackets.C_APPLY_PARTY, BitConverter.GetBytes(99));   // 99 is not online
        Hex.True(r.RejectionSent && r.ClientsSent == 0, $"nothing happened, and the sender was told: {r}");
        Hex.True(string.Join(",", sender.Log) == $"def:{ActionDispatcher.RejectionPacket}",
            string.Join(",", sender.Log));
        Hex.True(bystander.Log.Count == 0, "and nobody else heard about it");

        // An unregistered ticket - a packet that arrived after the session went away - is the
        // same shape: refused, not thrown, and not sent to whoever holds that ticket next.
        var ghost = PartyWiring.DispatchClientPacket(pm, h.Dispatcher, 4095,
            PartyPackets.C_DISMISS_PARTY, Array.Empty<byte>());
        Hex.True(!ghost.AnythingSent, $"an unknown ticket sends nothing at all: {ghost}");
    }

    /// <summary>
    /// Logging out does NOT break the party: PartyMemberInfo+0x70 is an Online flag, not a
    /// removal (PartyManager::MemberLeaveWorld), so the slot is kept and the rest are told with
    /// S_LOGOUT_PARTY_MEMBER. This is the path SocialHandlers.UnregisterChat now drives, which is
    /// why no new line is needed in the human-owned GameSession.
    /// </summary>
    [Test] public static void T49_logging_out_keeps_the_party_and_tells_the_others()
    {
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob"));
        pm.Register(P(11, 2, "Test"));

        var h = new DispatchHarness().Build();
        var stays = h.Ticket(10);
        var leaves = h.Ticket(11);
        PartyWiring.DispatchWorldFrame(pm, h.Dispatcher, PartyPackets.SA_JOIN_PARTY, SaJoinPartyPayload(1, 2));
        var party = pm.FindByMember(1)!;
        stays.Log.Clear(); leaves.Log.Clear(); h.WorldLog.Clear();

        var r = PartyWiring.DispatchLeave(pm, h.Dispatcher, 11);

        Hex.True(string.Join(",", stays.Log) == "def:S_LOGOUT_PARTY_MEMBER", string.Join(",", stays.Log));
        Hex.True(leaves.Log.Count == 0, "the one who left is not told about themselves");
        Hex.True(h.WorldLog.Count == 0, "World already knows - it is the one that despawned them");
        Hex.True(r.ClientsSent == 1, $"{r}");

        Hex.True(pm.PartyCount == 1 && pm.FindByMember(2) == party,
            "the party survives and still holds the offline member");
        int slot = party.IndexOf(2);
        Hex.True(slot >= 0 && party.Slots[slot]!.Value.Online == false, "the slot is kept, marked offline");
        Hex.True(!pm.TryGetTicket(2, out _), "but the ticket is gone, so nothing is sent to it");

        // coming back online re-flags the same slot rather than making a second one
        pm.Register(P(12, 2, "Test"));
        Hex.True(party.IndexOf(2) == slot && party.Slots[slot]!.Value.Online,
            "the same slot comes back online - slot indices are wire-visible and must not shift");
        Hex.True(party.Count == 2, "and there is still exactly one of them");
    }

    /// <summary>
    /// C_REQUEST_PARTY_INFO is Arbiter-owned (Handler_C_REQUEST_PARTY_INFO queues a
    /// PartyMatchManager job) but party matching is not modelled - none of the three shipped
    /// S_PARTY_MEMBER_INFO defs matches the v100 writer. Section 10's wiring hands all seven
    /// straight to the manager, which would answer this one with a system-message rejection every
    /// time the panel opens. It is registered (so it never reaches World, which has no handler
    /// either) and swallowed.
    /// </summary>
    [Test] public static void T49_the_party_match_query_is_swallowed_rather_than_refused()
    {
        Hex.True(PartyWiring.IsArbiterSide(PartyPackets.C_REQUEST_PARTY_INFO),
            "it is registered, so PacketDispatcher never forwards it to World");
        Hex.True(PartyWiring.NotModelled.Contains(PartyPackets.C_REQUEST_PARTY_INFO),
            "and it is the one we deliberately do not answer");
        Hex.True(PartyWiring.NotModelled.Count == 1, "only that one");

        // the reason: the manager's switch has no case for it, so it would reject
        var pm = NewPartyManager();
        pm.Register(P(10, 1, "dob"));
        var direct = pm.OnClientPacket(10, PartyPackets.C_REQUEST_PARTY_INFO, BitConverter.GetBytes(1));
        Hex.True(direct.IsEmpty && direct.Rejected != null,
            "PartyManager would refuse it - which is what the swallow exists to stop");

        // the other six do reach the manager
        foreach (var (name, op) in PartyWiring.ClientOpcodes)
            Hex.True(PartyWiring.NotModelled.Contains(op) == (op == PartyPackets.C_REQUEST_PARTY_INFO),
                $"{name} routing");
    }

    /// <summary>
    /// The roster edge, through the static the wiring actually uses. PartyWiring.Register is
    /// called from SocialHandlers.RegisterChat, so a character that is online for whisper is
    /// online for parties too - one roster, not two that can disagree.
    /// </summary>
    [Test] public static void T49_the_shared_roster_registers_a_player_for_parties()
    {
        PartyWiring.ResetForTests();
        try
        {
            Hex.True(!PartyWiring.Manager.TryGetPlayer(77, out _), "nobody yet");

            PartyWiring.Register(ticket: 77, userDbId: 9, name: "dob", level: 65, cls: 12,
                                 race: 4, gender: 1, gameId: 0x80000AF00009UL);

            Hex.True(PartyWiring.Manager.TryGetPlayer(77, out var p), "the ticket resolves");
            Hex.True(p.UserDbId == 9 && p.Name == "dob" && p.Level == 65 && p.Class == 12
                     && p.Race == 4 && p.Gender == 1,
                $"the character came through intact: db {p.UserDbId} '{p.Name}' L{p.Level} c{p.Class}");
            Hex.True(PartyWiring.Manager.TryGetTicket(9, out uint back) && back == 77,
                "and the reverse lookup, which is how a broadcast finds a member");

            // idempotent: the enter-world call and SyncRoster's self-heal both run
            PartyWiring.Register(ticket: 77, userDbId: 9, name: "dob", level: 66, cls: 12,
                                 race: 4, gender: 1, gameId: 0x80000AF00009UL);
            Hex.True(PartyWiring.Manager.TryGetPlayer(77, out var again) && again.Level == 66,
                "re-registering updates rather than duplicating");
        }
        finally { PartyWiring.ResetForTests(); }
    }


    /// <summary>Reset the recording fakes AND the World log between the steps of a scenario.
    /// FakeSink.Bodies is a separate list from FakeSink.Log, so clearing only the log leaves the
    /// next Bodies[0] pointing at the previous step's packet.</summary>
    static void ClearSinks(DispatchHarness h, params FakeSink[] sinks)
    {
        foreach (var s in sinks) { s.Log.Clear(); s.Bodies.Clear(); }
        h.WorldLog.Clear();
    }

    // =======================================================================================
    // T51 - GuildWiring. Research: status/GUILD-DESIGN.md section 11 (and section 10's diff,
    // which this supersedes in four places).
    //
    // T39 left GuildHandlers pure and unwired. These drive the WIRING - GuildWiring's own static
    // entry points, over the T41 dispatcher with recording fakes - so what is checked is the code
    // the one human-owned line will call, not a copy of it written a second time here.
    //
    // The boot load is the one piece with ground truth: data/cap_guild.bin seq 2 is the real
    // Arbiter's "no guilds" terminator, and answering 0x27CF from rows has to reproduce it.
    // =======================================================================================

    /// <summary>
    /// The registration numbers, and the mistake this pair exists to stop.
    /// <c>PacketDispatcher.Register</c> takes a minimum BODY length and compares it against
    /// <c>packet[4..]</c>; <c>GuildPackets.MinClientLength</c> is a TOTAL packet length that
    /// includes the 4-byte header. Section 10's diff passes the total straight through, which
    /// rejects every guild packet four bytes short - the bug status/CLIENT-REJECTS.md section
    /// 7.2c already recorded against both the guild and the chat wiring.
    /// </summary>
    [Test] public static void T51_guild_registrations_use_the_body_length_not_the_frame_length()
    {
        Hex.True(GuildWiring.ClientOpcodes.Length == 19,
            $"nineteen Arbiter-answered guild opcodes after T52, got {GuildWiring.ClientOpcodes.Length}");
        Hex.True(GuildWiring.ClientHeaderSize == 4, "the client header is [u16 len][u16 opcode]");

        foreach (var (name, op) in GuildWiring.ClientOpcodes)
        {
            int frame = GuildWiring.MinFrameLength(op);
            Hex.True(frame >= 4, $"{name}: frame guard {frame} is shorter than the header itself");
            Hex.True(GuildWiring.MinBodyLength(op) == frame - GuildWiring.ClientHeaderSize,
                $"{name}: body minimum must be the frame guard minus 4, got "
                + $"{GuildWiring.MinBodyLength(op)} for frame 0x{frame:X2}");
            Hex.True(GuildWiring.IsRegistered(op), $"{name} is one of the seventeen");
        }

        // Fifteen come straight from GuildPackets; the two that do not are the packets whose
        // names contain no GUILD, so T36's sweep never saw them.
        foreach (var (name, op) in GuildWiring.ClientOpcodes)
        {
            if (op == GuildHandlers.C_REQUEST_UPDATE_ANNOUNCE || op == GuildHandlers.C_REQUEST_UPDATE_INTRODUCE)
            {
                Hex.True(GuildPackets.MinClientLength(op) == 0, $"{name} is not in GuildPackets");
                Hex.True(GuildWiring.MinFrameLength(op) == 6, $"{name}: [u16 off] + wstring, min total 6");
                Hex.True(GuildWiring.MinBodyLength(op) == 2, $"{name}: body 2");
                continue;
            }
            Hex.True(GuildWiring.MinFrameLength(op) == GuildPackets.MinClientLength(op),
                $"{name}: the frame guard is GuildPackets'");
        }

        // a couple of the numbers spelled out, so a silent edit to GuildPackets is visible here
        Hex.True(GuildWiring.MinBodyLength(GuildPackets.C_REQUEST_GUILD_INFO) == 0x0C - 4,
            "C_REQUEST_GUILD_INFO: [i32 guildDbId][i32 windowType] = 8 bytes of body");
        Hex.True(GuildWiring.MinBodyLength(GuildPackets.C_GUILD_APPLY_LIST) == 0,
            "C_GUILD_APPLY_LIST is header-only");
        Hex.True(GuildWiring.MinBodyLength(GuildPackets.C_ACCEPT_GUILD_APPLY) == 5,
            "C_ACCEPT_GUILD_APPLY: [u8 accept][u32 userDbId], unaligned");

        // T52 registered the last two Arbiter-side packets, so every one of section 5.1 is ours.
        Hex.True(GuildWiring.IsRegistered(GuildPackets.C_INVITE_USER_TO_GUILD)
                 && GuildWiring.MinBodyLength(GuildPackets.C_INVITE_USER_TO_GUILD) == 0x0B - 4,
            "C_INVITE_USER_TO_GUILD: [u16 nameOff][u32 userDbId][u8 fromWantedList] = 7 bytes of body");
        Hex.True(GuildWiring.IsRegistered(GuildPackets.C_CHANGE_GUILDNAME)
                 && GuildWiring.MinBodyLength(GuildPackets.C_CHANGE_GUILDNAME) == 0x06 - 4,
            "C_CHANGE_GUILDNAME: [u16 off] + wstring = 2 bytes of body");
        // The ten that belong to WorldServer. Answering one double-answers the client.
        foreach (ushort op in new ushort[] { 0x7C83, 0xE303, 0xC4CC, 0x8C0F, 0xBC8A,
                                             0x8148, 0x73F1, 0xE885, 0xA6EF, 0x99CC })
        {
            Hex.True(!GuildWiring.IsRegistered(op), $"0x{op:X4} is World's (GUILD-DESIGN section 5.2)");
            Hex.True(GuildWiring.MinBodyLength(op) == 0, $"0x{op:X4} has no entry in either table");
        }
    }

    // T48 - the fuzz suite. status/SECURITY-AUDIT.md.
    //
    // Every bug this audit found is a packet-derived value used as a count, an index or a
    // length. Static reading found four of them; this is the part that keeps finding them after
    // the audit is over. For every registered client opcode and every allow-listed DB-proxy
    // opcode it dispatches 200 hostile bodies and asserts nothing escapes.
    //
    // WHAT "nothing escapes" MEANS HERE, precisely. PacketDispatcher already catches everything,
    // so "no exception reached the caller" is true by construction and proves nothing. What the
    // client fuzz actually asserts is that the dispatcher never took its `catch (Exception)`
    // branch - the one that logs at Error level. A PacketReadException is fine (it is the codec
    // saying "malformed", which is the designed answer); an IndexOutOfRange, an Overflow, an
    // ArgumentOutOfRange or a NullReference is a finding. The capturing logger below is what
    // makes that distinction observable.
    // =======================================================================================

    /// <summary>
    /// One line per distinct (where, exception) pair, most frequent first, each with its count
    /// and one sample message.
    ///
    /// <para>T50. The first real run of this suite printed its first 20 failure lines and every
    /// one of them was the same finding, so the report said nothing at all about the other 106.
    /// Counting distinct pairs is the list that is actually actionable: the 126 client errors
    /// were two findings and the 21 DB-proxy failures were two more.</para>
    /// </summary>
    static List<string> FuzzSummary(IEnumerable<(string Key, string Sample)> items)
    {
        var order = new List<string>();
        var count = new Dictionary<string, int>(StringComparer.Ordinal);
        var sample = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var (key, text) in items)
        {
            if (!count.ContainsKey(key)) { order.Add(key); count[key] = 0; sample[key] = text; }
            count[key]++;
        }
        order.Sort((a, b) => count[b] != count[a]
            ? count[b].CompareTo(count[a])
            : string.CompareOrdinal(a, b));
        var outp = new List<string>();
        foreach (var key in order) outp.Add($"{count[key]} x {key}  --  {sample[key]}");
        return outp;
    }

    /// <summary>
    /// The (packet or opcode, exception type) pair a captured log line is about. Everything else
    /// in the message - the session guid, the body length, the offending index - varies per body
    /// and would make every line distinct, which is exactly how the first run lost its findings.
    /// </summary>
    static string FuzzKeyOf(string error)
    {
        var where = System.Text.RegularExpressions.Regex.Match(
            error, @"\b(0x[0-9A-Fa-f]{4}|(?:C|SDB|DBS|SA|AS|S)_[A-Z0-9_]+)\b");
        int colon = error.IndexOf(':');
        string who = where.Success ? where.Groups[1].Value : colon > 0 ? error[..colon] : error;
        var kind = System.Text.RegularExpressions.Regex.Match(error, @"\b([A-Za-z0-9_]*Exception)\b");
        return $"{who} / {(kind.Success ? kind.Groups[1].Value : "logged at Error")}";
    }

    /// <summary>An ILogger that remembers what was logged at Error level or above.</summary>
    sealed class CapturingLogger : Microsoft.Extensions.Logging.ILogger
    {
        public readonly List<string> Errors = new();
        private readonly string _name;
        public CapturingLogger(string name) => _name = name;

        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
        public bool IsEnabled(Microsoft.Extensions.Logging.LogLevel level) => true;

        public void Log<TState>(Microsoft.Extensions.Logging.LogLevel level,
            Microsoft.Extensions.Logging.EventId id, TState state, Exception? ex,
            Func<TState, Exception?, string> fmt)
        {
            if (level < Microsoft.Extensions.Logging.LogLevel.Error) return;
            Errors.Add($"{_name}: {fmt(state, ex)}"
                + (ex != null ? $" [{ex.GetType().Name}: {ex.Message}]" : ""));
        }
    }

    /// <summary>An ILoggerFactory whose loggers all funnel into one <see cref="CapturingLogger"/>
    /// list, so a handler that logs its own error is caught as well as one that throws.</summary>
    sealed class CapturingLoggerFactory : Microsoft.Extensions.Logging.ILoggerFactory
    {
        public readonly List<string> Errors = new();
        public void AddProvider(Microsoft.Extensions.Logging.ILoggerProvider provider) { }
        public Microsoft.Extensions.Logging.ILogger CreateLogger(string categoryName)
            => new ForwardingLogger(this, categoryName);
        public void Dispose() { }

        private sealed class ForwardingLogger : Microsoft.Extensions.Logging.ILogger
        {
            private readonly CapturingLoggerFactory _f; private readonly string _n;
            public ForwardingLogger(CapturingLoggerFactory f, string n) { _f = f; _n = n; }
            public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
            public bool IsEnabled(Microsoft.Extensions.Logging.LogLevel level) => true;
            public void Log<TState>(Microsoft.Extensions.Logging.LogLevel level,
                Microsoft.Extensions.Logging.EventId id, TState state, Exception? ex,
                Func<TState, Exception?, string> fmt)
            {
                if (level < Microsoft.Extensions.Logging.LogLevel.Error) return;
                lock (_f.Errors)
                    _f.Errors.Add($"{_n}: {fmt(state, ex)}"
                        + (ex != null ? $" [{ex.GetType().Name}: {ex.Message}]" : ""));
            }
        }
    }

    /// <summary>
    /// The registered set and <see cref="GuildHandlers.Handles"/> must be the same set, in both
    /// directions. Registering an opcode the handler does not answer would reply to the player
    /// with an S_SYSTEM_MESSAGE_CUSTOM rejection every time they opened that window; leaving one
    /// out forwards it to World, which answers "handler has not been implemented yet!!!".
    /// </summary>
    [Test] public static void T51_the_registered_set_is_exactly_what_GuildHandlers_answers()
    {
        var registered = GuildWiring.ClientOpcodes.Select(c => c.Opcode).ToHashSet();
        Hex.True(registered.Count == GuildWiring.ClientOpcodes.Length, "no duplicate opcodes");

        var answered = new List<ushort>();
        for (int op = 0; op <= ushort.MaxValue; op++)
            if (GuildHandlers.Handles((ushort)op)) answered.Add((ushort)op);

        var missing = answered.Where(o => !registered.Contains(o)).ToArray();
        Hex.True(missing.Length == 0,
            "GuildHandlers answers these but GuildWiring does not register them, so they are "
            + "forwarded to World: " + string.Join(", ", missing.Select(o => $"0x{o:X4}")));

        var extra = registered.Where(o => !GuildHandlers.Handles(o)).ToArray();
        Hex.True(extra.Length == 0,
            "GuildWiring registers these but GuildHandlers has no case, so every one would answer "
            + "the player with a rejection: " + string.Join(", ", extra.Select(o => $"0x{o:X4}")));

        Hex.True(answered.Count == 19, $"nineteen answered opcodes after T52, saw {answered.Count}");
    }

    /// <summary>
    /// <b>ResolveDef is not optional for guilds.</b> GameSession.SendByDef resolves from the
    /// SHIPPED registry, and ten guild .def files are wrong (GUILD-DESIGN section 5.5). The
    /// dispatcher GuildWiring builds must carry GuildHandlers.ResolveDef, or S_ADD_GUILD_MEMBER
    /// goes out with the .def's 0x33-byte body instead of the 0x38 the dumper guard proves.
    /// </summary>
    [Test] public static void T51_the_wiring_dispatcher_carries_the_corrected_defs()
    {
        var d = GuildWiring.Dispatcher(null, QuietLog());
        Hex.True(d.ResolveDef != null, "the guild dispatcher must have a ResolveDef hook");

        var corrected = d.ResolveDef!("S_ADD_GUILD_MEMBER");
        Hex.True(corrected != null, "S_ADD_GUILD_MEMBER resolves to the correction, not the .def");

        // the correction, encoded, is 0x38 - the number the Arbiter's own dumper guard gives
        var member = new Dictionary<string, object>
        {
            ["memberDbId"] = 11, ["name"] = "g1", ["worldId"] = 1, ["guardId"] = 2, ["sectionId"] = 3,
            ["groupId"] = 4, ["userLevel"] = 60, ["race"] = 5, ["userClass"] = 6, ["state"] = 0,
            ["gender"] = 1, ["lastLogoutTime"] = 0L, ["isWorldEventTarget"] = false,
            ["cityWarCompensationStatus"] = false,
        };
        var bytes = new TeraSharp.Arbiter.Protocol.DefinitionWriter().Write(corrected!, member);
        Hex.True(BitConverter.ToUInt16(bytes, 0) == 0x38,
            $"fixed part 0x{BitConverter.ToUInt16(bytes, 0):X2}, want 0x38");

        // and a packet with no correction falls through to the session's own registry
        Hex.True(d.ResolveDef("S_NO_CORRECTION_FOR_THIS") == null,
            "an uncorrected packet must take the ordinary SendByDef path");
    }

    /// <summary>
    /// The whole point of T51: two live sessions, create -&gt; apply -&gt; accept -&gt; announce
    /// -&gt; leave, every packet arriving through GuildWiring's own entry points and the real
    /// ActionDispatcher. Guilds address clients by character db id, so the harness's player table
    /// is the one that resolves; the sinks are fakes, so no socket and no GameSession.
    /// </summary>
    [Test] public static void T51_create_invite_accept_announce_leave_across_two_sessions()
    {
        using var store = GuildStore();
        var guilds = NewGuildHandlers(store);
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var chief = h.Player(1);
        var joiner = h.Player(2);

        // ---- create. There is no C_ packet for it: the client asks World, which sends
        //      SDB_CREATE_GUILD2 down the DB-proxy link, so this is the seam that half calls.
        var (guildId, created) = GuildWiring.DispatchCreateGuild(guilds, h.Dispatcher, 1, "Ere");
        Hex.True(guildId > 0, $"CreateGuild returned {guildId}");
        Hex.True(chief.Log.Count == 2
                 && chief.Log[0] == "def:S_REQUEST_JOIN_GUILD_NOTICE"
                 && chief.Log[1].StartsWith("body:S_ADD_GUILD_MEMBER:"),
            "the notice, then the member - and the member through SendRawBody, which is what a "
            + "CORRECTED def looks like on the wire: " + string.Join(",", chief.Log));
        Hex.True(BitConverter.ToUInt16(chief.Bodies[0], 0) == 0x38,
            $"S_ADD_GUILD_MEMBER fixed part 0x{BitConverter.ToUInt16(chief.Bodies[0], 0):X2}, want 0x38 "
            + "- the .def's 0x33 would mean the correction never reached the wire");
        Hex.True(joiner.Log.Count == 0, "character 2 is not in the guild yet");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x140A,0x2866",
            "AS_ADD_GUILDMEMBER (0x140A) then AS_GUILD_JOINED (0x2866), the order "
            + "GuildUtil::UserJoinToGuild sends them: "
            + string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));
        Hex.True(created.ClientsSent == 2, $"{created}");

        // ---- apply. C_INVITE_USER_TO_GUILD still needs the wanted board, so the invite that
        //      IS wired is the applicant's half: the holders of the invite authority are told.
        ClearSinks(h, chief, joiner);
        var applied = GuildWiring.DispatchClientPacket(guilds, h.Dispatcher, 2,
            GuildPackets.C_APPLY_GUILD, CApplyGuildBody("Ere", "let me in"));
        Hex.True(string.Join(",", chief.Log) == "def:S_GUILD_APPLY_COUNT",
            "the chief holds the invite authority: " + string.Join(",", chief.Log));
        Hex.True(joiner.Log.Count == 0 && !applied.RejectionSent, $"the applicant waits: {applied}");
        Hex.True(store.GetGuildApplies(guildId).Count == 1, "spInsertGuildApply wrote the row");

        // ---- accept ----
        ClearSinks(h, chief, joiner);
        var accepted = GuildWiring.DispatchClientPacket(guilds, h.Dispatcher, 1,
            GuildPackets.C_ACCEPT_GUILD_APPLY, CAcceptGuildApplyBody(true, 2));
        Hex.True(store.GetGuildIdOf(2) == guildId, "character 2 is a member");
        Hex.True(store.GetGuildApplies(guildId).Count == 0, "and the application is spent");
        Hex.True(chief.Log.Any(l => l.StartsWith("body:S_ADD_GUILD_MEMBER:"))
                 && joiner.Log.Any(l => l.StartsWith("body:S_ADD_GUILD_MEMBER:")),
            "both members are told about the new one: "
            + string.Join(" | ", chief.Log) + " // " + string.Join(" | ", joiner.Log));
        Hex.True(joiner.Bodies.Count > 0 && BitConverter.ToUInt16(joiner.Bodies[0], 0) == 0x38,
            "and still through the corrected def");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x140A,0x2866",
            string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));
        Hex.True(accepted.ClientsDropped == 0, $"both members were online: {accepted}");

        // ---- announce ----
        ClearSinks(h, chief, joiner);
        GuildWiring.DispatchClientPacket(guilds, h.Dispatcher, 1,
            GuildHandlers.C_REQUEST_UPDATE_ANNOUNCE, CStringBody("raid at 8 & <late>"));
        Hex.True(string.Join(",", chief.Log) == "def:S_UPDATE_GUILD_ANNOUNCE", string.Join(",", chief.Log));
        Hex.True(string.Join(",", joiner.Log) == "def:S_UPDATE_GUILD_ANNOUNCE", string.Join(",", joiner.Log));
        Hex.True(store.GetGuild(guildId)!.Announce == "raid at 8 &amp; &lt;late&gt;",
            $"Guild::UpdateGuildAnnounce escapes & < > in that order: '{store.GetGuild(guildId)!.Announce}'");

        // ---- leave the world. The MEMBERSHIP survives - GuildMemberData+0x70 is a state flag,
        //      not a removal - so the rest of the guild is told, and World's mirror is updated.
        ClearSinks(h, chief, joiner);
        long when = 1_700_000_000L;
        var left = h.Dispatcher.Dispatch(
            GuildWiring.MemberState(store, 2, GuildWiring.StateOffline, when), "guild-leave");

        Hex.True(chief.Log.Count == 1 && chief.Log[0].StartsWith("body:S_UPDATE_GUILD_MEMBER:"),
            string.Join(",", chief.Log));
        Hex.True(BitConverter.ToUInt16(chief.Bodies[0], 0) == 0x39,
            $"S_UPDATE_GUILD_MEMBER fixed part 0x{BitConverter.ToUInt16(chief.Bodies[0], 0):X2}, want 0x39 "
            + "- three trailing bools, not the .def's two");
        Hex.True(joiner.Log.Count == 0, "the member who left is not told about themselves");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x1410",
            "AS_UPDATE_GUILD_MEMBER so World's read-only mirror agrees");
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 24) == GuildWiring.StateOffline,
            "the seventh i32 of AS_UPDATE_GUILD_MEMBER is State");
        Hex.True(left.ClientsSent == 1 && left.WorldSent == 1, $"{left}");

        Hex.True(store.GetGuildIdOf(2) == guildId, "still a member - logging out is not leaving");
        Hex.True(store.GetGuildMember(2)!.LastLogoutTime == when, "and the logout time was stored");

        // coming back online is the same flip the other way
        ClearSinks(h, chief);
        h.Dispatcher.Dispatch(GuildWiring.MemberState(store, 2, GuildWiring.StateOnline, null), "guild-join");
        Hex.True(chief.Log.Count == 1 && chief.Log[0].StartsWith("body:S_UPDATE_GUILD_MEMBER:"),
            string.Join(",", chief.Log));
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 24) == GuildWiring.StateOnline, "state 0");
        Hex.True(store.GetGuildMember(2)!.LastLogoutTime == when, "and the logout time was NOT touched");

        // a character with no guild produces nothing at all - the normal case
        Hex.True(GuildWiring.MemberState(store, 3, GuildWiring.StateOnline, null).IsEmpty,
            "character 3 is in no guild");
        Hex.True(GuildWiring.MemberState(null, 1, GuildWiring.StateOnline, null).IsEmpty,
            "and with no store open, nothing happens rather than throwing");
    }

    /// <summary>
    /// With no guilds the whole 0x27CF answer is the one terminator, and it has to be the frame
    /// the real Arbiter sends - which is what retires the replay entry. data/cap_guild.bin seq 2
    /// is that frame, from arb_world.log; the only bytes we deliberately differ on are the two
    /// uninitialised padding holes it leaks (GUILD-DESIGN section 2.1).
    /// </summary>
    [Test] public static void T51_the_guild_boot_load_is_the_capture_when_there_are_no_guilds()
    {
        // the wiring is what answers it now, not the replay table
        Hex.True(DbProxyHandlers.IsHandledRequest(DbProxyHandlers.SDB_INIT_GUILD),
            "0x27CF must be in the allow-list, or TryHandle falls through to the capture");
        Hex.True(DbProxyHandlers.SDB_INIT_GUILD == 0x27CF, "SDB_INIT_GUILD is 0x27CF");

        foreach (var store in new TeraSharp.Arbiter.Persistence.CharacterStore?[] { null, GuildStore(1) })
        {
            var frames = GuildWiring.BuildInitGuildLoad(store);
            Hex.True(frames.Count == 1, $"no guilds = one frame, got {frames.Count}");
            Hex.True(frames[0].Op == GuildPackets.DBS_INIT_GUILD_DATA, $"0x{frames[0].Op:X4}");
            Hex.Eq(frames[0].Payload, GuildPackets.BuildEmptyDbsInitGuildData(),
                "the empty answer is the terminator and nothing else");
            Hex.True(frames[0].Payload[12] == 0, "Success = 0 - the 'no guilds' terminator");
            store?.Dispose();
        }

        var cap = LoadTsisOrSkip("cap_guild.bin");
        if (cap == null) return;
        Hex.True(cap.TryGetValue(1, out var request) && request!.Length == 0,
            "seq 1 is the zero-length SDB_INIT_GUILD");
        Hex.True(cap.TryGetValue(2, out var capture), "seq 2 is the DBS_INIT_GUILD_DATA terminator");

        var ours = GuildWiring.BuildInitGuildLoad(null)[0].Payload;
        Hex.True(ours.Length == capture!.Length, $"payload {ours.Length} != capture {capture.Length}");

        var allowed = new HashSet<int>();
        foreach (var hole in GuildPackets.GuildDataPaddingHoles) { allowed.Add(13 + hole); allowed.Add(13 + hole + 1); }
        var differ = new List<int>();
        for (int i = 0; i < ours.Length; i++) if (ours[i] != capture[i]) differ.Add(i);
        foreach (var d in differ)
            Hex.True(allowed.Contains(d),
                $"payload byte 0x{d:X4} differs from arb_world.log and is not a GuildData padding hole");
        Hex.True(differ.Count == 2,
            $"arb_world.log leaks exactly 2 uninitialised bytes; we write zeros there. Saw {differ.Count}");
    }

    /// <summary>
    /// With a guild in the table the answer is the full section 4.3 sequence. The three array
    /// frames share one writer (Arb_part_072.c:14299 / :14378 / :14502) whose second u32 is a
    /// BYTE length, not an element count - <c>*local_2508 = count * 0xf0</c> - which is the one
    /// thing worth pinning here, because getting it wrong hands World a member list it reads as
    /// 0xF0 times too short.
    /// </summary>
    [Test] public static void T51_the_guild_boot_load_carries_every_guild_then_the_terminator()
    {
        using var store = GuildStore();
        var guilds = NewGuildHandlers(store);
        var a = new GuildActions();
        int guildId = guilds.CreateGuild(a, 1, "Ere", "Master", "Member");
        guilds.OnClientPacket(2, GuildPackets.C_APPLY_GUILD, CApplyGuildBody("Ere", "hi"));
        guilds.OnClientPacket(1, GuildPackets.C_ACCEPT_GUILD_APPLY, CAcceptGuildApplyBody(true, 2));
        Hex.True(store.GetGuildMembers(guildId).Count == 2, "two members");

        var frames = GuildWiring.BuildInitGuildLoad(store);
        Hex.True(string.Join(",", frames.Select(f => $"0x{f.Op:X4}"))
                 == "0x27ED,0x27D0,0x27D1,0x27D2,0x27D3,0x27ED",
            "the section 4.3 sequence, then the terminator: "
            + string.Join(",", frames.Select(f => $"0x{f.Op:X4}")));

        // 1. the per-guild DBS_INIT_GUILD_DATA, Success = 1, with a real blob
        var data = GuildPackets.ParseDbsInitGuildData(frames[0].Payload);
        Hex.True(data != null && data.Value.Success, "the first frame is Success = 1");
        var blob = data!.Value.GuildData;
        Hex.True(blob.Length == GuildPackets.GuildDataSize, $"GuildData is 0x23A0, got 0x{blob.Length:X}");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildDbId) == guildId, "GuildDbId");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdChiefDbId) == 1, "ChiefDbId");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdGuildLevel) == 1, "GuildLevel");
        Hex.True(BitConverter.ToInt32(blob, GuildPackets.GdJoinMinLevel) == 1
                 && BitConverter.ToInt32(blob, GuildPackets.GdJoinMaxLevel) == 70
                 && BitConverter.ToInt32(blob, GuildPackets.GdGuildJoinType) == 1,
            "the three join fields the capture confirms");
        Hex.Eq(blob[GuildPackets.GdGuildName..(GuildPackets.GdGuildName + 8)], "45 00 72 00 65 00 00 00",
            "GuildName is UTF-16LE, NUL-terminated");
        foreach (var hole in GuildPackets.GuildDataPaddingHoles)
            Hex.True(blob[hole] == 0 && blob[hole + 1] == 0,
                $"we never leak the padding hole at blob 0x{hole:X4}");

        // 2. the three array frames: [u32 off = 0x12][u32 BYTE length][u32 guildDbId][records]
        void CheckArray(byte[] p, int recordSize, int expectedCount, string what)
        {
            Hex.True(BitConverter.ToInt32(p, 0) == 0x12, $"{what}: array offset is frame 0x12");
            Hex.True(BitConverter.ToInt32(p, 4) == expectedCount * recordSize,
                $"{what}: slot 2 is a BYTE length ({expectedCount} x 0x{recordSize:X}), "
                + $"got {BitConverter.ToInt32(p, 4)}");
            Hex.True(BitConverter.ToInt32(p, 8) == guildId, $"{what}: guildDbId");
            Hex.True(p.Length == 12 + expectedCount * recordSize, $"{what}: payload length");
        }
        CheckArray(frames[1].Payload, GuildPackets.GuildGroupDataSize, 2, "DBS_INIT_GUILD_GROUP");
        CheckArray(frames[2].Payload, GuildPackets.GuildMemberDataSize, 2, "DBS_INIT_GUILD_MEMBER");
        CheckArray(frames[3].Payload, GuildWiring.GuildPerkRecordSize, 0, "DBS_INIT_GUILD_PERK_LIST");
        Hex.True(frames[4].Payload.Length == 0, "DBS_LOAD_GUILD_COMPLETE is empty");

        // 3. one member record, at the documented offsets
        var m0 = frames[2].Payload[12..(12 + GuildPackets.GuildMemberDataSize)];
        Hex.True(BitConverter.ToInt32(m0, GuildPackets.GmUserDbId) == 1, "first member is the chief");
        Hex.True(BitConverter.ToInt32(m0, GuildPackets.GmState) == GuildWiring.StateOffline,
            "the load loop forces State = 2; the sessions flip it");
        Hex.True(BitConverter.ToInt32(m0, GuildPackets.GmUnknown0080) == -1, "col 14 loads -1");
        Hex.True(BitConverter.ToInt64(m0, GuildPackets.GmGuildJoinDate) > 0, "GuildJoinDate was stored");

        // 4. and it still ends with the terminator, byte-identical to the empty answer
        Hex.Eq(frames[5].Payload, GuildPackets.BuildEmptyDbsInitGuildData(),
            "the last frame is the Success = 0 terminator World waits for");

        // more members than fit one frame -> more 0x27D1 frames, same header shape
        Hex.True(GuildWiring.MembersPerFrame == 31, "the captures batch members 31 per frame");
    }

    /// <summary>
    /// The 16-byte tagTIMESTAMP_STRUCT GuildData stores. Unset is 1970-01-01, which is what the
    /// capture's three unset timestamps hold - and the reason a 0 in the row must not become a
    /// year-0 struct.
    /// </summary>
    [Test] public static void T51_guild_timestamps_default_to_the_epoch_the_capture_shows()
    {
        Hex.Eq(GuildWiring.Timestamp(0), GuildPackets.BuildEpochTimestamp(), "0 is 1970-01-01");
        Hex.Eq(GuildWiring.Timestamp(-5), GuildPackets.BuildEpochTimestamp(), "so is anything before it");
        Hex.Eq(GuildPackets.BuildEpochTimestamp(), "B2 07 01 00 01 00 00 00 00 00 00 00 00 00 00 00",
            "the wire form the capture carries at blob 0x0080");

        // 2023-11-14 22:13:20 UTC
        Hex.Eq(GuildWiring.Timestamp(1_700_000_000L),
            GuildPackets.BuildTimestamp(2023, 11, 14, 22, 13, 20),
            "a real unix time becomes the same struct, field for field");
    }

    /// <summary>
    /// The hostile body generator. 200 per opcode, deterministic (seeded per opcode) so a
    /// failure is reproducible from the name in the message alone.
    ///
    /// <para>The shapes are the ones that broke things in this audit and in
    /// status/ARBITER-SECURITY-NOTES.md: all-0xFF (every field is -1 or 0xFFFFFFFF at once),
    /// counts and offsets at their extremes, truncations of a plausible packet, and plain
    /// random. Length 0 is included deliberately - several handlers index a body they never
    /// measured.</para>
    /// </summary>
    static IEnumerable<byte[]> FuzzBodies(int seed, int count = 200)
    {
        var rng = new Random(seed);

        // 1. the fixed shapes - every one of these found something somewhere
        yield return Array.Empty<byte>();
        yield return new byte[1];
        yield return new byte[2];
        yield return new byte[3];
        for (int n = 4; n <= 64; n += 4) yield return new byte[n];              // all zero
        for (int n = 4; n <= 64; n += 4) { var b = new byte[n]; Array.Fill(b, (byte)0xFF); yield return b; }

        // 2. count/offset extremes in the first four slots, which is where every array and
        //    bytes header lives
        foreach (ushort a in new ushort[] { 0, 1, 4, 8, 0x7FFF, 0x8000, 0xFFFE, 0xFFFF })
            foreach (ushort b2 in new ushort[] { 0, 4, 8, 0xFFFF })
            {
                var b = new byte[32];
                BitConverter.GetBytes(a).CopyTo(b, 0);
                BitConverter.GetBytes(b2).CopyTo(b, 2);
                BitConverter.GetBytes(a).CopyTo(b, 4);
                BitConverter.GetBytes(b2).CopyTo(b, 6);
                yield return b;
            }

        // 3. i32 extremes at each of the first eight 4-byte slots - the page/index/slot fields
        foreach (int v in new[] { int.MinValue, -1, 0, 1, int.MaxValue, 165191051, 0x40, 0x7FFFFFF })
            for (int slot = 0; slot < 4; slot++)
            {
                var b = new byte[32];
                BitConverter.GetBytes(v).CopyTo(b, slot * 4);
                yield return b;
            }

        // 4. random, including lengths either side of every guard we know about
        int made = 0;
        while (made++ < count)
        {
            int len = rng.Next(0, 3) switch
            {
                0 => rng.Next(0, 40),
                1 => rng.Next(0, 600),
                _ => rng.Next(0, 4096),
            };
            var b = new byte[len];
            rng.NextBytes(b);
            yield return b;
        }
    }

    /// <summary>data.json, the same way LoadDefinitionsOrSkip finds the def folder.</summary>
    static TeraSharp.Arbiter.Protocol.OpcodeTable? LoadOpcodesOrSkip()
    {
        var root = Environment.GetEnvironmentVariable("TERASHARP_DATA") ?? @"D:\v100\TERA_SERVER.100";
        var path = Path.Combine(root, "tera-server-proxy", "data", "data.json");
        if (!File.Exists(path))
        {
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            for (int i = 0; i < 10 && dir != null; i++, dir = dir.Parent)
            {
                var c = Path.Combine(dir.FullName, "tera-server-proxy", "data", "data.json");
                if (File.Exists(c)) { path = c; break; }
            }
        }
        if (!File.Exists(path)) { Console.WriteLine("        (skipped: data.json not found)"); return null; }
        try { return TeraSharp.Arbiter.Protocol.OpcodeTable.LoadFromFile(path, "376012"); }
        catch (Exception ex) { Console.WriteLine($"        (skipped: {ex.Message})"); return null; }
    }

    /// <summary>
    /// The real dispatcher with the real handler set, fed hostile bodies on every registered
    /// opcode. The session sits on an unconnected socket: GameSession.SendRaw already catches
    /// and logs a send failure at Warning, so nothing here depends on the network.
    /// </summary>
    [Test] public static void Fuzz_client_dispatch_survives_hostile_bodies()
    {
        var defs = LoadDefinitionsOrSkip();
        if (defs == null) return;
        var opcodes = LoadOpcodesOrSkip();
        if (opcodes == null) return;

        var factory = new CapturingLoggerFactory();
        var dispatchLog = new CapturingLogger("PacketDispatcher");
        var dispatcher = new TeraSharp.Arbiter.Network.PacketDispatcher(
            new LoggerAdapter<TeraSharp.Arbiter.Network.PacketDispatcher>(dispatchLog));

        HandlerRegistry.RegisterAll(dispatcher, opcodes, defs, factory);
        Hex.True(dispatcher.RegisteredCount > 40,
            $"only {dispatcher.RegisteredCount} handlers registered - the fuzz would prove nothing");

        // T50: registration-time complaints are not fuzz findings. RegisterAll logs at Error for
        // any name missing from the opcode map, and in build 376012 C_CHECK_ALIVE is missing (the
        // client never sends it) - that one line was the 126th "handler error" of the first run.
        // Report it, then start the fuzz from a clean list.
        List<string> registration;
        lock (factory.Errors) { registration = new List<string>(factory.Errors); factory.Errors.Clear(); }
        foreach (var line in registration) Console.WriteLine($"        (registration: {line})");

        using var socket = new System.Net.Sockets.Socket(
            System.Net.Sockets.AddressFamily.InterNetwork,
            System.Net.Sockets.SocketType.Stream,
            System.Net.Sockets.ProtocolType.Tcp);
        var session = new TeraSharp.Arbiter.Network.GameSession(
            socket, dispatcher, opcodes, defs, 376012, 0, QuietLog());

        var names = RegisteredOpcodeNames();
        int packets = 0;
        foreach (var (name, op) in names)
        {
            int seed = op;
            foreach (var body in FuzzBodies(seed))
            {
                var packet = new byte[body.Length + 4];
                BitConverter.GetBytes((ushort)packet.Length).CopyTo(packet, 0);
                BitConverter.GetBytes(op).CopyTo(packet, 2);
                body.CopyTo(packet, 4);
                dispatcher.Dispatch(session, packet);
                packets++;
            }
        }

        var errors = new List<string>();
        errors.AddRange(dispatchLog.Errors);
        lock (factory.Errors) errors.AddRange(factory.Errors);

        var summary = FuzzSummary(errors.Select(e => (FuzzKeyOf(e), e)));
        Hex.True(errors.Count == 0,
            $"{errors.Count} handler error(s) out of {packets} hostile packets across {names.Count} "
            + $"opcodes, {summary.Count} distinct (opcode, exception) pair(s). Each one is a "
            + "packet-derived value used without a bounds check:\n    "
            + string.Join("\n    ", summary));

        Console.WriteLine($"        ({packets} hostile packets over {names.Count} opcodes, no handler errors)");
    }

    /// <summary>Wraps a plain ILogger as ILogger&lt;T&gt; so it can be handed to PacketDispatcher.</summary>
    sealed class LoggerAdapter<T> : Microsoft.Extensions.Logging.ILogger<T>
    {
        private readonly Microsoft.Extensions.Logging.ILogger _inner;
        public LoggerAdapter(Microsoft.Extensions.Logging.ILogger inner) => _inner = inner;
        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => _inner.BeginScope(state);
        public bool IsEnabled(Microsoft.Extensions.Logging.LogLevel level) => _inner.IsEnabled(level);
        public void Log<TState>(Microsoft.Extensions.Logging.LogLevel level,
            Microsoft.Extensions.Logging.EventId id, TState state, Exception? ex,
            Func<TState, Exception?, string> fmt) => _inner.Log(level, id, state, ex, fmt);
    }

    /// <summary>Every (name, opcode) HandlerRegistry registers, read out of its own source so the
    /// list cannot drift from the code.</summary>
    static List<(string Name, ushort Op)> RegisteredOpcodeNames()
    {
        var opcodes = LoadOpcodesOrSkip();
        var outp = new List<(string, ushort)>();
        if (opcodes == null) return outp;
        var path = FindRepoFile(Path.Combine("src", "TeraSharp.Arbiter", "Handlers", "HandlerRegistry.cs"));
        if (path == null) return outp;
        var src = File.ReadAllText(path);
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (System.Text.RegularExpressions.Match m in
                 System.Text.RegularExpressions.Regex.Matches(src, "\"(C_[A-Z0-9_]+)\""))
        {
            string name = m.Groups[1].Value;
            if (!seen.Add(name)) continue;
            if (opcodes.TryGetCode(name, out ushort op)) outp.Add((name, op));
        }
        return outp;
    }

    /// <summary>
    /// The three subsystems that parse client packets outside the def codec, against a real
    /// scratch store. These are the hand-written parsers - the ones the def reader's bounds
    /// checks do not cover.
    /// </summary>
    [Test] public static void Fuzz_subsystem_parsers_survive_hostile_bodies()
    {
        using var store = T48Store();
        var guild = new GuildHandlers(store, QuietLog());
        var chat = new ChatManager(store, QuietLog());
        var party = new PartyManager(QuietLog());

        // a populated world, so the parsers reach past their early-outs
        chat.Register(new ChatPlayer(1, "t1", 0x0400000000000001UL, 60, 2, false));
        chat.Register(new ChatPlayer(2, "t2", 0x0400000000000002UL, 60, 2, false));
        int guildId = 0;
        var create = new GuildActions();
        guildId = guild.CreateGuild(create, 1, "Fuzz");
        Hex.True(guildId > 0, "the scratch guild was created");

        int calls = 0;
        // T50: keyed by (what, exception type) so one finding is one line, however many bodies
        // hit it. The cap is a memory stop, not a reporting one - the old `> 20` cut the run
        // short and hid every opcode after the first failing one.
        var failures = new List<(string Key, string Sample)>();

        void Drive(string what, Action<byte[]> f, int seed)
        {
            foreach (var body in FuzzBodies(seed))
            {
                try { f(body); }
                catch (Exception ex)
                {
                    if (failures.Count < 5000)
                        failures.Add(($"{what} / {ex.GetType().Name}",
                            $"{what} threw {ex.GetType().Name} on a {body.Length}-byte body: {ex.Message}"));
                }
                calls++;
            }
        }

        for (int op = 0; op <= 0xFFFF; op++)
        {
            ushort o = (ushort)op;
            if (GuildHandlers.Handles(o)) Drive($"GuildHandlers 0x{o:X4}", b => guild.OnClientPacket(1, o, b), op);
        }
        foreach (ushort o in new ushort[]
        {
            ChatPackets.C_WHISPER, ChatPackets.C_CHAT, ChatPackets.C_CREATE_PRIVATE_CHANNEL,
            ChatPackets.C_JOIN_PRIVATE_CHANNEL, ChatPackets.C_LEAVE_PRIVATE_CHANNEL,
            ChatPackets.C_KICK_CHANNEL_MEMBER, ChatPackets.C_CHANGE_CHANNEL_PASSWORD,
            ChatPackets.C_REQUEST_PRIVATE_CHANNEL_INFO,
        })
            Drive($"ChatManager 0x{o:X4}", b => chat.OnClientPacket(1, o, b), o);

        foreach (ushort o in PartyFuzzOpcodes())
            Drive($"PartyManager 0x{o:X4}", b => party.OnClientPacket(1, o, b), o);

        // T57: the World -> Arbiter guild frames, which reach the same store methods from the
        // other direction. Its own store, because these frames legitimately DELETE guilds and
        // a body that happens to name the scratch one would otherwise look like corruption.
        using (var worldStore = T48Store())
        {
            var g2 = new GuildHandlers(worldStore, QuietLog());
            Hex.True(g2.CreateGuild(new GuildActions(), 1, "FuzzW") > 0, "the second scratch guild");
            foreach (ushort o in GuildWiring.WorldOpcodes)
                Drive($"GuildWiring 0x{o:X4}", b => GuildWiring.OnWorldFrame(worldStore, o, b), o);
            Hex.True(worldStore.GetCharacter(1) != null, "the store still answers after the guild fuzz");
        }

        var parserSummary = FuzzSummary(failures);
        Hex.True(failures.Count == 0,
            $"{failures.Count} parser failure(s) over {calls} hostile bodies, "
            + $"{parserSummary.Count} distinct (parser, exception) pair(s):\n    "
            + string.Join("\n    ", parserSummary));

        // the store must still be usable afterwards - a fuzzed write that corrupted it would
        // show up here rather than as a silent half-commit
        Hex.True(store.GetCharacter(1) != null, "the store still answers after the fuzz");
        Hex.True(store.GetGuild(guildId) != null, "and the guild row survived");
        Console.WriteLine($"        ({calls} hostile bodies across the three subsystems)");
    }

    /// <summary>Every <c>C_*</c> opcode PartyPackets declares, by reflection - the switch in
    /// PartyManager uses named constants, so reading the names is stabler than parsing cases.</summary>
    static List<ushort> PartyFuzzOpcodes()
    {
        var outp = new List<ushort>();
        foreach (var f in typeof(PartyPackets).GetFields(
                     System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static))
        {
            if (!f.IsLiteral || f.FieldType != typeof(ushort)) continue;
            if (!f.Name.StartsWith("C_", StringComparison.Ordinal)) continue;
            outp.Add((ushort)f.GetRawConstantValue()!);
        }
        return outp;
    }

    /// <summary>
    /// The World side. Every opcode DbProxyHandlers allow-lists, fed hostile payloads. The link
    /// sits on an unconnected socket - WorldLink.SendFrame returns early on !Connected, so the
    /// replies are built (which is the part that can throw) and then dropped.
    ///
    /// <para>This one matters more than the client fuzz, because
    /// <c>WorldLink.ReceiveLoop</c> has no per-frame try/catch: an exception out of any
    /// <c>SDB_</c> handler unwinds to the loop's outer catch and closes the World link, which
    /// disconnects every player at once. status/SECURITY-AUDIT.md section 5.</para>
    /// </summary>
    [Test] public static void Fuzz_dbproxy_dispatch_survives_hostile_frames()
    {
        using var store = T48Store();
        var proxy = new DbProxyHandlers(store, QuietLog());

        using var socket = new System.Net.Sockets.Socket(
            System.Net.Sockets.AddressFamily.InterNetwork,
            System.Net.Sockets.SocketType.Stream,
            System.Net.Sockets.ProtocolType.Tcp);
        var link = new TeraSharp.Arbiter.World.WorldLink(1, socket, null!, QuietLog());

        var ops = new List<ushort>();
        for (int op = 0; op <= 0xFFFF; op++)
            if (DbProxyHandlers.IsHandledRequest((ushort)op)) ops.Add((ushort)op);
        Hex.True(ops.Count >= 30, $"only {ops.Count} allow-listed opcodes - the parser broke, not the code");

        int calls = 0;
        // T50: every opcode is fuzzed, every time. The old `> 20` break stopped the whole run at
        // the 21st failure, which in practice meant it stopped inside 0x27FA and never touched a
        // single opcode above it - the findings for the rest of the table were simply absent.
        var failures = new List<(string Key, string Sample)>();
        foreach (ushort op in ops)
        {
            foreach (var payload in FuzzBodies(op))
            {
                try { proxy.TryHandle(null!, link, op, payload); }
                catch (Exception ex)
                {
                    if (failures.Count < 5000)
                        failures.Add(($"0x{op:X4} {DbProxyOpcodeNames.Describe(op)} / {ex.GetType().Name}",
                            $"0x{op:X4} ({DbProxyOpcodeNames.Describe(op)}) threw "
                            + $"{ex.GetType().Name} on a {payload.Length}-byte payload: {ex.Message}"));
                }
                calls++;
            }
        }

        var dbSummary = FuzzSummary(failures);
        Hex.True(failures.Count == 0,
            $"{failures.Count} DB-proxy failure(s) over {calls} hostile payloads, "
            + $"{dbSummary.Count} distinct (opcode, exception) pair(s). Each one closes "
            + "the World link and disconnects every player:\n    "
            + string.Join("\n    ", dbSummary));

        Hex.True(store.GetCharacter(1) != null, "the store still answers after the fuzz");
        Console.WriteLine($"        ({calls} hostile payloads over {ops.Count} DB-proxy opcodes)");
    }

    /// <summary>A scratch store with two characters, for the fuzz tests.</summary>
    static TeraSharp.Arbiter.Persistence.CharacterStore T48Store()
    {
        var store = new TeraSharp.Arbiter.Persistence.CharacterStore(":memory:", QuietLog());
        var acct = store.GetOrCreateAccount("t48");
        for (int i = 1; i <= 2; i++)
            store.CreateCharacter(new TeraSharp.Arbiter.Persistence.CharacterRecord
            {
                AccountId = acct.Id, Name = "t" + i, Gender = i % 2, Race = 1, Class = 2,
                Level = 60, TemplateId = 10101, Zone = 7005,
                Appearance = new byte[8], Details = new byte[32], Shape = new byte[64], Position = i,
            });
        return store;
    }

    // ------------------------------------------------------- the fixes, pinned

    /// <summary>
    /// The pre-auth one. C_CHECK_VERSION is an array packet, it is the first handler registered,
    /// and MinBodyLength is 4 - so a four-byte body reached DefinitionReader.ReadArray with
    /// count = 65535. Before T48 that pre-sized a List for 65535 entries; with an element chain
    /// pointing at itself it also built 65535 Dictionaries, ~13 MB for a 16-byte packet.
    /// </summary>
    [Test] public static void Reader_rejects_a_hostile_array_count()
    {
        var def = TeraSharp.Arbiter.Protocol.DefinitionParser.ParseText("C_CHECK_VERSION",
            "array   version\n- int32 index\n- int32 value\n");

        // count = 0xFFFF, offset = 0: the array goes nowhere but the count is still 65535
        var a = new byte[4];
        BitConverter.GetBytes((ushort)0xFFFF).CopyTo(a, 0);
        var ra = new DefinitionReader(a).Read(def);
        Hex.True(((List<object>)ra["version"]).Count == 0, "a count with nowhere to point yields nothing");

        // count = 0xFFFF with an element whose `next` points at itself
        var b = new byte[16];
        BitConverter.GetBytes((ushort)0xFFFF).CopyTo(b, 0);
        BitConverter.GetBytes((ushort)8).CopyTo(b, 2);     // offset -> packet 8 = body 4
        BitConverter.GetBytes((ushort)8).CopyTo(b, 4);     // here
        BitConverter.GetBytes((ushort)8).CopyTo(b, 6);     // next -> itself
        BitConverter.GetBytes(1).CopyTo(b, 8);
        BitConverter.GetBytes(1).CopyTo(b, 12);
        var rb = (List<object>)new DefinitionReader(b).Read(def)["version"];
        Hex.True(rb.Count == 1, $"a self-looping chain yields one element, got {rb.Count}");

        // a two-element cycle
        var c = new byte[28];
        BitConverter.GetBytes((ushort)0xFFFF).CopyTo(c, 0);
        BitConverter.GetBytes((ushort)8).CopyTo(c, 2);
        BitConverter.GetBytes((ushort)8).CopyTo(c, 4);  BitConverter.GetBytes((ushort)20).CopyTo(c, 6);
        BitConverter.GetBytes((ushort)20).CopyTo(c, 16); BitConverter.GetBytes((ushort)8).CopyTo(c, 18);
        var rc = (List<object>)new DefinitionReader(c).Read(def)["version"];
        Hex.True(rc.Count == 2, $"a two-element cycle yields two elements, got {rc.Count}");

        // and a real packet still parses exactly as before
        var good = new byte[28];
        BitConverter.GetBytes((ushort)2).CopyTo(good, 0);
        BitConverter.GetBytes((ushort)8).CopyTo(good, 2);
        BitConverter.GetBytes((ushort)8).CopyTo(good, 4);  BitConverter.GetBytes((ushort)20).CopyTo(good, 6);
        BitConverter.GetBytes(0).CopyTo(good, 8); BitConverter.GetBytes(376012).CopyTo(good, 12);
        BitConverter.GetBytes((ushort)20).CopyTo(good, 16); BitConverter.GetBytes((ushort)0).CopyTo(good, 18);
        BitConverter.GetBytes(1).CopyTo(good, 20); BitConverter.GetBytes(376012).CopyTo(good, 24);
        var rg = (List<object>)new DefinitionReader(good).Read(def)["version"];
        Hex.True(rg.Count == 2, $"a real two-entry C_CHECK_VERSION still yields two, got {rg.Count}");
        var first = (Dictionary<string, object>)rg[0];
        Hex.True(Convert.ToInt32(first["value"]) == 376012, "and its fields are unchanged");

        Hex.True(DefinitionReader.MaxElementsPerPacket <= 65535 / 4,
            "the per-packet element budget must be well under what a u16 count can ask for");
    }

    /// <summary>
    /// The pagination one. status/ARBITER-SECURITY-NOTES.md bug #2 is a one-sided bound; ours was
    /// worse, because `(page - 1) * pageSize` overflowed and turned a positive page into a
    /// negative start index that passed `i &lt; all.Count`.
    /// </summary>
    [Test] public static void Pagination_clamps_before_it_multiplies()
    {
        // the exact value that used to produce all[-2147483646] with a page size of 13
        Hex.True(GuildHandlers.ClampPage(165191051, 3) == 3, "a hostile page clamps to the last one");
        Hex.True(GuildHandlers.ClampPage(int.MaxValue, 3) == 3, "so does int.MaxValue");
        Hex.True(GuildHandlers.ClampPage(int.MinValue, 3) == 1, "and int.MinValue clamps up to 1");
        Hex.True(GuildHandlers.ClampPage(-1, 3) == 1, "negatives clamp to 1");
        Hex.True(GuildHandlers.ClampPage(0, 3) == 1, "zero clamps to 1");
        Hex.True(GuildHandlers.ClampPage(2, 3) == 2, "a real page is untouched");
        Hex.True(GuildHandlers.ClampPage(1, 0) == 1, "an empty collection still has page 1");

        // after the clamp the multiply cannot wrap, for any page size this server uses
        foreach (int pageSize in new[] { 13, 20, 0x14 })
            foreach (int page in new[] { 1, 2, 1000, TeraSharp.Arbiter.Persistence.CharacterStore.MaxPageNumber })
            {
                long lo = (long)(page - 1) * pageSize, hi = (long)page * pageSize;
                Hex.True(lo == (page - 1) * pageSize && hi == page * pageSize,
                    $"page {page} x {pageSize} overflows an int");
            }

        // and the store clamps on its own, because it is called from more than one place
        using var store = T48Store();
        int gid = store.CreateGuild("Pagey", chiefDbId: 1, warAcceptable: false);
        Hex.True(store.GetGuildLog(gid, int.MaxValue).Count == 0, "a hostile page returns nothing, not page 1");
        Hex.True(store.GetGuildLog(gid, -5).Count == 0, "and a negative one does not throw");
    }

    /// <summary>
    /// The invite-list parser: a u16 count with a packet-supplied element chain, same shape as
    /// the def reader's arrays and the same three defences.
    /// </summary>
    [Test] public static void Chat_invite_list_parser_bounds_a_hostile_count()
    {
        // count = 0xFFFF in an 8-byte body: there is no room for even one element
        var b = new byte[8];
        BitConverter.GetBytes((ushort)0xFFFF).CopyTo(b, 0);
        BitConverter.GetBytes((ushort)12).CopyTo(b, 2);
        var r = ChatPackets.ParseCCreatePrivateChannel(b);
        Hex.True(r == null || r.Value.invited.Count == 0, "nothing is invited by an 8-byte body");

        // a self-looping element chain
        var c = new byte[16];
        BitConverter.GetBytes((ushort)0xFFFF).CopyTo(c, 0);
        BitConverter.GetBytes((ushort)12).CopyTo(c, 2);   // offset -> packet 12 = body 8
        BitConverter.GetBytes((ushort)12).CopyTo(c, 8);   // here
        BitConverter.GetBytes((ushort)12).CopyTo(c, 10);  // next -> itself
        BitConverter.GetBytes(7).CopyTo(c, 12);
        var rc = ChatPackets.ParseCCreatePrivateChannel(c);
        Hex.True(rc != null && rc.Value.invited.Count == 1,
            $"a self-loop yields one invitee, got {rc?.invited.Count}");
    }

    // =======================================================================================
    // T50 - the three findings the T48 fuzz suite actually produced when it was run for real.
    // status/FUZZ-FINDINGS.txt, status/SECURITY-AUDIT.md.
    // =======================================================================================

    /// <summary>
    /// T50 finding 1, 125 of the 126 client-fuzz errors. C_DELETE_USER.1 is <c>uint32 id</c>, so
    /// the def reader hands the handler a <see cref="uint"/>, and <c>Convert.ToInt32</c> throws
    /// OverflowException for every id past int.MaxValue - which is half of all four-byte values.
    /// It is not a malformed packet, just a large id, and the real handler reinterprets the DWORD
    /// into a signed slot where 0xFFFFFFFF simply matches none of the account's characters.
    /// </summary>
    [Test] public static void DefField_reinterprets_instead_of_throwing()
    {
        Hex.True(DefField.I32(0xFFFFFFFFu) == -1, "0xFFFFFFFF reinterprets to -1");
        Hex.True(DefField.I32(0x80000000u) == int.MinValue, "and 0x80000000 to int.MinValue");
        Hex.True(DefField.U32(-1) == 0xFFFFFFFFu, "U32 gives the same bits back");
        Hex.True(DefField.I64(ulong.MaxValue) == -1L, "the 64-bit pair behaves the same way");
        Hex.True(DefField.I32(null) == 0, "an absent field is 0, not an exception");
        Hex.True(DefField.I32("not a number") == 0, "and so is an unparseable one");
        Hex.True(DefField.I32(float.NaN) == 0, "NaN is 0");
        Hex.True(DefField.I32(double.PositiveInfinity) == int.MaxValue, "infinity clamps");
        Hex.True(DefField.I32(double.NegativeInfinity) == int.MinValue, "both ways");
        Hex.True(DefField.Bool(0u) == false && DefField.Bool(7u), "Bool takes any integer");
        Hex.True(DefField.Str(null).Length == 0, "Str is never null");

        var f = new Dictionary<string, object> { ["id"] = 0xC0000000u };
        Hex.True(DefField.I32(f, "id") == unchecked((int)0xC0000000u), "the dictionary overload agrees");
        Hex.True(DefField.I32(f, "absent") == 0, "a name that is not there is 0");
        Hex.True(DefField.List(f, "absent").Count == 0, "and an absent array is empty, not null");
    }

    /// <summary>
    /// The same finding through the real dispatcher, which is where it was logged at Error:
    /// PacketDispatcher catches everything, so what this asserts is that it never took its
    /// <c>catch (Exception)</c> branch for any id C_DELETE_USER can carry.
    /// </summary>
    [Test] public static void Delete_user_logs_no_error_for_an_id_past_int_max()
    {
        var defs = LoadDefinitionsOrSkip();
        if (defs == null) return;
        var opcodes = LoadOpcodesOrSkip();
        if (opcodes == null) return;
        if (!opcodes.TryGetCode("C_DELETE_USER", out ushort op)) return;

        var factory = new CapturingLoggerFactory();
        var dispatchLog = new CapturingLogger("PacketDispatcher");
        var dispatcher = new TeraSharp.Arbiter.Network.PacketDispatcher(
            new LoggerAdapter<TeraSharp.Arbiter.Network.PacketDispatcher>(dispatchLog));
        HandlerRegistry.RegisterAll(dispatcher, opcodes, defs, factory);
        lock (factory.Errors) factory.Errors.Clear();     // registration noise, not a finding
        dispatchLog.Errors.Clear();

        using var socket = new System.Net.Sockets.Socket(
            System.Net.Sockets.AddressFamily.InterNetwork,
            System.Net.Sockets.SocketType.Stream,
            System.Net.Sockets.ProtocolType.Tcp);
        var session = new TeraSharp.Arbiter.Network.GameSession(
            socket, dispatcher, opcodes, defs, 376012, 0, QuietLog());

        foreach (uint id in new uint[] { 0u, 1u, 0x7FFFFFFFu, 0x80000000u, 0xFFFFFFFFu })
        {
            var packet = new byte[8];
            BitConverter.GetBytes((ushort)8).CopyTo(packet, 0);
            BitConverter.GetBytes(op).CopyTo(packet, 2);
            BitConverter.GetBytes(id).CopyTo(packet, 4);
            dispatcher.Dispatch(session, packet);
        }

        var errors = new List<string>(dispatchLog.Errors);
        lock (factory.Errors) errors.AddRange(factory.Errors);
        Hex.True(errors.Count == 0,
            "C_DELETE_USER must not log an error for any id: " + string.Join(" | ", errors));
    }

    /// <summary>
    /// T50 finding 2, 2 of the 21 DB-proxy failures. <c>off + 16</c> was int arithmetic on a
    /// packet-supplied offset, so a listOff of int.MaxValue - and int.MinValue, which wraps to
    /// the same place - made the sum negative, the bound passed, and BitConverter threw
    /// ArgumentOutOfRangeException. WorldLink.ReceiveLoop has no per-frame catch, so that one
    /// exception closes the World link and disconnects every player.
    /// </summary>
    [Test] public static void Learn_all_crest_bounds_a_wrapping_list_offset()
    {
        foreach (uint listOff in new uint[]
                 { 0u, 19u, 32u, 0x7FFFFFFFu, 0x80000000u, 0xFFFFFFF9u, 0xFFFFFFFFu })
        {
            var req = new byte[32];
            BitConverter.GetBytes(1u).CopyTo(req, 0);
            BitConverter.GetBytes(listOff).CopyTo(req, 4);
            BitConverter.GetBytes(0x1234u).CopyTo(req, 16);
            var r = DbProxyHandlers.BuildLearnAllCrest(req);
            Hex.True(r != null && r.Length >= 13, $"listOff 0x{listOff:X8} must still build a reply");
            Hex.True(BitConverter.ToUInt32(r!, 8) == 0x1234u, "and echo the reqId");
        }

        // the request header is 20 bytes, so the first entry can sit at payload 20 = frame 26
        var loop = new byte[36];
        BitConverter.GetBytes(9u).CopyTo(loop, 0);        // count lies
        BitConverter.GetBytes(26u).CopyTo(loop, 4);       // listOff -> payload 20
        BitConverter.GetBytes(0x77u).CopyTo(loop, 16);    // reqId
        BitConverter.GetBytes(26u).CopyTo(loop, 20);      // this
        BitConverter.GetBytes(26u).CopyTo(loop, 24);      // next -> itself
        BitConverter.GetBytes(4242).CopyTo(loop, 28);     // crestId
        BitConverter.GetBytes(1).CopyTo(loop, 32);        // value
        var rl = DbProxyHandlers.BuildLearnAllCrest(loop);
        Hex.True(rl != null && BitConverter.ToUInt32(rl, 0) == 1,
            $"a self-referential chain yields one entry, got {(rl == null ? -1L : BitConverter.ToUInt32(rl, 0))}");
        Hex.True(rl!.Length == 13 + 16, $"and one entry of payload, got {rl.Length} B");
        Hex.True(BitConverter.ToInt32(rl, 13 + 8) == 4242, "which is the one that was sent");
    }

    /// <summary>
    /// T50 finding 3, 19 of the 21 DB-proxy failures. Microsoft.Data.Sqlite issues
    /// <c>PRAGMA foreign_keys = 1</c> unless the connection string says otherwise, so every
    /// REFERENCES clause in this schema is enforced: an INSERT naming a character that has no row
    /// throws SqliteException 19, and out of a DB-proxy handler that closes the World link and
    /// disconnects everyone. Every per-character INSERT now checks the owner first and drops the
    /// write with a warning - the caller still sends its DLM ack, which is what keeps the user's
    /// DB queue moving (status/HANDOFF.md section 1).
    /// </summary>
    [Test] public static void Per_character_writes_drop_an_owner_that_has_no_row()
    {
        using var store = StoreWithTwoCharacters();
        Hex.True(store.CharacterExists(1) && store.CharacterExists(2), "the fixture has 1 and 2");
        Hex.True(!store.CharacterExists(9999), "and nothing else");
        Hex.True(!store.CharacterExists(0) && !store.CharacterExists(-1), "0 and negatives never exist");

        var payload = new byte[288];
        Hex.True(!store.SaveAchievements(9999, payload), "SaveAchievements drops an unknown owner");
        Hex.True(store.SaveAchievements(1, payload), "and still takes a real one");

        Hex.True(store.UpsertQuest(9999, 1, 1, 1, new byte[80]) == 0, "UpsertQuest drops it");
        Hex.True(!store.AddTutorialTip(9999, 1), "AddTutorialTip drops it");
        Hex.True(store.AddAccomplishedAchievements(9999, new[] { (1, new byte[24]) }).Count == 0,
            "AddAccomplishedAchievements drops it");
        Hex.True(!store.AddFriend(1, 9999), "AddFriend checks the friend as well as the owner");
        Hex.True(!store.AddFriend(9999, 1), "both ends, either way round");
        Hex.True(!store.AddBlock(9999, 1), "AddBlock too");

        // the void ones: the assertion is that none of these throws
        store.SetSerenGuide(9999, 1, 1);
        store.UpsertReputation(9999, 1, new byte[52]);
        store.UpsertDungeonCoolTime(9999, 1, new byte[52]);
        store.SetDungeonClearCount(9999, 1, 1);
        store.UpsertFriend(9999, 1, 0, "", 1);
        store.UpsertFriendGroup(9999, 2, "g");

        // and the real owner is untouched by any of it
        Hex.True(store.GetCharacter(1) != null, "the store still answers afterwards");
        Hex.True(store.GetAchievements(1) != null, "character 1 still has its achievements");
        Hex.True(store.GetAchievements(9999) == null, "and 9999 never got any");
    }

    // =======================================================================================
    // T52 - the guild SA_ direction, and the last two C_ handlers.
    // Research: status/GUILD-DESIGN.md section 12.
    //
    // No capture contains a guild SA_ frame (no guild has ever existed on the tap), so the
    // payloads here are built from GUILD-DESIGN.md section 4.2's layouts, which came from the
    // decompiled handler guards - the same footing the party SA_ tests stand on.
    // =======================================================================================

    /// <summary>SA_LEAVE_GUILD / SA_BANISH_GUILD_MEMBER: `u32 nameOff@06, i64 ArbiterUser@0A,
    /// i32 GuildDbId@12, i32 MemberDbId@16`, frame 0x1A. Payload index = frame - 6.</summary>
    static byte[] SaLeaveGuildPayload(int guildDbId, int memberDbId, string memberName = "")
    {
        var name = new List<byte>();
        foreach (char ch in memberName) { name.Add((byte)ch); name.Add((byte)(ch >> 8)); }
        name.Add(0); name.Add(0);
        var p = new byte[20 + name.Count];
        BitConverter.GetBytes(memberName.Length == 0 ? 0 : 0x1A).CopyTo(p, 0);   // frame-relative
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 4);                   // ArbiterUser
        BitConverter.GetBytes(guildDbId).CopyTo(p, 12);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 16);
        name.CopyTo(p, 20);
        return p;
    }

    /// <summary>
    /// A store with `chars` characters (default: as many as there are members), of which 1..`members`
    /// are in guild "Ere" with character 1 as chief. Returns (store, handlers, guildId).
    /// </summary>
    static (TeraSharp.Arbiter.Persistence.CharacterStore store, GuildHandlers guilds, int guildId)
        T52Guild(int members = 3, int chars = 0)
    {
        var store = GuildStore(Math.Max(chars, members));
        var guilds = NewGuildHandlers(store);
        var a = new GuildActions();
        int guildId = guilds.CreateGuild(a, 1, "Ere", "Master", "Member");
        Hex.True(guildId > 0, $"CreateGuild returned {guildId}");
        for (int id = 2; id <= members; id++)
        {
            guilds.OnClientPacket(id, GuildPackets.C_APPLY_GUILD, CApplyGuildBody("Ere", "hi"));
            guilds.OnClientPacket(1, GuildPackets.C_ACCEPT_GUILD_APPLY, CAcceptGuildApplyBody(true, id));
            Hex.True(store.GetGuildIdOf(id) == guildId, $"character {id} joined");
        }
        return (store, guilds, guildId);
    }

    /// <summary>C_INVITE_USER_TO_GUILD (0xEF92): `[u16 nameOff][u32 userDbId][u8 fromWantedList]`,
    /// min total 0x0B. The name is only consulted when userDbId is 0.</summary>
    static byte[] CInviteBody(string name, int userDbId, bool fromWantedList)
    {
        var b = new byte[7 + (name.Length + 1) * 2];
        BitConverter.GetBytes((ushort)(7 + 4)).CopyTo(b, 0);
        BitConverter.GetBytes(userDbId).CopyTo(b, 2);
        b[6] = (byte)(fromWantedList ? 1 : 0);
        for (int i = 0; i < name.Length; i++) { b[7 + i * 2] = (byte)name[i]; b[8 + i * 2] = (byte)(name[i] >> 8); }
        return b;
    }

    /// <summary>
    /// The gate the one WorldBridge line uses. It has to be true for every W-&gt;A guild opcode
    /// and false for everything else. Unlike the party gate it is a membership test rather than
    /// `MinFrameLength(op) != 0`, because two of the twelve have no known layout and so answer 0 -
    /// and those two still must not reach the replay table, which would hand World somebody
    /// else's reply.
    /// </summary>
    [Test] public static void T52_the_guild_world_frame_gate_is_exactly_the_twelve()
    {
        ushort[] guild =
        {
            0x13FB, 0x13FC, 0x13FE, 0x1400, 0x1402, 0x1404,
            0x1406, 0x1408, 0x140B, 0x140F, 0x1414, 0x145C,
        };
        Hex.True(GuildWiring.WorldOpcodes.Length == 12, $"twelve, got {GuildWiring.WorldOpcodes.Length}");
        Hex.True(string.Join(",", GuildWiring.WorldOpcodes.Select(o => $"0x{o:X4}"))
                 == string.Join(",", guild.Select(o => $"0x{o:X4}")),
            "in opcode order: " + string.Join(",", GuildWiring.WorldOpcodes.Select(o => $"0x{o:X4}")));

        foreach (ushort op in guild)
        {
            Hex.True(GuildWiring.HandlesWorldFrame(op), $"0x{op:X4} must reach GuildWiring");
            Hex.True(!WorldReplayTable.OneWayFromWorld.Contains(op),
                $"0x{op:X4} is not sealed one-way - nothing is being taken away");
            Hex.True(!DbProxyHandlers.IsHandledRequest(op), $"0x{op:X4} is not a DB-proxy request");
        }

        // ten have a layout, two do not - and the gate covers both kinds
        int known = guild.Count(o => GuildPackets.MinFrameLength(o) != 0);
        Hex.True(known == 10, $"ten guild SA_ frames have a pinned layout, saw {known}");
        Hex.True(GuildPackets.MinFrameLength(0x1414) == 0 && GuildPackets.MinFrameLength(0x145C) == 0,
            "SA_INC_GUILD_ACCOUNT_LIMIT and SA_PUSH_GUILD_BUFF have no dumper we found");
        Hex.True(GuildWiring.HandlesWorldFrame(0x1414) && GuildWiring.HandlesWorldFrame(0x145C),
            "and are gated anyway, so the replay table never sees them");

        // neighbours, the party gate, and a sample of the rest of the default: arm
        foreach (ushort op in new ushort[] { 0x13FA, 0x13FD, 0x13FF, 0x1401, 0x1403, 0x140A,
                                             0x1410, 0x13F8, 0x1395, 0x27CF, 0x2809 })
            Hex.True(!GuildWiring.HandlesWorldFrame(op), $"0x{op:X4} must NOT be gated to guilds");
        // the AS_ direction is ours to SEND, never to receive
        Hex.True(!GuildWiring.HandlesWorldFrame(GuildPackets.AS_LEAVE_GUILD)
                 && !GuildWiring.HandlesWorldFrame(GuildPackets.AS_DESTROY_GUILD),
            "AS_ opcodes are Arbiter -> World");
        // and the two gates never overlap
        foreach (ushort op in GuildWiring.WorldOpcodes)
            Hex.True(!PartyWiring.HandlesWorldFrame(op), $"0x{op:X4} is not also a party frame");
    }

    /// <summary>
    /// SA_LEAVE_GUILD (0x13FE). GuildUtil::UserLeaveFromGuild sends <b>no client packet at
    /// all</b>: system message 0x126 to the leaver with GuildName, 0x2F8 to everyone still in the
    /// guild with UserName, and AS_LEAVE_GUILD to World. The row goes, and the character's
    /// guild_leave_time is stamped so C_REQUEST_COOLTIME_TO_JOIN_GUILD can answer.
    /// </summary>
    [Test] public static void T52_leaving_a_guild_removes_the_row_and_tells_everyone()
    {
        var (store, _, guildId) = T52Guild(3);
        using var _s = store;
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var chief = h.Player(1);
        var stays = h.Player(2);
        var leaver = h.Player(3);

        var actions = GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guildId, 3, "g3"));
        Hex.True(actions.Rejected == null, $"rejected: {actions.Rejected}");
        var r = h.Dispatcher.Dispatch(actions, "guild-world");

        Hex.True(store.GetGuildIdOf(3) == 0, "the member row is gone");
        Hex.True(store.GetGuildMembers(guildId).Count == 2, "two left");
        Hex.True(store.GetGuildLeaveTime(3) > 0,
            "guild_leave_time is stamped - Guild::CanRejoinGuild reads it later");

        Hex.True(string.Join(",", leaver.Log) == "def:S_SYSTEM_MESSAGE", string.Join(",", leaver.Log));
        Hex.True(string.Join(",", chief.Log) == "def:S_SYSTEM_MESSAGE", string.Join(",", chief.Log));
        Hex.True(string.Join(",", stays.Log) == "def:S_SYSTEM_MESSAGE", string.Join(",", stays.Log));
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x13FF",
            "AS_LEAVE_GUILD and nothing else: " + string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 0) == guildId
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 4) == 3,
            "AS_LEAVE_GUILD is [i32 GuildDbId][i32 MemberDbId]");
        Hex.True(r.ClientsSent == 3 && r.WorldSent == 1, $"{r}");

        // the guild history records it
        var log = store.GetGuildLog(guildId, 1);
        Hex.True(log.Any(e => e.ActionType == GuildHandlers.GuildLogLeave && e.ActorName == "g3"),
            "a 0x0C leave row was written");

        // a member of a DIFFERENT guild, or none, is refused rather than silently removed
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guildId, 3)).Rejected != null, "3 is no longer a member");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guildId + 99, 2)).Rejected != null, "2 is not in that guild");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD, new byte[8]).Rejected != null,
            "a frame shorter than 0x1A is refused, not read past");
        Hex.True(GuildWiring.OnWorldFrame(null, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guildId, 2)).Rejected != null, "and with no store open");
    }

    /// <summary>
    /// The two endings the leave path has beyond "one fewer member": the master leaving promotes
    /// a successor, and the last member leaving destroys the guild
    /// (GuildManager::MemberLeave_DestroyGuildWithLock is on this exact path).
    /// </summary>
    [Test] public static void T52_the_master_leaving_promotes_and_the_last_one_out_destroys()
    {
        var (store, _, guildId) = T52Guild(3);
        using var _s = store;
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var chief = h.Player(1); var a2 = h.Player(2); var a3 = h.Player(3);

        // the master leaves
        h.Dispatcher.Dispatch(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guildId, 1)), "guild-world");
        var g = store.GetGuild(guildId);
        Hex.True(g != null && g.ChiefDbId != 1 && store.GetGuildIdOf(g.ChiefDbId) == guildId,
            $"a remaining member was promoted, got chief {g?.ChiefDbId}");
        Hex.True(a2.Log.Contains("def:S_CHANGE_GUILD_CHIEF") && a3.Log.Contains("def:S_CHANGE_GUILD_CHIEF"),
            "both survivors are told who the new master is: " + string.Join(",", a2.Log));
        Hex.True(chief.Log.Count == 1 && chief.Log[0] == "def:S_SYSTEM_MESSAGE",
            "the one who left gets 0x126 and nothing else");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x13FF,0x1403",
            "AS_LEAVE_GUILD then AS_CHANGE_GUILD_CHIEF: "
            + string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));

        // then everybody else, until the guild is empty
        ClearSinks(h, chief, a2, a3);
        foreach (var m in store.GetGuildMembers(guildId).Select(m => m.UserDbId).ToArray())
            h.Dispatcher.Dispatch(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LEAVE_GUILD,
                SaLeaveGuildPayload(guildId, m)), "guild-world");

        Hex.True(store.GetGuild(guildId) == null, "the guild is destroyed when the last member goes");
        Hex.True(store.GetGuildMembers(guildId).Count == 0, "and it has no members");
        Hex.True(h.WorldLog.Any(w => w.Op == GuildPackets.AS_DESTROY_GUILD),
            "World is told with AS_DESTROY_GUILD (0x13FD): "
            + string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")));
    }

    /// <summary>SA_BANISH_GUILD_MEMBER (0x1400) is the same worker with one enum different: the
    /// guild hears 0x2F9 instead of 0x2F8. Everything else - the row, the log, AS_LEAVE_GUILD -
    /// is identical, because there is no spBanishGuildMember (GUILD-DESIGN section 3.1).</summary>
    [Test] public static void T52_banish_is_the_same_path_with_a_different_system_message()
    {
        var (store, _, guildId) = T52Guild(3);
        using var _s = store;
        Hex.True(GuildWiring.SmtMemberLeft == 0x2F8 && GuildWiring.SmtMemberBanished == 0x2F9
                 && GuildWiring.SmtYouLeftTheGuild == 0x126,
            "the three message ids GuildUtil::UserLeaveFromGuild sends");

        var actions = GuildWiring.OnWorldFrame(store, GuildPackets.SA_BANISH_GUILD_MEMBER,
            SaLeaveGuildPayload(guildId, 3, "g3"));
        Hex.True(actions.Rejected == null, $"rejected: {actions.Rejected}");
        Hex.True(store.GetGuildIdOf(3) == 0, "banished too");

        var messages = actions.Ordered.OfType<IArbiterClientAction>()
            .Select(c => (string)c.Fields!["message"]).ToList();
        Hex.True(messages.Count == 3, $"three system messages, got {messages.Count}");
        Hex.True(messages[0] == SocialHandlers.Smt(0x126, "GuildName", "Ere"),
            $"the banished member is told which guild: {messages[0]}");
        Hex.True(messages.Skip(1).All(m => m == SocialHandlers.Smt(0x2F9, "UserName", "g3")),
            $"and the rest hear 0x2F9, not 0x2F8: {string.Join(" | ", messages.Skip(1))}");

        // the voluntary path, same shape, 0x2F8
        var (store2, _, guild2) = T52Guild(3);
        using var _s2 = store2;
        var left = GuildWiring.OnWorldFrame(store2, GuildPackets.SA_LEAVE_GUILD,
            SaLeaveGuildPayload(guild2, 3, "g3")).Ordered.OfType<IArbiterClientAction>()
            .Select(c => (string)c.Fields!["message"]).Skip(1).ToList();
        Hex.True(left.All(m => m == SocialHandlers.Smt(0x2F8, "UserName", "g3")),
            $"voluntary is 0x2F8: {string.Join(" | ", left)}");
    }

    /// <summary>
    /// After T57 only two gated opcodes have no handler: SA_INC_GUILD_ACCOUNT_LIMIT (0x1414) and
    /// SA_PUSH_GUILD_BUFF (0x145C), neither of which has a modelled subsystem behind it. They are
    /// consumed and logged, not answered. That is on purpose: consuming keeps the replay table
    /// out of it, and an OnWorldFrame action set carries Origin = None, so the rejection reaches
    /// the log and not somebody's chat window. The other ten reach the same place on a frame
    /// that names no guild, which is what a zero payload is - so this doubles as the check that
    /// a blank frame never writes a row.
    /// </summary>
    [Test] public static void T52_the_unmodelled_guild_frames_are_consumed_not_answered()
    {
        var (store, _, _) = T52Guild(members: 2);
        using var _s = store;
        var h = new DispatchHarness().Build();
        var someone = h.Player(1);

        foreach (ushort op in GuildWiring.WorldOpcodes)
        {
            if (op == GuildPackets.SA_LEAVE_GUILD || op == GuildPackets.SA_BANISH_GUILD_MEMBER) continue;
            var a = GuildWiring.OnWorldFrame(store, op, new byte[32]);
            Hex.True(a.Origin.Kind == RecipientKind.None, $"0x{op:X4}: a World frame has no origin");
            Hex.True(a.Rejected != null && a.IsEmpty,
                $"0x{op:X4}: a frame naming no guild changes nothing and answers nothing");
            var r = h.Dispatcher.Dispatch(a, "guild-world");
            Hex.True(!r.RejectionSent, $"0x{op:X4}: the rejection stays in the log");
        }
        Hex.True(someone.Log.Count == 0, "and nobody's chat window was touched");

        // The two that are gated on purpose stay that way whatever the payload names.
        foreach (ushort op in new[] { GuildPackets.SA_INC_GUILD_ACCOUNT_LIMIT, GuildPackets.SA_PUSH_GUILD_BUFF })
            Hex.True(GuildWiring.OnWorldFrame(store, op, new byte[64]).Rejected != null,
                $"0x{op:X4} has no modelled subsystem - GUILD-DESIGN.md section 12.3");
    }

    /// <summary>
    /// C_INVITE_USER_TO_GUILD (0xEF92), in the binary's own order of guards. The reply is two
    /// system messages - 0xE2F to the inviter and 0xE30 to the target - plus a guild_invites row;
    /// there is no S_ packet for it, which is why C_REJECT_INVITE_USER_TO_GUILD takes a guild id.
    /// </summary>
    [Test] public static void T52_invite_writes_the_row_and_tells_both_sides()
    {
        var (store, guilds, guildId) = T52Guild(members: 2, chars: 3);
        using var _s = store;
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var chief = h.Player(1);
        var target = h.Player(3);

        // by name
        var a = guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD, CInviteBody("g3", 0, false));
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        h.Dispatcher.Dispatch(a, "guild");
        Hex.True(store.GetGuildInvites(3).Any(i => i.GuildId == guildId && i.InvitorDbId == 1),
            "spAddInviteUserToGuild wrote the row");
        Hex.True(string.Join(",", chief.Log) == "def:S_SYSTEM_MESSAGE"
                 && string.Join(",", target.Log) == "def:S_SYSTEM_MESSAGE",
            $"both sides: {string.Join(",", chief.Log)} // {string.Join(",", target.Log)}");

        var msgs = a.ToClients.Select(c => (string)c.Fields!["message"]).ToList();
        Hex.True(msgs[0] == SocialHandlers.Smt(GuildHandlers.MsgInviteSent, "userName", "g3"),
            $"0xE2F to the inviter, key spelled lowercase: {msgs[0]}");
        Hex.True(msgs[1] == SocialHandlers.Smt(GuildHandlers.MsgInviteReceived, "guildName", "Ere"),
            $"0xE30 to the target: {msgs[1]}");

        // a second invite from the same guild is refused - GuildJoinManager::AlreadyInvitedGuild
        Hex.True(guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("g3", 0, false)).Rejected != null, "no duplicate invites");
        // by db id works the same way, and 0 means "use the name"
        Hex.True(store.GetGuildInvites(3).Count == 1, "still one row");

        // every guard, in the binary's order
        Hex.True(guilds.OnClientPacket(3, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("g2", 0, false)).Rejected != null, "the caller must be in a guild (0xE2B)");
        Hex.True(guilds.OnClientPacket(2, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("g3", 0, false)).Rejected != null, "and hold the invite authority (0xE2C)");
        Hex.True(guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("nobody", 0, false)).Rejected != null, "no such user (0xE2B)");
        Hex.True(guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("g1", 0, false)).Rejected != null, "cannot invite yourself");
        Hex.True(guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD,
            CInviteBody("g3", 0, true)).Rejected != null, "no wanted board in this build (0xE2E)");

        // a target who is already in a guild is a system message, not a rejection
        var already = guilds.OnClientPacket(1, GuildPackets.C_INVITE_USER_TO_GUILD, CInviteBody("g2", 0, false));
        Hex.True(already.Rejected == null && already.ToClients.Count == 1,
            "0xE36 is content, not a refusal");
        Hex.True((string)already.ToClients[0].Fields!["message"]
                 == SocialHandlers.Smt(GuildHandlers.MsgAlreadyInAGuild, "userName", "g2"),
            (string)already.ToClients[0].Fields!["message"]);
    }

    /// <summary>
    /// C_CHANGE_GUILDNAME (0xFC1C). The handler's one guard is
    /// <c>*(int *)(guild + 0xd8) == *(int *)(user + 0x120)</c> - Guild+0xD8 is GuildData+0x50,
    /// the ChiefDbId - so only the master may rename. The reply is S_CHANGE_GUILDNAME, whose
    /// shipped .def drops the `usable` flag the whole name-check family carries (section 5.5).
    /// </summary>
    [Test] public static void T52_only_the_master_may_rename_and_a_taken_name_is_refused()
    {
        var (store, guilds, guildId) = T52Guild(members: 2, chars: 3);
        using var _s = store;

        // a member is refused outright - the real handler answers nothing at all
        Hex.True(guilds.OnClientPacket(2, GuildPackets.C_CHANGE_GUILDNAME, CStringBody("Nope")).Rejected != null,
            "only the guild master may rename");
        Hex.True(store.GetGuild(guildId)!.Name == "Ere", "and nothing changed");

        // the master renames
        var ok = guilds.OnClientPacket(1, GuildPackets.C_CHANGE_GUILDNAME, CStringBody("Erenor"));
        Hex.True(ok.Rejected == null && ok.ToClients.Count == 1, $"rejected: {ok.Rejected}");
        Hex.True(ok.ToClients[0].PacketName == "S_CHANGE_GUILDNAME", ok.ToClients[0].PacketName);
        Hex.True((string)ok.ToClients[0].Fields!["guildName"] == "Erenor"
                 && (bool)ok.ToClients[0].Fields!["usable"],
            "the reply carries the name and the flag the shipped .def forgot");
        Hex.True(store.GetGuild(guildId)!.Name == "Erenor", "the row was renamed");
        Hex.True(string.Join(",", ok.ToWorld.Select(w => $"0x{w.Opcode:X4}")) == "0x1490",
            "AS_UPDATE_GUILD_NAME: " + string.Join(",", ok.ToWorld.Select(w => $"0x{w.Opcode:X4}")));

        // a name another guild already has comes back usable = false, and nothing is written
        var other = NewGuildHandlers(store);
        var setup = new GuildActions();
        int g2 = other.CreateGuild(setup, 3, "Taken");   // character 3 is in no guild yet
        Hex.True(g2 > 0, "a second guild exists");
        var clash = guilds.OnClientPacket(1, GuildPackets.C_CHANGE_GUILDNAME, CStringBody("Taken"));
        Hex.True(!(bool)clash.ToClients[0].Fields!["usable"], "usable = false");
        Hex.True(clash.ToWorld.Count == 0, "and World is not told about a rename that did not happen");
        Hex.True(store.GetGuild(guildId)!.Name == "Erenor", "the row is untouched");

        // renaming to the name you already have is a no-op that succeeds
        var same = guilds.OnClientPacket(1, GuildPackets.C_CHANGE_GUILDNAME, CStringBody("Erenor"));
        Hex.True((bool)same.ToClients[0].Fields!["usable"], "a guild may keep its own name");
        Hex.True(!store.RenameGuild(guildId, ""), "an empty name is refused");
        Hex.True(!store.RenameGuild(guildId + 999, "Ghost"), "and so is a guild id that does not exist");
    }

    // =======================================================================================
    // T53 - the trade broker codec. Research: status/BROKER-DESIGN.md.
    //
    // No capture contains a broker frame, so every layout is golden against the packet's own PDL
    // dumper - the same footing the party (T28) and guild (T36) codecs stand on. What these
    // tests pin is the two things a dumper gives you for free and a hand-copy loses: that the
    // guard lands on the end of the last field, and that the shipped .def agrees.
    // =======================================================================================

    /// <summary>
    /// The split that decides the whole design: the Arbiter answers 16 of the 21
    /// C_TRADE_BROKER_* packets and never sees the other five, which are exactly the five that
    /// move an item. Registering one of World's would double-answer the client; leaving one of
    /// ours unregistered sends it to World, which cannot answer it.
    /// </summary>
    [Test] public static void T53_the_broker_client_packets_split_16_arbiter_5_world()
    {
        (ushort Op, int Frame)[] ours =
        {
            (0xABCA, 0x04), (0x961B, 0x04), (0x9FA3, 0x0C), (0xDB7F, 0x10), (0xEAFB, 0x04),
            (0x76B4, 0x6C), (0xE53F, 0x08), (0x983A, 0x09), (0x6F34, 0x10), (0xB981, 0x04),
            (0xB33F, 0x0C), (0x92E5, 0x04), (0xA788, 0x10), (0x8DC7, 0x75), (0x8CFB, 0x08),
            (0x8863, 0x09),
        };
        Hex.True(ours.Length == 16, "sixteen Arbiter-answered broker packets");

        foreach (var (op, frame) in ours)
        {
            Hex.True(BrokerPackets.ArbiterHandlesClientPacket(op), $"0x{op:X4} is ours");
            Hex.True(BrokerPackets.MinClientLength(op) == frame,
                $"0x{op:X4}: frame guard 0x{BrokerPackets.MinClientLength(op):X2}, want 0x{frame:X2}");
            Hex.True(BrokerPackets.MinBodyLength(op) == (frame <= 4 ? 0 : frame - 4),
                $"0x{op:X4}: the body minimum is the frame guard minus the 4-byte header, got "
                + $"{BrokerPackets.MinBodyLength(op)}");
            Hex.True(!BrokerPackets.WorldHandlesClientPacket(op), $"0x{op:X4} is not also World's");
        }

        // the five World owns - dumpers but no Handler_C_* anywhere in ArbiterServer.exe
        ushort[] worlds = { 0x7E74, 0xB8BA, 0x7516, 0x5C10, 0xF66D };
        foreach (ushort op in worlds)
        {
            Hex.True(BrokerPackets.WorldHandlesClientPacket(op), $"0x{op:X4} is World's");
            Hex.True(!BrokerPackets.ArbiterHandlesClientPacket(op)
                     && BrokerPackets.MinClientLength(op) == 0 && BrokerPackets.MinBodyLength(op) == 0,
                $"0x{op:X4} must answer 0 in both length tables, or someone will register it");
        }

        // and each of the five becomes the SDB_ of the same name
        Hex.True(BrokerPackets.SDB_TRADE_BROKER_REGISTER_ITEM == 0x2817
                 && BrokerPackets.SDB_TRADE_BROKER_UNREGISTER_ITEM == 0x2819
                 && BrokerPackets.SDB_TRADE_BROKER_CALC_SOLD_ITEM == 0x281B
                 && BrokerPackets.SDB_TRADE_BROKER_CALC_BOUGHT_ITEM == 0x281D
                 && BrokerPackets.SDB_TRADE_BROKER_BUY_IT_NOW == 0x281F,
            "the C_ name and the SDB_ name are the same word");
    }

    /// <summary>
    /// The finding that matters: five of the seven SDB_ broker requests carry a DlmId, so each is
    /// a per-user DLMItem. Nothing answers them and no capture contains one, so the replay table
    /// cannot cover either - opening the broker on a live TeraSharp head-blocks that character's
    /// DB queue for the life of the World process, exactly as opening the mailbox did before T45.
    /// </summary>
    [Test] public static void T53_five_broker_requests_are_unanswered_DLM_items()
    {
        // T53 found them unanswered; T55 answers them. The tripwire now guards the other way.
        ushort[] withDlm = { 0x2817, 0x2819, 0x281B, 0x281D, 0x281F };
        ushort[] withoutDlm = { 0x2821, 0x2824 };

        foreach (ushort op in withDlm)
        {
            Hex.True(BrokerPackets.CarriesDlmId(op), $"0x{op:X4} carries a DlmId");
            Hex.True(DbProxyHandlers.IsHandledRequest(op),
                $"0x{op:X4} must be answered (T55) - an unanswered DlmId wedges the character's DB queue");
            Hex.True(!WorldReplayTable.OneWayFromWorld.Contains(op),
                $"0x{op:X4} is not sealed one-way either - World really is waiting for a reply");
            Hex.True(BrokerPackets.ReplyFor(op) == (ushort)(op + 1),
                $"0x{op:X4}'s reply is the next opcode");
        }
        foreach (ushort op in withoutDlm)
            Hex.True(!BrokerPackets.CarriesDlmId(op),
                $"0x{op:X4} carries no DlmId, so an unanswered one cannot head-block anyone");

        // CANCEL_DEAL is the one pair that is not request+1
        Hex.True(BrokerPackets.ReplyFor(0x2824) == 0x282C, "SDB 0x2824 -> DBS 0x282C, not 0x2825");
        Hex.True(BrokerPackets.ReplyFor(0xDEAD) == 0, "and anything else has no reply");
        // DBS_TRADE_BROKER_ACCEPT_DEAL is a push, so nothing maps to it
        Hex.True(BrokerPackets.DBS_TRADE_BROKER_ACCEPT_DEAL == 0x2823, "0x2823 has no SDB_ partner");
    }

    /// <summary>
    /// Every inter-server broker frame's guard, from its dumper. A short frame kills the link on
    /// the real Arbiter (PDL version mismatch), so these have to be exact; our parsers answer
    /// null instead, which is the safe analogue.
    /// </summary>
    [Test] public static void T53_broker_frame_guards_match_the_dumpers()
    {
        (ushort Op, int Frame)[] frames =
        {
            (0x2817, 0x16), (0x2819, 0x1E), (0x281B, 0x22), (0x281D, 0x22), (0x281F, 0x27),
            (0x2821, 0x12), (0x2824, 0x0E),
            (0x2818, 0x13), (0x281A, 0x1F), (0x281C, 0x1F), (0x281E, 0x1F), (0x2820, 0x1F),
            (0x2822, 0x4C), (0x2823, 0x1E), (0x282C, 0x0A),
            (0x1457, 0x0E), (0x1459, 0x13), (0x1458, 0x0A), (0x145A, 0x12), (0x145B, 0x0A),
            (0x286D, 0x0B),
        };
        foreach (var (op, frame) in frames)
            Hex.True(BrokerPackets.MinFrameLength(op) == frame,
                $"0x{op:X4}: 0x{BrokerPackets.MinFrameLength(op):X2}, want 0x{frame:X2}");
        Hex.True(frames.Length == 21, "seven SDB_, eight DBS_, six AS_/SA_");
        Hex.True(BrokerPackets.MinFrameLength(0xDEAD) == 0, "and 0 for anything else");

        // none of the broker opcodes collides with a gate we already have
        foreach (var (op, _) in frames)
        {
            Hex.True(!PartyWiring.HandlesWorldFrame(op), $"0x{op:X4} is not a party frame");
            Hex.True(!GuildWiring.HandlesWorldFrame(op), $"0x{op:X4} is not a guild frame");
        }
    }

    /// <summary>
    /// The three SDB_ requests a handler would answer first, parsed at the documented offsets,
    /// and the reply builders that go with them. The BUY_IT_NOW case is the one the shipped .def
    /// gets wrong - TotalPriceWithTax sits past where the .def stops.
    /// </summary>
    [Test] public static void T53_the_SDB_broker_requests_parse_at_the_documented_offsets()
    {
        // SDB_TRADE_BROKER_REGISTER_ITEM, frame 0x16: i32 DlmId@0E, i32 OwnerDbId@12
        var reg = new byte[0x16 - 6];
        BitConverter.GetBytes(0x3Cu).CopyTo(reg, 0x0E - 6);
        BitConverter.GetBytes(77).CopyTo(reg, 0x12 - 6);
        var r = BrokerPackets.ParseSdbRegisterItem(reg);
        Hex.True(r != null && r.Value.dlmId == 0x3C && r.Value.ownerDbId == 77, $"{r}");
        Hex.True(BrokerPackets.ParseSdbRegisterItem(new byte[4]) == null, "a short frame is refused");

        // SDB_TRADE_BROKER_BUY_IT_NOW, frame 0x27 - the .def stops at InstantBuy@1E and misses
        // the i64 at 0x1F entirely (BROKER-DESIGN.md section 5).
        var buy = new byte[0x27 - 6];
        BitConverter.GetBytes(0x41u).CopyTo(buy, 0x0E - 6);
        BitConverter.GetBytes(88).CopyTo(buy, 0x12 - 6);
        BitConverter.GetBytes(2).CopyTo(buy, 0x16 - 6);
        BitConverter.GetBytes(9001).CopyTo(buy, 0x1A - 6);
        buy[0x1E - 6] = 1;
        BitConverter.GetBytes(1_234_567_890_123L).CopyTo(buy, 0x1F - 6);
        var b = BrokerPackets.ParseSdbBuyItNow(buy);
        Hex.True(b != null, "parsed");
        Hex.True(b!.Value.dlmId == 0x41 && b.Value.ownerDbId == 88 && b.Value.step == 2
                 && b.Value.tradeId == 9001 && b.Value.instantBuy
                 && b.Value.totalPriceWithTax == 1_234_567_890_123L,
            $"every field, including the one the .def forgot: {b}");
        Hex.True(buy.Length == 0x21, "the frame is 0x27 = 6-byte header + 0x21 of payload");

        // the two with no DlmId
        var start = new byte[0x12 - 6];
        BitConverter.GetBytes(11).CopyTo(start, 0);
        BitConverter.GetBytes(22).CopyTo(start, 4);
        BitConverter.GetBytes(33).CopyTo(start, 8);
        var sd = BrokerPackets.ParseSdbStartDeal(start);
        Hex.True(sd != null && sd.Value.buyerDbId == 11 && sd.Value.sellerDbId == 22 && sd.Value.tradeId == 33, $"{sd}");

        var cancel = new byte[0x0E - 6];
        BitConverter.GetBytes(44).CopyTo(cancel, 0);
        BitConverter.GetBytes(55).CopyTo(cancel, 4);
        var cd = BrokerPackets.ParseSdbCancelDeal(cancel);
        Hex.True(cd != null && cd.Value.userDbId == 44 && cd.Value.tradeId == 55, $"{cd}");

        // CALC_SOLD and CALC_BOUGHT are one layout behind two opcodes
        var calc = new byte[0x22 - 6];
        BitConverter.GetBytes(0x50u).CopyTo(calc, 0x16 - 6);
        BitConverter.GetBytes(66).CopyTo(calc, 0x1A - 6);
        BitConverter.GetBytes(3).CopyTo(calc, 0x1E - 6);
        foreach (ushort op in new ushort[] { 0x281B, 0x281D })
        {
            var c = BrokerPackets.ParseSdbCalcItem(op, calc);
            Hex.True(c != null && c.Value.dlmId == 0x50 && c.Value.ownerDbId == 66 && c.Value.step == 3,
                $"0x{op:X4}: {c}");
        }
        Hex.True(BrokerPackets.ParseSdbCalcItem(0x2817, calc) == null,
            "and it refuses an opcode that is not one of the two");

        // the replies, at the sizes the dumpers give
        var ack = BrokerPackets.BuildDbsRegisterItem(0x3C, success: false);
        Hex.True(ack.Length == 0x13 - 6, $"DBS_REGISTER_ITEM payload {ack.Length}, want {0x13 - 6}");
        Hex.True(BitConverter.ToUInt32(ack, 0x0E - 6) == 0x3C && ack[0x12 - 6] == 0, "DlmId echoed, Success 0");

        var step = BrokerPackets.BuildDbsStepAck(0x41, step: 2, success: true);
        Hex.True(step.Length == 0x1F - 6, $"the 0x1F shape {step.Length}");
        Hex.True(BitConverter.ToUInt32(step, 0x16 - 6) == 0x41
                 && BitConverter.ToInt32(step, 0x1A - 6) == 2 && step[0x1E - 6] == 1,
            "DlmId, the Step echoed back, Success");

        var accept = BrokerPackets.BuildDbsAcceptDeal(1, 2, 3, 4, 5_000_000L);
        Hex.True(accept.Length == 0x1E - 6 && BitConverter.ToInt64(accept, 16) == 5_000_000L,
            $"DBS_ACCEPT_DEAL is 0x1E and ends with AgreedPrice: {accept.Length}");
    }

    /// <summary>
    /// The search filter, 0x6C bytes of it. The point of this test is the last assertion: the
    /// handler's guard lands exactly on the end of <c>Wearable</c>, which is what says the field
    /// list is complete rather than merely plausible.
    /// </summary>
    [Test] public static void T53_the_history_search_filter_fills_its_guard_exactly()
    {
        Hex.True(BrokerPackets.HistorySearchSize == 0x6C, "fixed part 0x6C");
        Hex.True(BrokerPackets.WaitingSearchSize == 0x75,
            "the waiting filter is nine bytes longer - it adds CanBargainItemsOnly and reorders");

        var body = new byte[BrokerPackets.HistorySearchSize - 4];
        void I(int packetOff, int v) => BitConverter.GetBytes(v).CopyTo(body, packetOff - 4);
        void L(int packetOff, long v) => BitConverter.GetBytes(v).CopyTo(body, packetOff - 4);
        I(0x0C, 65); I(0x10, 70); I(0x14, 4); I(0x18, 1);
        body[0x1C - 4] = 1; body[0x1D - 4] = 0;
        I(0x1E, 100); I(0x22, 450);
        I(0x26, 7); L(0x2A, 12345L); I(0x32, 2);
        I(0x36, 1); I(0x3A, 9); I(0x3E, 0); I(0x42, 12);
        L(0x46, 1_000L); L(0x4E, 9_999_999L);
        body[0x56 - 4] = 1; body[0x57 - 4] = 1;
        L(0x58, 5L); L(0x60, 50L);
        body[0x68 - 4] = 1; body[0x69 - 4] = 1; body[0x6A - 4] = 0; body[0x6B - 4] = 1;

        var f = BrokerPackets.ParseCHistorySearch(body);
        Hex.True(f != null, "parsed");
        var v = f!.Value;
        Hex.True(v.MinLevel == 65 && v.MaxLevel == 70 && v.Grade == 4 && v.UnidentifiedItem == 1,
            $"the four leading i32: {v.MinLevel},{v.MaxLevel},{v.Grade},{v.UnidentifiedItem}");
        Hex.True(v.Masterpiece && !v.Enchantable, "the two unaligned bools at 0x1C/0x1D");
        Hex.True(v.MinItemLevel == 100 && v.MaxItemLevel == 450, "item level band");
        Hex.True(v.OptionValue == 12345L && v.OptionSearchCompareType == 2, "the i64 at 0x2A is unaligned");
        Hex.True(v.MinPrice == 1_000L && v.MaxPrice == 9_999_999L, "price band");
        Hex.True(v.MinTCatPrice == 5L && v.MaxTCatPrice == 50L, "and the T-cat band");
        Hex.True(v.ExactMatch && v.EquipmentSet && v.UseDetailSearch && v.Awakened
                 && !v.Unbindable && v.Wearable, "the six trailing bools");
        Hex.True(v.Keyword == "" && v.Category == "" && v.ItemTemplateIdList == ""
                 && v.SecondaryKeyword == "",
            "an offset of 0 reads as empty, which is what the real handler falls back on");

        // one byte short and it is refused rather than read past
        Hex.True(BrokerPackets.ParseCHistorySearch(body[..^1]) == null,
            "0x6B of body is one short of the guard");
        Hex.True(BrokerPackets.ParseCHistorySearch(null!) == null, "and null is not a crash");
    }

    /// <summary>The small fixed-layout client packets, and the two i64 that are UNALIGNED
    /// because the protocol packs a TradeId in front of them.</summary>
    [Test] public static void T53_the_small_broker_client_packets_parse()
    {
        var confirm = new byte[8];
        BitConverter.GetBytes(101).CopyTo(confirm, 0);
        BitConverter.GetBytes(2).CopyTo(confirm, 4);
        var c = BrokerPackets.ParseCDealConfirm(confirm);
        Hex.True(c != null && c.Value.tradeId == 101 && c.Value.dealStatus == 2, $"{c}");

        var reject = new byte[8];
        BitConverter.GetBytes(7).CopyTo(reject, 0);
        BitConverter.GetBytes(102).CopyTo(reject, 4);
        var rj = BrokerPackets.ParseCRejectSuggest(reject);
        Hex.True(rj != null && rj.Value.buyerDbId == 7 && rj.Value.tradeId == 102, $"{rj}");

        var price = new byte[12];
        BitConverter.GetBytes(103).CopyTo(price, 0);
        BitConverter.GetBytes(7_777_777_777L).CopyTo(price, 4);      // unaligned i64
        var pu = BrokerPackets.ParseCDealPriceUpdate(price);
        Hex.True(pu != null && pu.Value.tradeId == 103 && pu.Value.price == 7_777_777_777L, $"{pu}");
        var sg = BrokerPackets.ParseCSuggestDeal(price);
        Hex.True(sg != null && sg.Value.tradeId == 103 && sg.Value.suggestPrice == 7_777_777_777L,
            "SUGGEST_DEAL is the same shape");

        var input = new byte[12];
        BitConverter.GetBytes(0x1122334455667788L).CopyTo(input, 0);
        BitConverter.GetBytes(88888).CopyTo(input, 8);
        var ip = BrokerPackets.ParseCInputPrice(input);
        Hex.True(ip != null && ip.Value.itemDbId == 0x1122334455667788L && ip.Value.itemTemplateId == 88888, $"{ip}");

        Hex.True(BrokerPackets.ParseCListPage(BitConverter.GetBytes(3)) == 3, "PageNo");
        var sort = new byte[5];
        BitConverter.GetBytes(2).CopyTo(sort, 0); sort[4] = 1;
        var st = BrokerPackets.ParseCListSort(sort);
        Hex.True(st != null && st.Value.criteria == 2 && st.Value.ascending, $"{st}");

        // every parser refuses a body one byte short of its guard
        Hex.True(BrokerPackets.ParseCDealConfirm(new byte[7]) == null
                 && BrokerPackets.ParseCRejectSuggest(new byte[7]) == null
                 && BrokerPackets.ParseCDealPriceUpdate(new byte[11]) == null
                 && BrokerPackets.ParseCSuggestDeal(new byte[11]) == null
                 && BrokerPackets.ParseCInputPrice(new byte[11]) == null
                 && BrokerPackets.ParseCListPage(new byte[3]) == null
                 && BrokerPackets.ParseCListSort(new byte[4]) == null,
            "a short body is null, never a read past the end");
    }

    /// <summary>
    /// The four shipped .def files that do not match the binary, and the contract that lets a
    /// future wiring chain the corrections with the guild and chat ones. The BUY_IT_NOW
    /// correction is the one with teeth: the .def is 8 bytes short of the price the buyer paid.
    /// </summary>
    [Test] public static void T53_the_four_wrong_broker_defs_are_corrected()
    {
        Hex.True(BrokerPackets.CorrectedDefs.Count == 4, "four, no more - two others only LOOK wrong");
        foreach (var name in new[] { "SDB_TRADE_BROKER_BUY_IT_NOW", "S_TRADE_BROKER_DEAL_SUGGESTED",
                                     "S_TRADE_BROKER_DEAL_INFO_UPDATE", "S_TRADE_BROKER_SOLD_ITEM_LIST" })
            Hex.True(BrokerPackets.CorrectedDefs.ContainsKey(name), name);

        // the corrections parse, and carry the fields the .def dropped
        var buy = BrokerPackets.ResolveDef(null, "SDB_TRADE_BROKER_BUY_IT_NOW");
        Hex.True(buy != null && buy.Fields.Any(f => f.Name == "totalPriceWithTax"),
            "the i64 the .def stops before");
        var sold = BrokerPackets.ResolveDef(null, "S_TRADE_BROKER_SOLD_ITEM_LIST");
        Hex.True(sold != null && sold.Fields.Count == 2,
            "two i64 - the guard is 0x18 = header + both");
        var sug = BrokerPackets.ResolveDef(null, "S_TRADE_BROKER_DEAL_SUGGESTED");
        Hex.True(sug != null && sug.Fields[0].Name == "userName@hdr" && sug.Fields[0].IsHeaderFor == FieldKind.String,
            "the binary writes the name's ref slot FIRST (the parser emits it as the userName@hdr header)");
        Hex.True(sug!.Fields.Any(f => f.Name == "itemEnchantCount"), "and the .def drops this one");
        var upd = BrokerPackets.ResolveDef(null, "S_TRADE_BROKER_DEAL_INFO_UPDATE");
        Hex.True(upd != null && upd.Fields.Count == 3,
            "three fields - the .def has an extra int32 and is 4 bytes too long");

        // an uncorrected packet falls through, and a null registry returns the corrections only
        Hex.True(BrokerPackets.ResolveDef(null, "S_TRADE_BROKER_CALC_NOTIFY") == null,
            "the same contract as GuildHandlers.ResolveDef / ChatManager.ResolveDef");

        // ...and it really does chain with the other two
        Hex.True((BrokerPackets.ResolveDef(null, "S_ADD_GUILD_MEMBER")
                  ?? GuildHandlers.ResolveDef(null, "S_ADD_GUILD_MEMBER")) != null,
            "broker ?? guild resolves a guild packet");
    }

    /// <summary>
    /// The broker opcodes, cross-checked the way T36 cross-checked the guild ones: the client ids
    /// the Arbiter writes into its packets have to match data.json maps."376012". Here the check
    /// is against the def folder's presence and the in-code constants agreeing with the table in
    /// status/BROKER-DESIGN.md, since data.json is not in the repo.
    /// </summary>
    [Test] public static void T53_no_two_broker_opcodes_collide()
    {
        var all = typeof(BrokerPackets).GetFields(BindingFlags.Public | BindingFlags.Static)
            .Where(f => f.IsLiteral && f.FieldType == typeof(ushort))
            .Select(f => (f.Name, Op: (ushort)f.GetRawConstantValue()!))
            .ToList();
        Hex.True(all.Count == 57,
            $"21 C_ + 15 S_ + 7 SDB_ + 8 DBS_ + 4 AS_ + 2 SA_ = 57 broker opcodes, got {all.Count}");
        Hex.True(all.Count(f => f.Name.StartsWith("C_")) == 21
                 && all.Count(f => f.Name.StartsWith("S_")) == 15
                 && all.Count(f => f.Name.StartsWith("SDB_")) == 7
                 && all.Count(f => f.Name.StartsWith("DBS_")) == 8
                 && all.Count(f => f.Name.StartsWith("AS_")) == 4
                 && all.Count(f => f.Name.StartsWith("SA_")) == 2,
            "the family breakdown - DBS_ has one more than SDB_ because ACCEPT_DEAL is a push");

        var byOp = new Dictionary<ushort, string>();
        foreach (var (name, op) in all)
        {
            Hex.True(!byOp.ContainsKey(op),
                $"0x{op:X4} is declared twice: {name} and {(byOp.TryGetValue(op, out var w) ? w : "")}"
                + " - a copy/paste in a 42-constant block is otherwise invisible");
            byOp[op] = name;
        }

        // the four families are in their own numeric ranges, which is a cheap sanity check
        Hex.True(BrokerPackets.SDB_TRADE_BROKER_REGISTER_ITEM >> 8 == 0x28
                 && BrokerPackets.DBS_TRADE_BROKER_CANCEL_DEAL >> 8 == 0x28,
            "the DB-proxy pairs live in 0x28xx");
        Hex.True(BrokerPackets.SA_TRADE_BROKER_OPEN >> 8 == 0x14
                 && BrokerPackets.AS_TRADE_BROKER_DEAL_CLOSE >> 8 == 0x14,
            "the inter-server ones in 0x14xx, except AS_TRADE_BROKER_ITEM_SOLD");
        Hex.True(BrokerPackets.AS_TRADE_BROKER_ITEM_SOLD == 0x286D,
            "which sits in the DB-proxy range despite being an AS_");
    }

    // =======================================================================================
    // T55 - the broker DLM answers. Research: status/BROKER-DESIGN.md sections 3 and 8.
    //
    // T53 mapped the family and said section 8 was the one thing to do first: five SDB_ requests
    // carry a DlmId, the broker window sends the first of them the moment it opens, and nothing
    // answered them - so walking up to a broker NPC stopped that character's DB queue for the
    // life of the World process. These tests pin the answer, and in particular the two things a
    // hand-written empty form gets wrong (the backpatched offset slots, and the atom stride).
    // =======================================================================================

    /// <summary>
    /// The five are allow-listed, dispatched, and paired with the right reply opcode. The
    /// allow-list entry is what takes them off the replay table's hands - TryHandle runs first.
    /// </summary>
    [Test] public static void T55_the_five_broker_DLM_requests_are_answered()
    {
        ushort[] five = { 0x2817, 0x2819, 0x281B, 0x281D, 0x281F };
        foreach (ushort op in five)
        {
            Hex.True(BrokerPackets.CarriesDlmId(op), $"0x{op:X4} carries a DlmId");
            Hex.True(DbProxyHandlers.IsHandledRequest(op),
                $"0x{op:X4} must be allow-listed, or TryHandle returns false and the replay table "
                + "(which has never seen a broker frame) gets it");
            Hex.True(BrokerPackets.ReplyFor(op) == (ushort)(op + 1), $"0x{op:X4} -> 0x{op + 1:X4}");
        }

        // the two without a DlmId stay alone: an unanswered one cannot head-block anyone
        foreach (ushort op in new ushort[] { 0x2821, 0x2824 })
        {
            Hex.True(!BrokerPackets.CarriesDlmId(op), $"0x{op:X4} carries no DlmId");
            Hex.True(!DbProxyHandlers.IsHandledRequest(op),
                $"0x{op:X4} is deliberately still unanswered - there is no deal to have yet");
        }
        // and the Arbiter->World push has no request at all
        Hex.True(!DbProxyHandlers.IsHandledRequest(0x2823),
            "DBS_TRADE_BROKER_ACCEPT_DEAL is a push, not a reply");
    }

    /// <summary>
    /// The refusal, byte for byte, against the writers. Two things here that a hand-written empty
    /// form gets wrong, and both are the reason this test exists:
    /// <list type="number">
    /// <item>the ref OFFSET slots are backpatched unconditionally - before the emptiness check -
    /// so an empty answer carries 0x13 (or 0x1F) in the offset and 0 in the length, not two
    /// zeros. Same convention as DBS_INIT_GUILD_DATA;</item>
    /// <item>the 0x1F family has TWO ref pairs, not one, and the fixed part therefore ends at
    /// 0x1F rather than 0x17.</item>
    /// </list>
    /// </summary>
    [Test] public static void T55_the_broker_refusal_is_the_writers_empty_form()
    {
        // 0x2818 DBS_TRADE_BROKER_REGISTER_ITEM, frame 0x13 = 6-byte header + 13 of payload
        var reg = BrokerPackets.BuildDbsRegisterItem(0x3C, success: false);
        Hex.True(reg.Length == 0x13 - 6, $"payload {reg.Length}, want {0x13 - 6}");
        Hex.Eq(reg, "13 00 00 00  00 00 00 00  3C 00 00 00  00",
            "offset backpatched to 0x13, length 0, DlmId echoed, Success 0");

        // the 0x1F family - four opcodes, one writer
        var ack = BrokerPackets.BuildDbsStepAck(0x41, step: 2, success: false);
        Hex.True(ack.Length == 0x1F - 6, $"payload {ack.Length}, want {0x1F - 6}");
        Hex.Eq(ack, "1F 00 00 00  00 00 00 00  1F 00 00 00  00 00 00 00  41 00 00 00  02 00 00 00  00",
            "both offsets 0x1F, both lengths 0, DlmId, Step echoed, Success 0");

        // and the one entry point the handler uses
        foreach (ushort op in new ushort[] { 0x2819, 0x281B, 0x281D, 0x281F })
            Hex.Eq(BrokerPackets.BuildEmptyRefusal(op, 0x41, 2)!, ack,
                $"0x{op:X4} is the same 0x1F shape");
        Hex.Eq(BrokerPackets.BuildEmptyRefusal(0x2817, 0x3C, 0)!, reg, "0x2817 is the 0x13 shape");
        Hex.True(BrokerPackets.BuildEmptyRefusal(0xDEAD, 1, 1) == null, "and nothing else gets one");

        // non-empty: the offsets move, the lengths are count * 0x358, and ItemBinary is the ATOM
        Hex.True(BrokerPackets.AtomSize == 0x358,
            "ItemBinary is an ItemTransactionAtom array - the same 856-byte record the warehouse "
            + "uses - not the ItemData listing T53 guessed at");
        var oneAtom = new byte[BrokerPackets.AtomSize];
        var full = BrokerPackets.BuildDbsStepAck(1, 0, true, refA: new byte[8], atoms: oneAtom);
        Hex.True(BitConverter.ToInt32(full, 0x06 - 6) == 0x1F
                 && BitConverter.ToInt32(full, 0x0A - 6) == 8
                 && BitConverter.ToInt32(full, 0x0E - 6) == 0x1F + 8
                 && BitConverter.ToInt32(full, 0x12 - 6) == BrokerPackets.AtomSize,
            "refB's offset is refA's offset plus refA's length, and its length is count * 0x358");
        Hex.True(full.Length == (0x1F - 6) + 8 + BrokerPackets.AtomSize, $"payload {full.Length}");
    }

    /// <summary>
    /// The handler end to end: a real request in, a reply carrying that request's own DlmId and
    /// Step out. The id is the whole point - DLMExistManager::Find matches on it, so a reply with
    /// the wrong one is no better than none.
    /// </summary>
    [Test] public static void T55_the_broker_handler_echoes_the_DlmId_and_step()
    {
        // 0x2817: i32 DlmId@0E, i32 OwnerDbId@12
        var reg = new byte[0x16 - 6];
        BitConverter.GetBytes(0x7Bu).CopyTo(reg, 0x0E - 6);
        BitConverter.GetBytes(42).CopyTo(reg, 0x12 - 6);
        var parsedReg = BrokerPackets.ParseSdbRegisterItem(reg);
        Hex.True(parsedReg != null && parsedReg.Value.dlmId == 0x7B, "the request parses");
        Hex.True(BitConverter.ToUInt32(
                     BrokerPackets.BuildEmptyRefusal(0x2817, parsedReg!.Value.dlmId, 0)!, 0x0E - 6) == 0x7B,
            "and the reply carries that id, not a captured one");

        // 0x281F: the step at 0x16 is echoed, never invented
        var buy = new byte[0x27 - 6];
        BitConverter.GetBytes(0x99u).CopyTo(buy, 0x0E - 6);
        BitConverter.GetBytes(7).CopyTo(buy, 0x12 - 6);
        BitConverter.GetBytes(3).CopyTo(buy, 0x16 - 6);
        BitConverter.GetBytes(1234).CopyTo(buy, 0x1A - 6);
        buy[0x1E - 6] = 1;
        BitConverter.GetBytes(55_000L).CopyTo(buy, 0x1F - 6);
        var b = BrokerPackets.ParseSdbBuyItNow(buy)!.Value;
        var reply = BrokerPackets.BuildEmptyRefusal(0x281F, b.dlmId, b.step)!;
        Hex.True(BitConverter.ToUInt32(reply, 0x16 - 6) == 0x99, "DlmId echoed");
        Hex.True(BitConverter.ToInt32(reply, 0x1A - 6) == 3,
            "and the Step - its values were never traced, so inventing one tells World a stage "
            + "completed that did not");
        Hex.True(reply[0x1E - 6] == 0, "Success = 0: the item stays where it was");
        Hex.True(b.totalPriceWithTax == 55_000L, "and the price the .def forgets was read");
    }

    /// <summary>
    /// A frame shorter than the handler's own guard must be dropped, not thrown out of. The real
    /// Arbiter kills the World link over this; we cannot, because WorldLink.ReceiveLoop has no
    /// per-frame catch and one exception disconnects every player (status/SECURITY-AUDIT.md).
    /// Fuzz_dbproxy_dispatch_survives_hostile_frames covers the general case; this pins the
    /// five specifically, since they are new.
    /// </summary>
    [Test] public static void T55_a_short_broker_frame_is_refused_not_thrown()
    {
        foreach (ushort op in new ushort[] { 0x2817, 0x2819, 0x281B, 0x281D, 0x281F })
        {
            int frame = BrokerPackets.MinFrameLength(op);
            Hex.True(frame > 0, $"0x{op:X4} has a guard");
            for (int len = 0; len < frame - 6; len++)
            {
                var shortBody = new byte[len];
                Hex.True(BrokerPackets.BuildEmptyRefusal(op, 0, 0) != null, "the builder still works");
                // the parsers are what the handler asks first, and all of them answer null
                bool any = op switch
                {
                    0x2817 => BrokerPackets.ParseSdbRegisterItem(shortBody) != null,
                    0x2819 => BrokerPackets.ParseSdbUnregisterItem(shortBody) != null,
                    0x281B or 0x281D => BrokerPackets.ParseSdbCalcItem(op, shortBody) != null,
                    _ => BrokerPackets.ParseSdbBuyItNow(shortBody) != null,
                };
                Hex.True(!any, $"0x{op:X4}: a {len}-byte payload must parse as null, not read past");
            }
        }
    }

    /// <summary>
    /// The fifteen client packets BrokerHandlers registers, their body lengths, and the one it
    /// deliberately leaves alone. Registering C_TRADE_BROKER_HIGHEST_ITEM_LEVEL here would throw
    /// at startup - PacketDispatcher.Register refuses a duplicate and T45 already has it.
    /// </summary>
    [Test] public static void T55_the_broker_client_registrations_avoid_the_T45_duplicate()
    {
        Hex.True(BrokerHandlers.ClientOpcodes.Length == 15,
            $"sixteen Arbiter-answered minus the one T45 owns, got {BrokerHandlers.ClientOpcodes.Length}");

        foreach (var (name, op) in BrokerHandlers.ClientOpcodes)
        {
            Hex.True(BrokerPackets.ArbiterHandlesClientPacket(op), $"{name} is Arbiter-side");
            int frame = BrokerPackets.MinClientLength(op);
            Hex.True(BrokerHandlers.MinBodyLength(op) == (frame <= 4 ? 0 : frame - 4),
                $"{name}: the body minimum is the frame guard minus the 4-byte header, got "
                + $"{BrokerHandlers.MinBodyLength(op)} for frame 0x{frame:X2}");
        }

        Hex.True(BrokerHandlers.AlreadyAnsweredByT45 == 0xEAFB
                 && BrokerPackets.ArbiterHandlesClientPacket(0xEAFB),
            "C_TRADE_BROKER_HIGHEST_ITEM_LEVEL is Arbiter-side and answered - just not here");
        Hex.True(!BrokerHandlers.ClientOpcodes.Any(c => c.Opcode == 0xEAFB),
            "and must NOT be in this list, or Register throws on the duplicate at startup");
        Hex.True(ArbiterClientHandlers.ArbiterOwned.Contains((ushort)0xEAFB),
            "T45 owns it");

        // the five World owns must not be here either - answering one double-answers the client
        foreach (ushort op in new ushort[] { 0x7E74, 0xB8BA, 0x7516, 0x5C10, 0xF66D })
            Hex.True(!BrokerHandlers.ClientOpcodes.Any(c => c.Opcode == op),
                $"0x{op:X4} is World's");
    }

    /// <summary>
    /// Every reply BrokerHandlers sends, at the size its S_ dumper guard gives. The three that
    /// answer nothing are the deal family: each reaches a TradeBroker:: method that looks the
    /// deal up first and returns before any writer, and with no listings there is never a deal.
    /// </summary>
    [Test] public static void T55_the_broker_replies_are_the_empty_forms()
    {
        (ushort C, ushort S, int Frame)[] answered =
        {
            (0xABCA, 0x53C0, 0x08), (0xB981, 0xCDEA, 0x08), (0x92E5, 0x5587, 0x18),
            (0x76B4, 0x9372, 0x10), (0xE53F, 0x9372, 0x10), (0x983A, 0x9372, 0x10),
            (0x8DC7, 0xFD2C, 0x10), (0x8CFB, 0xFD2C, 0x10), (0x8863, 0xFD2C, 0x10),
            (0x6F34, 0x4FE6, 0x2C), (0xA788, 0xD0E6, 0x05),
        };
        foreach (var (c, sOp, frame) in answered)
        {
            var f = BrokerHandlers.ReplyFor(c);
            Hex.True(f != null, $"0x{c:X4} must be answered");
            Hex.True(BitConverter.ToUInt16(f!, 0) == f!.Length && f.Length == frame,
                $"0x{c:X4} -> 0x{sOp:X4}: {f.Length} bytes, want {frame}, and the length field agrees");
            Hex.True(BitConverter.ToUInt16(f, 2) == sOp, $"0x{c:X4} answers with 0x{sOp:X4}");
        }

        // the four that send nothing to the client
        foreach (ushort c in new ushort[] { 0x961B, 0x9FA3, 0xDB7F, 0xB33F })
            Hex.True(BrokerHandlers.ReplyFor(c) == null,
                $"0x{c:X4} has no client reply while the broker is empty");

        // the paged lists say page 1 of 1, not 0 of 0 - page 0 of an empty history is the bug
        // that crashed the real Arbiter's C_VIEW_GUILD_WAR (CLAUDE.md's hard rules)
        var hist = BrokerHandlers.ReplyFor(0x76B4)!;
        Hex.True(BitConverter.ToInt32(hist, 8) == 1 && BitConverter.ToInt32(hist, 12) == 1,
            $"page {BitConverter.ToInt32(hist, 8)} of {BitConverter.ToInt32(hist, 12)}");
        Hex.True(BitConverter.ToUInt16(hist, 4) == 0 && BitConverter.ToUInt16(hist, 6) == 0,
            "and the array slots are (count 0, offset 0)");

        // S_TRADE_BROKER_SOLD_ITEM_LIST carries the second i64 the shipped .def drops
        var sold = BrokerHandlers.ReplyFor(0x92E5)!;
        Hex.True(sold.Length == 0x18 && BitConverter.ToInt64(sold, 8) == 0
                 && BitConverter.ToInt64(sold, 16) == 0,
            "TotalCalcMoney and TotalCalcTCatMoney, both zero");

        // and the suggest refusal is one byte
        var sug = BrokerHandlers.ReplyFor(0xA788)!;
        Hex.True(sug.Length == 5 && sug[4] == 0, "S_TRADE_BROKER_REQUEST_DEAL_RESULT{false}");
    }

    /// <summary>
    /// The correction with teeth: SDB_TRADE_BROKER_BUY_IT_NOW's shipped .def stops before
    /// <c>i64 TotalPriceWithTax</c> at frame 0x1F, so a codec built from it would be 8 bytes
    /// short of the price the buyer actually paid - and would mis-read everything after it if the
    /// field ever moved. Pinned against the shipped file, not just against itself.
    /// </summary>
    [Test] public static void T55_the_corrected_buy_it_now_def_carries_the_price()
    {
        var corrected = BrokerPackets.ResolveDef(null, "SDB_TRADE_BROKER_BUY_IT_NOW");
        Hex.True(corrected != null, "the correction resolves");
        var names = corrected!.Fields.Select(f => f.Name).ToList();
        Hex.True(names.Contains("totalPriceWithTax"), $"fields: {string.Join(",", names)}");
        Hex.True(names[^1] == "totalPriceWithTax",
            "and it is LAST - it sits past the binary ref, at frame 0x1F");

        var defs = LoadDefinitionsOrSkip();
        if (defs == null) return;
        var shipped = defs.Get("SDB_TRADE_BROKER_BUY_IT_NOW");
        Hex.True(shipped != null, "the shipped .def exists");
        Hex.True(!shipped!.Fields.Any(f => f.Name.Equals("totalPriceWithTax", StringComparison.OrdinalIgnoreCase)),
            "the shipped one really is missing it - if this fails the .def was fixed upstream and "
            + "the correction can go");
        Hex.True(corrected.Fields.Count == shipped.Fields.Count + 1,
            $"exactly one field more: {corrected.Fields.Count} vs {shipped.Fields.Count}");

        // the parser reads it at the offset the dumper gives, which is what the .def would miss
        var buy = new byte[0x27 - 6];
        BitConverter.GetBytes(long.MaxValue).CopyTo(buy, 0x1F - 6);
        Hex.True(BrokerPackets.ParseSdbBuyItNow(buy)!.Value.totalPriceWithTax == long.MaxValue,
            "read at frame 0x1F");
        Hex.True(buy.Length == 0x21, "and it is the last thing in the frame");
    }

    // ======================================================================
    // T59 - character money
    //
    // Two facts the whole feature rests on, both read off the binaries rather
    // than guessed:
    //
    //  1. The op-9 ItemTransactionAtom carries a signed DELTA.
    //     Inventory::PrepareMoneyTransaction (WorldServer.exe.c:1407fa050)
    //     refuses when `*(__int64 *)(inv + 0x78) + amount < 0` - it adds the
    //     value to the money it already holds - then writes that same value to
    //     atom + 0x50. It also emits NO atom when the amount is 0, which an
    //     absolute update could never do.
    //
    //  2. Money reaches World in the enter-world BLOB, at offset 448 (0x1C0),
    //     as an i64. The Arbiter binds its SQL `money` column to
    //     UserData + 0x1C0 (Arb_part_032.c:17798); World's enter-world
    //     finisher calls Inventory::SetMoney(User + 0xA478,
    //     *(__int64 *)(context + 0x268)) (WorldServer.exe.c:1663604) and the
    //     blob lands at context + 0xA8 - 0x268 - 0xA8 = 0x1C0.
    //
    // It is NOT in DBS_USER_LOAD_INVENTORY (0x27A4): that reply's only fields
    // are InvenItems, DlmId and ContinueReceive (dumper FUN_140209730,
    // Arb_part_016.c:760), and its array is a plain run of 0x218-byte
    // ItemData records with no money entry (writer Arb_part_064.c:15328).
    // And World never writes it back: blob + 0x1C0 is zero in all six
    // SDB_UPDATE_USER_DATA frames of cap_newchar.log, including the ones sent
    // after the character had earned 230 gold. That is why it needs a column.
    // ======================================================================

    /// <summary>A store with `count` characters, ids 1..count, none of them in a guild.</summary>
    static TeraSharp.Arbiter.Persistence.CharacterStore T59Store(int count = 2)
    {
        var store = new TeraSharp.Arbiter.Persistence.CharacterStore(":memory:", QuietLog());
        var acct = store.GetOrCreateAccount("t59");
        for (int i = 1; i <= count; i++)
        {
            int id = store.CreateCharacter(new TeraSharp.Arbiter.Persistence.CharacterRecord
            {
                AccountId = acct.Id, Name = "m" + i, Gender = 1, Race = 4, Class = 12,
                Level = 1, TemplateId = 10101, Zone = 5, X = 1f, Y = 2f, Z = 3f,
                Appearance = new byte[8], Details = new byte[32], Shape = new byte[64],
                Position = i,
            });
            Hex.True(id == i, $"expected character id {i}, got {id}");
        }
        return store;
    }

    /// <summary>One op-9 money atom for owner `who`, exactly as PrepareMoneyTransaction builds
    /// it: no item id, template 0, both inven slots 0, both owners the player, delta at +0x50.</summary>
    static byte[] T59MoneyAtoms(long who, params long[] deltas)
    {
        var atoms = new (uint Op, long ItemDbId, int Template, long SrcOwner, uint SrcInven,
                         uint SrcSlot, long DstOwner, uint DstInven, uint DstSlot, long Delta)[deltas.Length];
        for (int i = 0; i < deltas.Length; i++)
            atoms[i] = (WarehouseHandlers.TsChangeMoney, 0L, 0, who, 0u, 0u, who, 0u, 0u, deltas[i]);
        return T44AtomPayload(DbProxyHandlers.ItemSingleRequestHeader, atoms);
    }

    [Test] public static void T59_the_money_atom_is_a_delta_and_lands_on_the_character_row()
    {
        using var store = T59Store();

        Hex.True(store.GetCharacterMoney(1) == 0, "a new character has no money");

        var r = T44Apply(store, T59MoneyAtoms(1, 19));
        Hex.True(store.GetCharacterMoney(1) == 19, $"first loot: {store.GetCharacterMoney(1)}");
        Hex.True(r.CharacterMoneyDelta == 19, $"counted as character money, not warehouse: {r}");
        Hex.True(r.MoneyDelta == 0, "and not as warehouse money");
        Hex.True(r.Ignored == 0, "an op-9 atom is no longer an ignored atom");

        // The sequence cap_newchar_client.log's S_ITEMLIST shows for "Test": 19 -> 67 -> 30 ->
        // 114 -> 230. Every step is the running total plus the atom's signed delta; the 30 -> 114
        // step is the +84 INVENTORY-DESIGN.md section 1 already recorded from a kill.
        T44Apply(store, T59MoneyAtoms(1, 48, -37, 84, 116));
        Hex.True(store.GetCharacterMoney(1) == 230,
            $"19 + 48 - 37 + 84 + 116 = 230, got {store.GetCharacterMoney(1)}");

        // Several atoms in one message accumulate, and the result reports the net.
        var net = T44Apply(store, T59MoneyAtoms(1, 10, -4));
        Hex.True(net.CharacterMoneyDelta == 6 && store.GetCharacterMoney(1) == 236, $"{net}");

        // World refuses anything that would go negative before it ever builds the atom, so a
        // negative total can only arrive from a frame World did not send. Clamped, not stored.
        T44Apply(store, T59MoneyAtoms(1, long.MinValue / 2));
        Hex.True(store.GetCharacterMoney(1) == 0, "clamped at zero, never negative");

        // Money belongs to one character; the other one is untouched throughout.
        Hex.True(store.GetCharacterMoney(2) == 0, "the second character earned nothing");

        // An owner that is not a character is a warning, not a throw and not a stray row.
        var miss = T44Apply(store, T59MoneyAtoms(9999, 5));
        Hex.True(miss.CharacterMoneyDelta == 5 && store.GetCharacterMoney(9999) == 0,
            "an unknown owner updates nothing");

        // And money is never an item row: `items` stays empty through all of it.
        Hex.True(store.GetItems(1, BagItems.Pocket).Count == 0, "op 9 writes no item row");
    }

    [Test] public static void T59_the_money_field_is_where_both_binaries_put_it()
    {
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.MoneyOffset == 448,
            "blob + 0x1C0");
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.MoneyOffset == 0x268 - 0xA8,
            "which is exactly context + 0x268 with the blob memcpy'd to context + 0xA8");
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.MoneyBlockEnd == 456, "i64, not i32");

        // Short buffers: read 0, write nothing, throw nothing. A character that has never
        // entered the world has no blob at all, so this is the normal case and not an error.
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(null) == 0, "null reads 0");
        Hex.True(!TeraSharp.Arbiter.Persistence.StarterBlob.WriteMoney(null, 5), "null writes nothing");
        var tooShort = new byte[455];
        Hex.True(!TeraSharp.Arbiter.Persistence.StarterBlob.WriteMoney(tooShort, 5),
            "one byte short of the field is refused, not written past");
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(tooShort) == 0, "and reads 0");

        var template = LoadStarterTemplateOrSkip();
        if (template == null) return;
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(template) == 0,
            "the captured starter blob carries money 0 - the character had none yet");
    }

    /// <summary>
    /// The round trip the live bug was about: World saves the blob with money ZEROED (it never
    /// writes that field), we keep the number in its own column, and the next enter-world serves
    /// it back inside the blob. Byte-exact against data/starter_blob.bin: the served blob differs
    /// from the capture in exactly the eight bytes at 448.
    /// </summary>
    [Test] public static void T59_money_round_trips_into_the_enter_world_blob_byte_exact()
    {
        var template = LoadStarterTemplateOrSkip();
        if (template == null) return;
        using var store = T59Store(1);

        // What World actually hands back in SDB_UPDATE_USER_DATA: the capture's bytes, money 0.
        store.SaveWorldBlob(1, (byte[])template.Clone());
        var fresh = store.GetCharacter(1)!;
        Hex.True(fresh.Money == 0 && fresh.WorldBlob!.SequenceEqual(template),
            "with no money the served blob is the capture, byte for byte");

        // 267 is the figure the live session was chasing; the exact value does not matter, only
        // that it is not representable in 32 bits by accident, so use a large one too.
        store.AddCharacterMoney(1, 267);
        var chr = store.GetCharacter(1)!;
        Hex.True(chr.Money == 267, $"the column holds it: {chr.Money}");
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(chr.WorldBlob) == 267,
            "and the blob we would send carries it at 448");

        int diffs = 0;
        for (int i = 0; i < template.Length; i++) if (chr.WorldBlob![i] != template[i]) diffs++;
        Hex.True(diffs == 2, $"exactly the two bytes of 267 changed, got {diffs}");
        for (int i = 0; i < template.Length; i++)
            if (i < 448 || i >= 456)
                Hex.True(chr.WorldBlob![i] == template[i], $"byte {i} must not move");

        // The 0x2738 payload itself, which is what World reads.
        var payload = DbProxyHandlers.BuildDbsUserEnterWorld(0x13, chr.WorldBlob);
        Hex.True(payload.Length == 13 + 15312, $"header + blob: {payload.Length}");
        Hex.True(BitConverter.ToInt64(payload, 13 + 448) == 267,
            "money is at payload 13 + 448, i.e. frame 19 + 448");

        // Beyond 32 bits, because the GM commands hand out ten-digit amounts.
        store.SetCharacterMoney(1, 10_000_000_000L);
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(store.GetCharacter(1)!.WorldBlob)
                 == 10_000_000_000L, "i64 all the way through");

        // A second save from World zeroes the field again - and must not lose the money.
        store.SaveWorldBlob(1, (byte[])template.Clone());
        Hex.True(store.GetCharacterMoney(1) == 10_000_000_000L,
            "World's save does not clear the column");
        Hex.True(TeraSharp.Arbiter.Persistence.StarterBlob.ReadMoney(store.GetCharacter(1)!.WorldBlob)
                 == 10_000_000_000L, "and the next login still serves it");
    }

    [Test] public static void T59_the_money_column_is_guarded_by_the_self_test()
    {
        Hex.True(SelfTest.RequiredColumns.Contains(("characters", "money")),
            "a stale terasharp.db without characters.money must be reported, not silently reset "
            + "everyone's gold to 0");
    }


    // ======================================================================
    // T57 - the eight guild SA_ frames section 12.3 left gated but unanswered
    //
    // Every one is quoted to its handler in Arb_part_072.c. The two shapes
    // worth remembering:
    //   * only the chief change sends a client packet; the rest are a store
    //     write plus an AS_ fan-out to every WorldServerSession;
    //   * SA_LOAD_GUILD replies with 0x144D, 0x27D0, 0x27D1, 0x27D2 - the
    //     guild blob goes out as AS_LOAD_GUILD_DATA, NOT as the boot load's
    //     DBS_INIT_GUILD_DATA (0x27ED), and there is no 0x27D3 terminator.
    // ======================================================================

    /// <summary>SA_LOAD_GUILD / SA_DESTROY_GUILD: `i64 ArbiterUser@06, i32 GuildDbId@0E`.</summary>
    static byte[] SaGuildActionPayload(int guildDbId)
    {
        var p = new byte[12];
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 0);
        BitConverter.GetBytes(guildDbId).CopyTo(p, 8);
        return p;
    }

    /// <summary>SA_CHANGE_GUILD_CHIEF / SA_REMOVE_GUILD_GROUP: the same plus one more i32.</summary>
    static byte[] SaGuildPairPayload(int guildDbId, int second)
    {
        var p = new byte[16];
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 0);
        BitConverter.GetBytes(guildDbId).CopyTo(p, 8);
        BitConverter.GetBytes(second).CopyTo(p, 12);
        return p;
    }

    /// <summary>SA_CHANGE_GUILDGROUP: `i64 ArbiterUser@06, i32 GuildDbId@0E, MemberDbId@12, GroupId@16`.</summary>
    static byte[] SaChangeGuildGroupPayload(int guildDbId, int memberDbId, int groupId)
    {
        var p = new byte[20];
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 0);
        BitConverter.GetBytes(guildDbId).CopyTo(p, 8);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 12);
        BitConverter.GetBytes(groupId).CopyTo(p, 16);
        return p;
    }

    /// <summary>SA_UPDATE_GUILD_MEMBER: `i32 GuildDbId@06, i32 MemberDbId@0A` - no ArbiterUser.</summary>
    static byte[] SaUpdateGuildMemberPayload(int guildDbId, int memberDbId)
    {
        var p = new byte[8];
        BitConverter.GetBytes(guildDbId).CopyTo(p, 0);
        BitConverter.GetBytes(memberDbId).CopyTo(p, 4);
        return p;
    }

    /// <summary>SA_CREATE_GUILD_GROUP: `u32 nameOff@06, i64 ArbiterUser@0A, i32 GuildDbId@12`,
    /// then the wstring; fixed part 0x16.</summary>
    static byte[] SaCreateGuildGroupPayload(int guildDbId, string name)
    {
        var p = new byte[16 + (name.Length + 1) * 2];
        BitConverter.GetBytes(0x16).CopyTo(p, 0);                    // frame-relative
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 4);
        BitConverter.GetBytes(guildDbId).CopyTo(p, 12);
        for (int i = 0; i < name.Length; i++)
        { p[16 + i * 2] = (byte)name[i]; p[17 + i * 2] = (byte)(name[i] >> 8); }
        return p;
    }

    /// <summary>SA_SET_GUILDGROUP_AUTHORITY: `u32 nameOff@06, i64 ArbiterUser@0A, i32 GuildDbId@12,
    /// i32 GroupId@16, i32 Authority@1A`, then the wstring; fixed part 0x1E.</summary>
    static byte[] SaSetGroupAuthorityPayload(int guildDbId, int groupId, int authority, string name)
    {
        var p = new byte[24 + (name.Length + 1) * 2];
        BitConverter.GetBytes(0x1E).CopyTo(p, 0);
        BitConverter.GetBytes(0x8000_0AF0_0001L).CopyTo(p, 4);
        BitConverter.GetBytes(guildDbId).CopyTo(p, 12);
        BitConverter.GetBytes(groupId).CopyTo(p, 16);
        BitConverter.GetBytes(authority).CopyTo(p, 20);
        for (int i = 0; i < name.Length; i++)
        { p[24 + i * 2] = (byte)name[i]; p[25 + i * 2] = (byte)(name[i] >> 8); }
        return p;
    }

    [Test] public static void T57_load_guild_re_pushes_the_mirror_in_the_decompiles_order()
    {
        var (store, _, guildId) = T52Guild(3);
        using var _s = store;
        var h = new DispatchHarness().Build();
        var chief = h.Player(1);

        var a = GuildWiring.OnWorldFrame(store, GuildPackets.SA_LOAD_GUILD, SaGuildActionPayload(guildId));
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        h.Dispatcher.Dispatch(a, "guild-world");

        var ops = string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}"));
        Hex.True(ops == "0x144D,0x27D0,0x27D1,0x27D2",
            "AS_LOAD_GUILD_DATA, groups, members, perks - no 0x27ED and no 0x27D3 terminator: " + ops);
        Hex.True(chief.Log.Count == 0, "and no client packet: the guild window is not refreshed by this");

        // The blob goes out whole, behind the AS_LOAD_GUILD_DATA [u32 off][u32 len] header.
        var data = h.WorldLog[0].Payload;
        Hex.True(BitConverter.ToInt32(data, 0) == 6 + 8, "blob offset is frame-relative 0x0E");
        Hex.True(BitConverter.ToInt32(data, 4) == GuildPackets.GuildDataSize,
            $"and the whole 0x23A0 GuildData: {BitConverter.ToInt32(data, 4)}");
        Hex.True(BitConverter.ToInt32(data, 8) == guildId, "which starts with the guild id");

        // The member frame carries three members at 0xF0 each, keyed by guild id, as a BYTE length.
        var mem = h.WorldLog[2].Payload;
        Hex.True(BitConverter.ToInt32(mem, 4) == 3 * GuildPackets.GuildMemberDataSize,
            $"3 members x 0xF0: {BitConverter.ToInt32(mem, 4)}");
        Hex.True(BitConverter.ToInt32(mem, 8) == guildId, "and the guild id");

        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LOAD_GUILD,
            SaGuildActionPayload(guildId + 99)).Rejected != null, "an unknown guild is refused");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_LOAD_GUILD, new byte[8]).Rejected != null,
            "and a frame shorter than 0x12 is refused, not read past");
    }

    [Test] public static void T57_destroy_and_chief_change()
    {
        var (store, _, guildId) = T52Guild(3);
        using var _s = store;
        var h = new DispatchHarness().Build(resolveDef: n => GuildHandlers.ResolveDef(null, n));
        var chief = h.Player(1);
        var member = h.Player(2);

        // --- chief change: every member is told, then World.
        var a = GuildWiring.OnWorldFrame(store, GuildPackets.SA_CHANGE_GUILD_CHIEF,
            SaGuildPairPayload(guildId, 2));
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        h.Dispatcher.Dispatch(a, "guild-world");
        Hex.True(store.GetGuild(guildId)!.ChiefDbId == 2, "the row moved");
        Hex.True(string.Join(",", chief.Log) == "def:S_CHANGE_GUILD_CHIEF", string.Join(",", chief.Log));
        Hex.True(string.Join(",", member.Log) == "def:S_CHANGE_GUILD_CHIEF", string.Join(",", member.Log));
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x1403",
            "AS_CHANGE_GUILD_CHIEF and nothing else");
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 0) == guildId
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 4) == 2, "[GuildDbId][NewChiefDbId]");

        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_CHANGE_GUILD_CHIEF,
            SaGuildPairPayload(guildId, 2)).Rejected != null, "2 is already the chief");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_CHANGE_GUILD_CHIEF,
            SaGuildPairPayload(guildId, 99)).Rejected != null, "and a non-member cannot be promoted");

        // --- destroy: rows and children gone, one AS_DESTROY_GUILD, nothing to the clients.
        var h2 = new DispatchHarness().Build();
        var stillThere = h2.Player(1);
        var d = GuildWiring.OnWorldFrame(store, GuildPackets.SA_DESTROY_GUILD, SaGuildActionPayload(guildId));
        Hex.True(d.Rejected == null, $"rejected: {d.Rejected}");
        h2.Dispatcher.Dispatch(d, "guild-world");
        Hex.True(store.GetGuild(guildId) == null, "the guild is gone");
        Hex.True(store.GetGuildIdOf(1) == 0 && store.GetGuildIdOf(3) == 0, "and so are the memberships");
        Hex.True(string.Join(",", h2.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x13FD", "AS_DESTROY_GUILD");
        Hex.True(stillThere.Log.Count == 0,
            "the member-facing half of DestroyGuildWithLock was not traced - section 12.4");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_DESTROY_GUILD,
            SaGuildActionPayload(guildId)).Rejected != null, "destroying it twice is refused");
    }

    [Test] public static void T57_the_guild_group_handlers_write_rows_and_fan_out()
    {
        var (store, _, guildId) = T52Guild(2);
        using var _s = store;
        var h = new DispatchHarness().Build();
        var chief = h.Player(1);

        // --- create. Guild::GenerateNewGuildGroupId is max(existing) + 1; the default group is 2
        // (TeraSharp.Arbiter.Persistence.CharacterStore.DefaultGuildGroupId), so the first one created here is 3.
        var a = GuildWiring.OnWorldFrame(store, GuildPackets.SA_CREATE_GUILD_GROUP,
            SaCreateGuildGroupPayload(guildId, "Officers"));
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        h.Dispatcher.Dispatch(a, "guild-world");

        int expected = TeraSharp.Arbiter.Persistence.CharacterStore.DefaultGuildGroupId + 1;
        var made = store.GetGuildGroup(guildId, expected);
        Hex.True(made != null, $"group {expected} exists");
        Hex.True(made!.Name == "Officers" && made.Authority == GuildWiring.GuildGroupDefaultAuthority,
            $"name and authority 0: '{made.Name}' / {made.Authority}");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x1407", "AS_CREATE_GUILD_GROUP");
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 4) == guildId
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 8) == expected
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 12) == 0,
            "[off][GuildDbId][GroupId][Authority=0] then the name");
        Hex.True(store.GetGuildLog(guildId, 1).Any(e => e.ActionType == GuildHandlers.GuildLogAddGroup),
            "a 0x15 add-group row was written");
        Hex.True(chief.Log.Count == 0, "and no client packet");

        // ids never go back down, even after a removal
        var second = GuildWiring.OnWorldFrame(store, GuildPackets.SA_CREATE_GUILD_GROUP,
            SaCreateGuildGroupPayload(guildId, "Veterans"));
        Hex.True(second.Rejected == null && store.GetGuildGroup(guildId, expected + 1) != null,
            "the next one is max + 1");

        // --- rename / re-authorise
        h.WorldLog.Clear();
        var auth = GuildWiring.OnWorldFrame(store, GuildPackets.SA_SET_GUILDGROUP_AUTHORITY,
            SaSetGroupAuthorityPayload(guildId, expected, 7, "Elders"));
        Hex.True(auth.Rejected == null, $"rejected: {auth.Rejected}");
        h.Dispatcher.Dispatch(auth, "guild-world");
        var changed = store.GetGuildGroup(guildId, expected)!;
        Hex.True(changed.Name == "Elders" && changed.Authority == 7, $"'{changed.Name}' / {changed.Authority}");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x1405",
            "AS_SET_GUILDGROUP_AUTHORITY");

        // --- move a member into it
        h.WorldLog.Clear();
        var move = GuildWiring.OnWorldFrame(store, GuildPackets.SA_CHANGE_GUILDGROUP,
            SaChangeGuildGroupPayload(guildId, 2, expected));
        Hex.True(move.Rejected == null, $"rejected: {move.Rejected}");
        h.Dispatcher.Dispatch(move, "guild-world");
        Hex.True(store.GetGuildMember(2)!.GuildGroupId == expected, "the member moved group");
        Hex.True(store.GetGuildLog(guildId, 1).Any(e => e.ActionType == GuildHandlers.GuildLogChangeMemberGroup),
            "a 0x20 change-group row was written");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x140C", "AS_CHANGE_GUILDGROUP");
        Hex.True(BitConverter.ToInt32(h.WorldLog[0].Payload, 0) == guildId
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 4) == 2
                 && BitConverter.ToInt32(h.WorldLog[0].Payload, 8) == expected,
            "[GuildDbId][MemberDbId][GroupId]");

        // --- remove. The decompile writes the log only when the remove took, but fans out either
        // way - the loop sits outside that `if`.
        h.WorldLog.Clear();
        var gone = GuildWiring.OnWorldFrame(store, GuildPackets.SA_REMOVE_GUILD_GROUP,
            SaGuildPairPayload(guildId, expected));
        Hex.True(gone.Rejected == null, $"rejected: {gone.Rejected}");
        h.Dispatcher.Dispatch(gone, "guild-world");
        Hex.True(store.GetGuildGroup(guildId, expected) == null, "the group is gone");
        Hex.True(store.GetGuildLog(guildId, 1).Any(e => e.ActionType == GuildHandlers.GuildLogRemoveGroup),
            "a 0x16 remove-group row was written");
        Hex.True(string.Join(",", h.WorldLog.Select(w => $"0x{w.Op:X4}")) == "0x1409", "AS_REMOVE_GUILD_GROUP");

        h.WorldLog.Clear();
        var again = GuildWiring.OnWorldFrame(store, GuildPackets.SA_REMOVE_GUILD_GROUP,
            SaGuildPairPayload(guildId, expected));
        Hex.True(again.Rejected == null && !again.IsEmpty,
            "removing it twice still tells World, exactly as the decompile does");

        // InputRestrictionHelper::CheckGuildGroupName: 1..15 characters.
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_CREATE_GUILD_GROUP,
            SaCreateGuildGroupPayload(guildId, "")).Rejected != null, "an empty name is refused");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_CREATE_GUILD_GROUP,
            SaCreateGuildGroupPayload(guildId, new string('x', 16))).Rejected != null,
            "and one of 16 characters");
        Hex.True(GuildWiring.OnWorldFrame(store, GuildPackets.SA_CREATE_GUILD_GROUP,
            SaCreateGuildGroupPayload(guildId, new string('x', 15))).Rejected == null,
            "15 is legal");
    }

    [Test] public static void T57_update_guild_member_echoes_the_stored_roster_row()
    {
