    /// <summary>
    /// The ParcelData field map, pinned against both captured forms of the SAME parcel - the
    /// 3544-byte record inside SDB_MAKE_PARCEL (seq 1485) and the 2536-byte NoMsg record
    /// DBS_LIST_PARCEL returned for it (seq 1539). The two differ in exactly the way that
    /// matters: the request carries ReceiverDbId 0 and the reply carries 1002.
    /// </summary>
    [Test] public static void T61_the_parcel_record_fields_are_pinned_to_both_captured_forms()
    {
        var make = Hex.B(Cap61_MakeParcelDataHead);
        var list = Hex.B(Cap61_ListParcelDataHead);

        var mf = ParcelDbHandlers.ParseParcelData(make);
        Hex.True(mf.SenderDbId == 2 && mf.SenderName == "Test", $"+00/+04 sender: {mf.SenderDbId} '{mf.SenderName}'");
        Hex.True(mf.ReceiverName == "two", $"+54 ReceiverName: '{mf.ReceiverName}'");
        Hex.True(mf.ReceiverDbId == 0,
            "+50 ReceiverDbId is ZERO in a MAKE request - the client only knew the name it typed");
        Hex.True(mf.Money == 100, $"+D0 Money: {mf.Money}");
        Hex.True(mf.ParcelId == 0, "+A0 ParcelId is unallocated on the way in");

        var lf = ParcelDbHandlers.ParseParcelData(list);
        Hex.True(lf.ReceiverDbId == 1002, $"+50 is filled in once the Arbiter has stored it: {lf.ReceiverDbId}");
        Hex.True(lf.SenderDbId == 2 && lf.SenderName == "Test" && lf.ReceiverName == "two", "and the rest is unchanged");
        Hex.True(lf.ParcelId == 1, $"+A0 ParcelId: {lf.ParcelId}");
        Hex.True(lf.Money == 100, $"+D0 Money: {lf.Money}");

        // The title lives past the head slice, at +0x960 in both.
        var titled = new byte[ParcelDbHandlers.ParcelDataNoMsgSize];
        Hex.B(Cap61_ParcelTitle).CopyTo(titled, ParcelDbHandlers.ParcelDataTitle);
        Hex.True(ParcelDbHandlers.ParseParcelData(titled).Title == "No subject",
            "+960 Title");
    }

    /// <summary>
    /// The live bug, and the fix. A MAKE record names its receiver; resolving that name is what
    /// puts the parcel in somebody's inbox instead of user 0's.
    /// </summary>
    [Test] public static void T61_a_parcel_round_trips_from_the_captured_record_to_the_inbox()
    {
        using var store = GuildStore(2);          // characters g1 (id 1) and g2 (id 2)
        var make = Hex.B(Cap61_MakeParcelDataHead);

        // Reading +0x50 straight off the request is the bug: it answers 0.
        Hex.True(ParcelDbHandlers.ParseParcelData(make).ReceiverDbId == 0, "the raw field is 0");
        Hex.True(ParcelDbHandlers.ResolveReceiverDbId(store, make) == 0,
            "and 'two' is not in this store, so the resolver refuses rather than inventing a row");

        // The same record addressed to somebody who exists.
        var mine = (byte[])make.Clone();
        Array.Clear(mine, ParcelDbHandlers.ParcelDataReceiverName, 8);
        const string who = "g2";
        for (int i = 0; i < who.Length; i++)
            BitConverter.GetBytes((ushort)who[i]).CopyTo(mine, ParcelDbHandlers.ParcelDataReceiverName + i * 2);
        int to = ParcelDbHandlers.ResolveReceiverDbId(store, mine);
        Hex.True(to == 2, $"the name resolves to the db id: {to}");

        var f = ParcelDbHandlers.ParseParcelData(mine);
        int parcelId = store.CreateParcel(f.SenderDbId, f.SenderName, to, f.Title, string.Empty, f.Money);
        store.SetParcelRecord(parcelId, mine);

        var inbox = store.GetParcelsFor(to);
        Hex.True(inbox.Count == 1, $"the inbox has it: {inbox.Count}");
        Hex.True(inbox[0].SenderName == "Test" && inbox[0].Money == 100,
            $"with the sender and money off the record: '{inbox[0].SenderName}' {inbox[0].Money}");
        Hex.True(store.GetParcelsFor(1).Count == 0, "and nobody else's inbox moved");

        var body = ParcelDbHandlers.BuildParcelList(store, to, out uint count, out uint maxPage);
        Hex.True(count == 1 && maxPage == 1, $"one parcel, one page: {count}/{maxPage}");
        Hex.True(body.Length == ParcelDbHandlers.ParcelDataNoMsgSize,
            $"the list stride is 0x9e8, as the capture's 2536-byte record is: {body.Length}");
        Hex.True(ParcelDbHandlers.ParseParcelData(body).ReceiverDbId == to,
            "and the record we serve has the receiver FILLED IN, which is what seq 1539 shows");

        Hex.True(store.DeleteParcel(parcelId), "delete removes it");
        Hex.True(store.GetParcelsFor(to).Count == 0, "and the inbox is empty again");
    }

    /// <summary>
    /// The three party windows, from the client half of the same session. The looting block is
    /// the same 19 bytes the A-&gt;W frames carry (PARTY-DESIGN.md section 6.3), which is worth
    /// pinning because the .def is missing a field of it.
    /// </summary>
    [Test] public static void T61_the_party_windows_are_the_captured_client_packets()
    {
        var mgr = Hex.B(Cap61_S_CHANGE_PARTY_MANAGER);
        Hex.True(mgr.Length == 22 && BitConverter.ToUInt16(mgr, 0) == 22, "S_CHANGE_PARTY_MANAGER is 22 bytes");
        Hex.True(BitConverter.ToUInt16(mgr, 4) == 0x0E, "[04] name offset, packet-relative 0x0E");
        Hex.True(BitConverter.ToInt32(mgr, 6) == 2800 && BitConverter.ToInt32(mgr, 10) == 1002,
            "[06] planetId 2800, [0A] the new manager's db id");
        Hex.True(ContractBroker.ReadWString(mgr, 0x0E) == "two", "then the name");

        var loot = Hex.B(Cap61_S_PARTY_LOOTING_METHOD);
        Hex.True(loot.Length == 23, "S_PARTY_LOOTING_METHOD is 4 + the 19-byte block");
        var s = new PartyPackets.LootSettings(
            Method: BitConverter.ToInt32(loot, 4), RareGradeForDicing: BitConverter.ToInt32(loot, 8),
            RareItemDistributionMethod: BitConverter.ToInt32(loot, 12),
            EquipmentForDicing: loot[16] != 0, FindClassForDicing: loot[17] != 0,
            BoundOnLootItemDistributionMethod: BitConverter.ToInt32(loot, 18), ForbidLootingInBattle: loot[22] != 0);
        Hex.True(s == new PartyPackets.LootSettings(0, 1, 0, false, true, 1, false),
            $"the client sees exactly what SA_CHANGE_LOOTING_METHOD carried: {s}");

        var lst = Hex.B(Cap61_S_PARTY_MEMBER_LIST);
        Hex.True(BitConverter.ToUInt16(lst, 4) == 1 && BitConverter.ToUInt16(lst, 6) == 0x32,
            "[04] array count 1, [06] array offset 0x32 - the ref header comes first");
        Hex.True(BitConverter.ToInt64(lst, 14) == 0x0AF0_0014_0000_0001L,
            "and the PartyId is the one AS_DO_CREATE_PARTY made");
        Hex.True(BitConverter.ToInt32(lst, 22) == 2800 && BitConverter.ToInt32(lst, 26) == 2,
            "followed by the leader's planet and db id");
    }

    /// <summary>
    /// SDB_LOAD_PREMIUM_SLOT_LEFT_COOLTIME (0x28BD, seq 644) is a per-user login load carrying a
    /// DlmId, and nothing answered it - it fell through to the replay table. The reply's list
    /// offset is written even when the list is empty.
    /// </summary>
    [Test] public static void T61_the_premium_slot_cooltime_load_is_answered()
    {
        var cap = Hex.B(Cap61_PremiumCooltimeReply);
        Hex.True(cap.Length == 51 - 6, $"the captured reply is 51 bytes, got {cap.Length + 6}");
        var records = cap[DbProxyHandlers.PremiumSlotReplyHeader..];
        Hex.True(records.Length == 2 * DbProxyHandlers.PremiumSlotRecordSize, "two 16-byte records");
        Hex.Eq(DbProxyHandlers.BuildDbsPremiumSlotCooltime(0x98, records), cap,
            "0x28BE, cap_social.log seq 645");

        var empty = DbProxyHandlers.BuildDbsPremiumSlotCooltime(0x98);
        Hex.True(empty.Length == DbProxyHandlers.PremiumSlotReplyHeader, "an empty reply is the header alone");
        Hex.True(BitConverter.ToUInt32(empty, 0) == 19 && BitConverter.ToUInt32(empty, 4) == 0,
            "with the offset slot still written - frame 19, count 0");
        Hex.True(DbProxyHandlers.IsHandledRequest(DbProxyHandlers.SDB_LOAD_PREMIUM_SLOT_LEFT_COOLTIME),
            "and 0x28BD is allow-listed now");
    }

    // ===================== T62: three live leftovers =====================

    /// <summary>
    /// C_ASK_INTERACTIVE -&gt; S_ANSWER_INTERACTIVE. Right-clicking a friend sends the first and the
    /// client will not open its context menu without the second, which is what put friend delete
    /// out of reach. Request offsets are Handler_C_ASK_INTERACTIVE's own reads (guard 0x0E); the
    /// reply field order is the writer's, and the names are the PDL dumper's.
    /// </summary>
    [Test] public static void T62_ask_interactive_answers_at_the_handlers_offsets()
    {
        var body = Hex.B("0E 00  03 00 00 00  F0 0A 00 00  64 00 6F 00 62 00 00 00");
        var r = ArbiterClientHandlers.ParseAskInteractive(body);
        Hex.True(r != null, "an 18-byte body (22-byte packet) parses");
        Hex.True(r!.Value.AskType == 3 && r.Value.TargetPlanetId == 2800 && r.Value.TargetName == "dob",
            $"type {r.Value.AskType}, planet {r.Value.TargetPlanetId}, name '{r.Value.TargetName}'");
        Hex.True(ArbiterClientHandlers.ParseAskInteractive(new byte[9]) == null,
            "one byte short of the guard is refused");

        Hex.Eq(ArbiterClientHandlers.BuildAnswerInteractive(3, 10101, 65, true, false, 2800, "dob"),
            "20 00  C8 85  18 00  03 00 00 00  75 27 00 00  41 00 00 00  01  00  F0 0A 00 00  "
            + "64 00 6F 00 62 00 00 00",
            "S_ANSWER_INTERACTIVE: [nameOff=24][AskType][TargetTemplateId][TargetLevel]"
            + "[TargetInParty][TargetInGuild][TargetPlanetId][name]");
        Hex.True(ArbiterClientHandlers.AskInteractivePacketSize == 0x0E
                 && ArbiterClientHandlers.AnswerInteractivePacketSize == 0x18,
            "the two sizes the guards compare against");
    }

    /// <summary>
    /// S_WATCHED_MOVIES, built the way Account::SendWatchedMoviesToClient builds it: the standard
    /// TERA list encoding, count at 0x04 and the first element's offset at 0x06, each element
    /// carrying its own offset and the next one's (0 on the last). An empty list is the 8-byte
    /// fixed part with both slots zero - which is the answer a character who has seen nothing
    /// gets, and is still an answer, so the intro stops replaying.
    /// </summary>
    [Test] public static void T62_watched_movies_uses_the_standard_list_encoding()
    {
        Hex.Eq(ArbiterClientHandlers.BuildWatchedMovies(null),
            "08 00  A4 97  00 00  00 00",
            "nothing seen yet: count 0, offset 0");
        Hex.Eq(ArbiterClientHandlers.BuildWatchedMovies(new[] { 1001, 1002 }),
            "18 00  A4 97  02 00  08 00  08 00  10 00  E9 03 00 00  10 00  00 00  EA 03 00 00",
            "two movies: each entry is [here][next][movieId], next 0 on the last");
        Hex.True(ArbiterClientHandlers.WatchedMoviesPacketSize == 4,
            "the request is header-only - Handler_C_WATCHED_MOVIES guards on param_3 < 4 and reads nothing");
    }

    /// <summary>
    /// C_FINDNAME -&gt; S_FINDNAME, pinned against the REAL Arbiter's replies in
    /// D:\packetlogs\cap_social_client_ctl.txt frames 1093 / 1096 / 1098 - three keystrokes of
    /// "two", each answered with the query echoed and an empty result.
    /// </summary>
    [Test] public static void T62_findname_matches_the_real_arbiters_replies()
    {
        // frame 1097 C->S, verbatim
        var req = ArbiterClientHandlers.ParseFindName(Hex.B("0A 00  01 00 00 00  74 00 77 00 6F 00 00 00"));
        Hex.True(req != null && req.Value.FindType == 1 && req.Value.Query == "two",
            $"C_FINDNAME parses to type {req?.FindType}, query '{req?.Query}'");

        // frames 1093 / 1096 / 1098 S->C, verbatim
        Hex.Eq(ArbiterClientHandlers.BuildFindName(1, "t", null),
            "12 00  5D F9  0C 00  10 00  01 00 00 00  74 00 00 00  00 00", "frame 1093");
        Hex.Eq(ArbiterClientHandlers.BuildFindName(1, "tw", Array.Empty<string>()),
            "14 00  5D F9  0C 00  12 00  01 00 00 00  74 00 77 00 00 00  00 00", "frame 1096");
        Hex.Eq(ArbiterClientHandlers.BuildFindName(1, "two", Array.Empty<string>()),
            "16 00  5D F9  0C 00  14 00  01 00 00 00  74 00 77 00 6F 00 00 00  00 00", "frame 1098");

        // and the shape of a hit - the separator is the one byte T62 guessed rather than read
        Hex.Eq(ArbiterClientHandlers.BuildFindName(1, "two", new[] { "dob" }),
            "1C 00  5D F9  0C 00  14 00  01 00 00 00  74 00 77 00 6F 00 00 00  64 00 6F 00 62 00 00 00",
            "one match, at the second string offset");
        Hex.True(ArbiterClientHandlers.FindNameMaxResults == 10,
            "User::FindNameLog re-tests list.size() < 10 in each of its three passes");
        Hex.True(ArbiterClientHandlers.ParseFindName(new byte[5]) == null, "5 B is one short of the guard");
    }

    // ===================== T74: the 2026-09-16 economy pass =====================

    /// <summary>
    /// Withdrawing from the bank was ADDING to the bank row. op 2 and op 0x11 do not share a sign
    /// convention: cap_social2.log has op 2 signed against the bag (-1 banking at seq 2005, +1
    /// withdrawing at seq 2096) while op 0x11 sits on the warehouse row and is positive BOTH
    /// times (+20 seq 2074, +1 seq 2096) and only ever appears on a GET. It is a magnitude to
    /// remove.
    /// </summary>
    [Test] public static void T74_a_warehouse_withdraw_takes_the_amount_out()
    {
        using var store = GuildStore(2);
        store.UpsertItem(500, 2, WarehouseHandlers.InvenAccountWarehouse, 0, 6550, 20);

        // seq 2074's pair: 20 into the bag, 20 out of the bank.
        const int hdr = WarehouseHandlers.GetRequestSize;
        var payload = new byte[hdr + 2 * DbProxyHandlers.ItemAtomSize];
        BitConverter.GetBytes((uint)(6 + hdr)).CopyTo(payload, WarehouseHandlers.GetReqBinaryRef);
        BitConverter.GetBytes((uint)(2 * DbProxyHandlers.ItemAtomSize)).CopyTo(payload, WarehouseHandlers.GetReqBinaryRef + 4);
        BitConverter.GetBytes(0xBCu).CopyTo(payload, WarehouseHandlers.GetReqDlmId);
        BrokerAtom(0, WarehouseHandlers.TsInsertItem, 0, 6550, 20, 1, 0, 0, 1, BagItems.Pocket, 0)
            .CopyTo(payload, hdr);
        BrokerAtom(1, WarehouseHandlers.TsWareChangeAmount, 0, 6550, 20,
                   2, WarehouseHandlers.InvenAccountWarehouse, 0,
                   2, WarehouseHandlers.InvenAccountWarehouse, 0)
            .CopyTo(payload, hdr + DbProxyHandlers.ItemAtomSize);

        var (op, _) = RunHandler1(DbProxyHandlers.SDB_GET_WAREHOUSE, payload, store);
        Hex.True(op == DbProxyHandlers.DBS_GET_WAREHOUSE, $"0x{op:X4}");

        var bank = store.GetItems(2, WarehouseHandlers.InvenAccountWarehouse);
        Hex.True(bank.Count == 0, $"the bank row is empty and pruned, not doubled: {bank.Count} row(s)");
        var bag = store.GetInventoryItems(1);
        Hex.True(bag.Count == 1 && bag[0].Amount == 20, $"and the 20 arrived in the bag: {bag.Count}");
    }

    /// <summary>
    /// SDB_RECV_PARCEL is two-step, like the broker. cap_social.log seq 1553..1556: step 1 has no
    /// atoms and is answered with the 3544-byte FULL record; step 2 brings the attachment atoms.
    /// We answered step 1 with the short 0x9e8 list form and paid the gold there, so World had no
    /// attachment slots to build step 2 from and never sent one.
    /// </summary>
    [Test] public static void T74_the_parcel_receive_is_two_step()
    {
        using var store = GuildStore(2);
        int id = store.CreateParcel(2, "Test", 1, "here", string.Empty, 500);
        // The full record World sent us, attachment region and all.
        var full = new byte[3544];
        Hex.B(Cap61_MakeParcelDataHead).CopyTo(full, 0);
        full[3000] = 0x7F;                       // a byte only the full form can carry
        store.SetParcelRecord(id, full);

        byte[] Request(uint step, int atoms)
        {
            var p = new byte[ParcelDbHandlers.RecvRequestSize + atoms * DbProxyHandlers.ItemAtomSize];
            BitConverter.GetBytes((uint)(6 + ParcelDbHandlers.RecvRequestSize))
                .CopyTo(p, ParcelDbHandlers.RecvReqTransListRef);
            BitConverter.GetBytes((uint)(atoms * DbProxyHandlers.ItemAtomSize))
                .CopyTo(p, ParcelDbHandlers.RecvReqTransListRef + 4);
            BitConverter.GetBytes(0xA8u).CopyTo(p, ParcelDbHandlers.RecvReqDlmId);
            BitConverter.GetBytes(step).CopyTo(p, ParcelDbHandlers.RecvReqStep);
            BitConverter.GetBytes((uint)id).CopyTo(p, ParcelDbHandlers.RecvReqParcelId);
            for (int i = 0; i < atoms; i++)
                BrokerAtom(i, WarehouseHandlers.TsInsertItem, 0, 6560, 1, 0, 0, 0, 1, BagItems.Pocket, 4)
                    .CopyTo(p, ParcelDbHandlers.RecvRequestSize + i * DbProxyHandlers.ItemAtomSize);
            return p;
        }

        long before = store.GetCharacterMoney(1);
        var (op1, b1) = RunHandler1(DbProxyHandlers.SDB_RECV_PARCEL, Request(1, 0), store);
        Hex.True(op1 == DbProxyHandlers.DBS_RECV_PARCEL, $"0x{op1:X4}");
        Hex.True(BitConverter.ToUInt32(b1, ParcelDbHandlers.RecvRspParcelDataRef + 4) == 3544,
            $"step 1 carries the FULL 3544-byte record, not the 0x9e8 list form: "
            + $"{BitConverter.ToUInt32(b1, ParcelDbHandlers.RecvRspParcelDataRef + 4)}");
        Hex.True(BitConverter.ToUInt32(b1, ParcelDbHandlers.RecvRspTransListRef + 4) == 0,
            "and no atoms - World has not built them yet");
        Hex.True(b1[ParcelDbHandlers.RecvRspParcelDataRef + 4 + 0] != 0
                 && b1[ParcelDbHandlers.RecvRspSuccess] == 1, "Success 1");
        Hex.True(store.GetCharacterMoney(1) == before,
            "the gold is NOT paid on the read pass - that was the live bug's other half");

        var (_, b2) = RunHandler1(DbProxyHandlers.SDB_RECV_PARCEL, Request(2, 1), store);
        Hex.True(BitConverter.ToUInt32(b2, ParcelDbHandlers.RecvRspParcelDataRef + 4) == 3544
                 && BitConverter.ToUInt32(b2, ParcelDbHandlers.RecvRspTransListRef + 4)
                    == DbProxyHandlers.ItemAtomSize,
            "step 2 carries the record AND the atoms echoed, as seq 1556 does");
        Hex.True(store.GetCharacterMoney(1) == before + 500, "and the gold lands on the commit pass");
        Hex.True(store.GetInventoryItems(1).Any(r => r.TemplateId == 6560), "with the attachment");
    }

    /// <summary>
    /// The live "collected 1 of 2" then "0 of 2" loop. A row somebody already collected is not a
    /// failure - the request's atoms were applied either way - and answering Success 0 made World
    /// ask again forever. Both captured step-2 replies carry Success 1.
    /// </summary>
    [Test] public static void T74_an_already_collected_broker_row_is_not_a_failure()
    {
        using var store = GuildStore(2);
        int id = store.CreateBrokerListing(2, "Test", 10029, 139093, 1, 1);
        store.SellBrokerListing(id, 1);

        const int hdr = BrokerPackets.CalcRequestHeader;
        var calc = new byte[hdr + 4 + DbProxyHandlers.ItemAtomSize];
        BitConverter.GetBytes((uint)(6 + hdr)).CopyTo(calc, 0);
        BitConverter.GetBytes(4u).CopyTo(calc, 4);
        BitConverter.GetBytes((uint)(6 + hdr + 4)).CopyTo(calc, 8);
        BitConverter.GetBytes((uint)DbProxyHandlers.ItemAtomSize).CopyTo(calc, 12);
        BitConverter.GetBytes(0xBAu).CopyTo(calc, 16);
        BitConverter.GetBytes(1).CopyTo(calc, 20);
        BitConverter.GetBytes(2).CopyTo(calc, 24);                 // Step 2
        BitConverter.GetBytes(id).CopyTo(calc, hdr);
        BrokerAtom(0, WarehouseHandlers.TsBrokerCalcBought, 0, 0, 0, 1, 0, 0, 0, 0, 0)
            .CopyTo(calc, hdr + 4);

        var (op, first) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_CALC_BOUGHT_ITEM, calc, store);
        Hex.True(op == DbProxyHandlers.DBS_TRADE_BROKER_CALC_BOUGHT_ITEM, $"0x{op:X4}");
        Hex.True(first[24] == 1 && store.GetBrokerListing(id)!.State == CharacterStore.BrokerBuyerCollected,
            "the first commit collects it and says so");

        var (_, again) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_CALC_BOUGHT_ITEM, calc, store);
        Hex.True(again[24] == 1,
            "and the second says Success 1 as well - a row already taken is not a failure, and "
            + "Success 0 is what made World ask again");
    }

    /// <summary>
    /// 0x27DD SDB_ITEM_TRADE_LOG and 0x288C SDB_CASH_ITEM_LOG. Both handlers run to
    /// <c>return 1</c> with no packet writer in them at all (Arb_part_063.c:12031 for the first),
    /// and cap_social2/3 agree: three 0x288C arrive and no A-&gt;W frame follows any of them.
    /// 0x27DD carries a DlmId, but the real Arbiter never answers it either, so World cannot be
    /// waiting on one. Sealing them is about the other half: an unsealed request makes the replay
    /// table attribute the NEXT A-&gt;W frame to it as a response.
    /// </summary>
    [Test] public static void T74_the_two_audit_log_writes_are_sealed()
    {
        Hex.True(WorldReplayTable.OneWayFromWorld.Contains(0x27DD), "SDB_ITEM_TRADE_LOG");
        Hex.True(WorldReplayTable.OneWayFromWorld.Contains(0x288C), "SDB_CASH_ITEM_LOG");
        Hex.True(!DbProxyHandlers.IsHandledRequest(0x27DD) && !DbProxyHandlers.IsHandledRequest(0x288C),
            "and neither is allow-listed - sealed is not the same as answered");
    }

    /// <summary>
    /// A guard, not a feature. The broker's Active Listings and Sold tabs are still served empty
    /// because no capture contains a populated one: cap_social3_client.log holds exactly one
    /// S_TRADE_BROKER_REGISTERED_ITEM_LIST and it is empty (seq 1276), and
    /// S_TRADE_BROKER_SOLD_ITEM_LIST never appears - the client asked twice and the real Arbiter
    /// answered neither. That tap is the BUYER's client, which is why: the buyer had no listings.
    ///
    /// <para>The shipped .def cannot stand in for the capture. The one list layout we HAVE
    /// verified byte for byte disagrees with its own .def: the def gives
    /// <c>uint32 listing, uint32 unk2, int32 unk3, int32 item, int16 quantity</c> where the wire
    /// puts TradeId at +6, an i64 ItemDbId at +10, TemplateId at +18 and a 4-byte Amount at +22.
    /// The shipped defs are from another build (PARTY-DESIGN.md section 6 says the same of the
    /// opcode= comments), so filling the other two tabs from theirs would be a guess dressed up
    /// as a source.</para>
    /// </summary>
    [Test] public static void T74_the_broker_list_defs_disagree_with_the_wire()
    {
        // What the wire says, from cap_social3_client.log seq 1419 / 1472 - already pinned by
        // T72_the_waiting_item_list_is_byte_exact. Restated here as the reason the other two tabs
        // stay empty.
        Hex.True(BrokerPackets.WlTradeId == 6 && BrokerPackets.WlItemDbId == 10
                 && BrokerPackets.WlTemplateId == 18 && BrokerPackets.WlAmount == 22,
            "the verified waiting-list offsets");
        Hex.True(BrokerPackets.WlItemDbId - BrokerPackets.WlTradeId == 4
                 && BrokerPackets.WlTemplateId - BrokerPackets.WlItemDbId == 8,
            "TradeId is 4 bytes and ItemDbId is 8 - the def calls the second one a uint32");

        // And the two tabs the capture does not justify filling in are still the empty form.
        using var store = GuildStore(2);
        store.CreateBrokerListing(2, "Test", 10027, 200997, 1, 10001);
        Hex.Eq(BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_REGISTERED_ITEM_LIST, store, 2)![4..],
            "00 00 00 00", "Active Listings: seq 1276's empty body, even with a row in the table");
        Hex.True(BrokerPackets.EmptyArraySlots == 4,
            "and that empty body is [u16 count][u16 firstOffset], both zero");
    }

    // ===================== T72: the broker's client windows =====================

    /// <summary>cap_social3_client.log seq 1472 - the search page after listing 3 was bought.</summary>
    const string Cap72_WaitingTwoRows =
        "02 00 10 00 00 00 00 00 01 00 00 00 10 00 76 00 "
        + "6C 00 02 00 00 00 2C 27 00 00 00 00 00 00 41 0D "
        + "03 00 01 00 00 00 00 00 00 00 00 00 00 00 00 11 "
        + "27 00 00 00 00 00 00 F9 2A 00 00 00 00 00 00 00 "
        + "00 00 00 02 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 54 00 65 00 73 00 74 00 "
        + "00 00 76 00 00 00 D2 00 01 00 00 00 2B 27 00 00 "
        + "00 00 00 00 25 11 03 00 01 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 11 27 00 00 00 00 00 00 F9 2A 00 "
        + "00 00 00 00 00 00 00 00 00 02 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 54 00 "
        + "65 00 73 00 74 00 00 00";

    /// <summary>cap_social3_client.log seq 1486 - one bought item, not yet collected.</summary>
    const string Cap72_BoughtOneRow =
        "01 00 08 00 08 00 00 00 6A 00 03 00 00 00 00 00 "
        + "00 00 2D 27 00 00 00 00 00 00 55 1F 02 00 01 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 0F 19 AB 6A 00 "
        + "00 00 00 01 00 00 00 00 00 00 00 02 00 00 00 01 "
        + "1E 19 AB 6A 00 00 00 00 01 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 54 00 65 00 73 00 74 00 00 00";

    static (int, long, int, int, long, int, string) WaitRow(
        int tradeId, long itemDbId, int templateId, long price)
        => (tradeId, itemDbId, templateId, 1, price, 2, "Test");

    /// <summary>
    /// S_TRADE_BROKER_WAITING_ITEM_LIST (0xFD2C), the search result page. TERA's ordinary array
    /// encoding with PACKET-relative offsets: the body is [count][firstOffset][page][totalPage]
    /// and each element opens with [here][next][nameOffset].
    /// </summary>
    [Test] public static void T72_the_waiting_item_list_is_byte_exact()
    {
        // seq 1231: nothing on sale. Count and offset both 0, then page 0 of 1.
        Hex.Eq(BrokerPackets.BuildSWaitingItemListBody(null),
            "00 00 00 00 00 00 00 00 01 00 00 00", "seq 1231, the empty search page");

        // seq 1472: two listings, both at 10001, newest first.
        var two = BrokerPackets.BuildSWaitingItemListBody(new[]
        {
            WaitRow(2, 10028, 200001, 10001),
            WaitRow(1, 10027, 200997, 10001),
        });
        Hex.Eq(two, Cap72_WaitingTwoRows, "seq 1472");

        // and the three-row page the same window showed before the buy (seq 1419).
        var three = BrokerPackets.BuildSWaitingItemListBody(new[]
        {
            WaitRow(3, 10029, 139093, 1),
            WaitRow(2, 10028, 200001, 10001),
            WaitRow(1, 10027, 200997, 10001),
        });
        Hex.True(three.Length == 318 && BitConverter.ToUInt16(three, 0) == 3
                 && BitConverter.ToUInt16(three, 2) == 16,
            $"seq 1419 is 322 bytes on the wire, 318 of body: {three.Length}");
        Hex.True(BitConverter.ToUInt16(three, 12) == 16 && BitConverter.ToUInt16(three, 14) == 118
                 && BitConverter.ToUInt16(three, 16) == 108,
            "the first element is at 16, the next at 118 and its name at 108 - a 92-byte fixed part");

        // The tax the list shows: a tenth, truncated. 10001 -> 11001 and 1 -> 1, both captured.
        Hex.True(BrokerPackets.PriceWithTax(10001) == 11001 && BrokerPackets.PriceWithTax(1) == 1,
            "TotalPriceWithTax at +43");
    }

    /// <summary>
    /// S_TRADE_BROKER_BOUGHT_ITEM_LIST (0x53C0). A different element shape from the waiting
    /// list - four more bytes before ItemDbId, and two UNIX timestamps - so the two are not
    /// interchangeable even though most of the field names match.
    /// </summary>
    [Test] public static void T72_the_bought_item_list_is_byte_exact()
    {
        Hex.Eq(BrokerPackets.BuildSBoughtItemListBody(null), "00 00 00 00",
            "seq 1491: this list's empty form carries no page scalars at all");

        var one = BrokerPackets.BuildSBoughtItemListBody(new[]
        {
            (3, 10029L, 139093, 1, 1L, 2, "Test", 0x6AAB190FL, 0x6AAB191EL),
        });
        Hex.Eq(one, Cap72_BoughtOneRow, "seq 1486");
        Hex.True(0x6AAB191E - 0x6AAB190F == 15,
            "the two times are UNIX seconds 15 apart - the same gap the TradeData record's "
            + "RegisterTime and SoldTime have");
    }

    /// <summary>
    /// The three small ones. HIGHEST_ITEM_LEVEL is the fix: T45 answered 0 because there was no
    /// broker, and the real Arbiter answers 469.0 both times it is asked, for both characters.
    /// </summary>
    [Test] public static void T72_the_small_broker_replies_are_byte_exact()
    {
        Hex.Eq(BrokerPackets.BuildSHighestItemLevelBody(), "00 80 EA 43",
            "seq 134 and 3217: the float 469.0, not 0");
        Hex.True(BrokerPackets.HighestItemLevelDefault == 469.0f, "and that is the default we send");
        Hex.Eq(ArbiterClientHandlers.BuildTradeBrokerHighestItemLevel(BrokerPackets.HighestItemLevelDefault),
            "08 00 53 7E 00 80 EA 43", "the whole frame T45's handler sends");

        Hex.Eq(BrokerPackets.BuildSBuyItNowBody(true), "01", "seq 1469");
        Hex.Eq(BrokerPackets.BuildSCalcNotifyBody(0, 1), "00 00 00 00 01 00 00 00",
            "seq 1462: nothing sold waiting, one bought item waiting to be collected");
    }

    /// <summary>
    /// The windows served from the table. The two that stay on the empty form are the point as
    /// much as the two that do not: the capture shows REGISTERED only empty and never shows
    /// SOLD at all, so filling them in by analogy would be a guess.
    /// </summary>
    [Test] public static void T72_the_broker_windows_serve_the_listings_table()
    {
        using var store = GuildStore(2);
        int a = store.CreateBrokerListing(2, "Test", 10027, 200997, 1, 10001);
        int b = store.CreateBrokerListing(2, "Test", 10028, 200001, 1, 10001);

        var waiting = BrokerHandlers.ReplyFor(
            BrokerPackets.C_TRADE_BROKER_WAITING_ITEM_LIST_NEW, store, 1);
        Hex.True(waiting != null && BitConverter.ToUInt16(waiting, 0) == waiting.Length
                 && BitConverter.ToUInt16(waiting, 2) == BrokerPackets.S_TRADE_BROKER_WAITING_ITEM_LIST,
            "a whole client frame comes back");
        Hex.Eq(waiting![4..], Cap72_WaitingTwoRows,
            "and with two rows in the table it is seq 1472 byte for byte - newest first at equal price");

        // Bought: nothing until something is sold to this character.
        Hex.Eq(BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_BOUGHT_ITEM_LIST, store, 1)![4..],
            "00 00 00 00", "an empty bought list");
        store.SellBrokerListing(a, 1);
        var bought = BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_BOUGHT_ITEM_LIST, store, 1)!;
        Hex.True(BitConverter.ToUInt16(bought, 4) == 1
                 && BitConverter.ToInt32(bought, 4 + 4 + BrokerPackets.BlTradeId) == a
                 && BitConverter.ToInt32(bought, 4 + 4 + BrokerPackets.BlSellerDbId) == 2,
            "and one row once it has been bought, keyed on the buyer");

        // The two the capture does not justify filling in.
        Hex.Eq(BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_REGISTERED_ITEM_LIST, store, 2)!,
            BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_REGISTERED_ITEM_LIST)!,
            "REGISTERED is the empty form either way - seq 1276 is the only one captured");
        Hex.Eq(BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_SOLD_ITEM_LIST, store, 2)!,
            BrokerHandlers.ReplyFor(BrokerPackets.C_TRADE_BROKER_SOLD_ITEM_LIST)!,
            "and SOLD never appears in the capture at all");

        // The collect badge, for when a caller needs it. Not wired to a client packet: the three
        // CALC / BUY_IT_NOW C_ opcodes are World's, not ours.
        Hex.Eq(BrokerHandlers.CalcNotifyBodyFor(store, 1), "00 00 00 00 01 00 00 00",
            "one bought item waiting for this character");
        Hex.Eq(BrokerHandlers.CalcNotifyBodyFor(store, 2), "01 00 00 00 00 00 00 00",
            "and one sold item waiting for its seller");
    }

    // ===================== T71: the broker listings table =====================

    /// <summary>One 856-byte broker atom at the offsets the register batch uses.</summary>
    static byte[] BrokerAtom(int index, uint op, long itemDbId, int templateId, long amount,
                             long srcOwner, int srcInven, int srcSlot,
                             long dstOwner, int dstInven, int dstSlot, long price = 0)
    {
        var r = new byte[DbProxyHandlers.ItemAtomSize];
        BitConverter.GetBytes(index).CopyTo(r, 0);
        BitConverter.GetBytes(op).CopyTo(r, WarehouseHandlers.AtomOp);
        BitConverter.GetBytes(itemDbId).CopyTo(r, WarehouseHandlers.AtomItemDbId);
        BitConverter.GetBytes(templateId).CopyTo(r, WarehouseHandlers.AtomTemplateId);
        BitConverter.GetBytes(srcOwner).CopyTo(r, WarehouseHandlers.AtomSrcOwner);
        BitConverter.GetBytes(srcInven).CopyTo(r, WarehouseHandlers.AtomSrcInven);
        BitConverter.GetBytes(srcSlot).CopyTo(r, WarehouseHandlers.AtomSrcSlot);
        BitConverter.GetBytes(dstOwner).CopyTo(r, WarehouseHandlers.AtomDstOwner);
        BitConverter.GetBytes(dstInven).CopyTo(r, WarehouseHandlers.AtomDstInven);
        BitConverter.GetBytes(dstSlot).CopyTo(r, WarehouseHandlers.AtomDstSlot);
        BitConverter.GetBytes(amount).CopyTo(r, WarehouseHandlers.AtomDelta);
        BitConverter.GetBytes(price).CopyTo(r, BrokerPackets.RegisterAtomPriceOffset);
        return r;
    }

    /// <summary>A broker request: a fixed header, then one ref's worth of atoms.</summary>
    static byte[] BrokerRequest(int header, int atomRefOffset, params byte[][] atoms)
    {
        int bytes = atoms.Length * DbProxyHandlers.ItemAtomSize;
        var p = new byte[header + bytes];
        BitConverter.GetBytes((uint)(6 + header)).CopyTo(p, atomRefOffset);
        BitConverter.GetBytes((uint)bytes).CopyTo(p, atomRefOffset + 4);
        for (int i = 0; i < atoms.Length; i++) atoms[i].CopyTo(p, header + i * DbProxyHandlers.ItemAtomSize);
        return p;
    }

    /// <summary>
    /// The three record forms the broker replies carry, byte-exact against cap_social3.log. All
    /// three are the same 0x188 struct: a plain TradeData (seq 1881), the CalcItemList form with
    /// the settlement block (seq 1947 / 1905), and the cleared one a cancel returns (seq 2003).
    /// </summary>
    [Test] public static void T71_the_three_trade_record_forms_are_byte_exact()
    {
        var trade = BrokerPackets.BuildTradeData(3, 2, "Test", 10029, 139093, 1, 1,
            new DateTime(2026, 9, 16, 22, 32, 47));

        // seq 1947: the seller's collect. CalcState 3, buyer 1003, sold 22:33:02, money 1.
        var sold = BrokerPackets.BuildCalcItemData(trade, BrokerPackets.CalcStateSold, 1003, 1,
            new DateTime(2026, 9, 16, 22, 33, 2));
        Hex.True(BitConverter.ToInt32(sold, BrokerPackets.TdCalcState) == 3
                 && BitConverter.ToInt32(sold, BrokerPackets.TdBuyerDbId) == 1003
                 && BitConverter.ToInt32(sold, BrokerPackets.TdBuyerFlag) == 1
                 && BitConverter.ToInt64(sold, BrokerPackets.TdSoldPrice) == 1
                 && BitConverter.ToInt64(sold, BrokerPackets.TdCalcMoney) == 1,
            "the settlement block CALC_SOLD adds on top of TradeData");
        Hex.Eq(sold[BrokerPackets.TdSoldTime..(BrokerPackets.TdSoldTime + 16)],
            "EA 07 09 00 10 00 16 00 21 00 02 00 00 00 00 00", "SoldTime at +0xD8, 2026-09-16 22:33:02");

        // seq 1905: the buyer's collect differs from the seller's in ONE field.
        var bought = BrokerPackets.BuildCalcItemData(trade, BrokerPackets.CalcStateBought, 1003, 1,
            new DateTime(2026, 9, 16, 22, 33, 2));
        int diffs = 0;
        for (int i = 0; i < sold.Length; i++) if (sold[i] != bought[i]) diffs++;
        Hex.True(diffs == 1 && BitConverter.ToInt32(bought, BrokerPackets.TdCalcState) == 2,
            $"the two calc records differ only at +0x58: {diffs} byte(s)");

        // seq 2003: the cancel's record is present and entirely zero.
        var cleared = BrokerPackets.BuildClearedTradeData();
        Hex.True(cleared.Length == BrokerPackets.TradeDataSize && cleared.All(x => x == 0),
            "a cancelled listing comes back as 0x188 zero bytes, not as an absent ref");
    }

    /// <summary>
    /// SDB_TRADE_BROKER_REGISTER_ITEM. One pass, no Step. The price is in the op-53 atom at
    /// +0x288 and nowhere else - the request has no price field at all - and the op-44 atom
    /// moves the row into inven 6, the broker's holding pocket.
    /// </summary>
    [Test] public static void T71_registering_creates_a_listing_and_pockets_the_item()
    {
        using var store = GuildStore(2);
        store.UpsertItem(10029, 2, BagItems.Pocket, 6, 139093, 1);
        // The seller has to be able to AFFORD the listing fee. AddCharacterMoney clamps at zero
        // (MAX(0, money + delta)), so on a character created with no gold the -500 atom lands as
        // a no-op and the assertion below can never hold - which is what made this test red.
        // The real seller in cap_social3.log seq 1515 had gold; so does this one now.
        store.AddCharacterMoney(2, 5000);
        long goldBefore = store.GetCharacterMoney(2);
        Hex.True(goldBefore == 5000, $"the seller starts with gold: {goldBefore}");

        var payload = BrokerRequest(BrokerPackets.RegisterRequestHeader, 0,
            BrokerAtom(0, WarehouseHandlers.TsChangeMoney, 0, 0, -500, 2, 0, 0, 2, 0, 0),
            BrokerAtom(1, WarehouseHandlers.TsBrokerRegister, 10029, 139093, 1, 2, 0, 0, 2, 0, 0, price: 10001),
            BrokerAtom(2, WarehouseHandlers.TsBrokerMoveItem, 10029, 139093, 1, 2, 0, 0, 2, WarehouseHandlers.InvenBroker, 0));
        BitConverter.GetBytes(0xB4u).CopyTo(payload, 8);      // DlmId at payload 8
        BitConverter.GetBytes(2).CopyTo(payload, 12);         // OwnerDbId at payload 12

        var (op, body) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_REGISTER_ITEM, payload, store);
        Hex.True(op == BrokerPackets.DBS_TRADE_BROKER_REGISTER_ITEM, $"replied 0x{op:X4}, want 0x2818");
        Hex.True(BitConverter.ToUInt32(body, 0) == 0x13
                 && BitConverter.ToUInt32(body, 4) == 3 * DbProxyHandlers.ItemAtomSize
                 && BitConverter.ToUInt32(body, 8) == 0xB4 && body[12] == 1,
            "seq 1515's header: [0x13][atom bytes][DlmId][Success 1], then the atoms echoed");
        Hex.Eq(body[13..], payload[BrokerPackets.RegisterRequestHeader..],
            "every atom comes back verbatim - none of them arrives with an id to allocate");

        var listing = store.GetBrokerListing(1);
        Hex.True(listing != null && listing.SellerDbId == 2 && listing.ItemDbId == 10029
                 && listing.TemplateId == 139093 && listing.Price == 10001
                 && listing.State == TeraSharp.Arbiter.Persistence.CharacterStore.BrokerListed,
            $"the listing: {listing?.ItemDbId} for {listing?.Price}, state {listing?.State}");
        Hex.True(store.GetCharacterMoney(2) == goldBefore - 500, "the op-9 atom took the listing fee");
        var pocketed = store.GetItems(2, WarehouseHandlers.InvenBroker);
        Hex.True(pocketed.Count == 1 && pocketed[0].ItemDbId == 10029,
            "and op 44 moved the row into inven 6 rather than deleting it");
    }

    /// <summary>
    /// The two-step commit, over all four of the Step-carrying opcodes. Step 1 reads the listing
    /// back and moves nothing; Step 2 applies the atoms and advances the row. The three
    /// different shapes of Step-2 reply are the point: the cancel returns a ZEROED record, the
    /// two calcs return NO record, and the buy returns the record unchanged.
    /// </summary>
    [Test] public static void T71_the_two_step_commit_walks_a_listing_to_collected()
    {
        using var store = GuildStore(2);
        int id = store.CreateBrokerListing(2, "Test", 10029, 139093, 1, 1);

        // ---- BUY_IT_NOW step 1: read. No atoms either way. ----
        var buy1 = new byte[BrokerPackets.BuyItNowRequestHeader];
        BitConverter.GetBytes((uint)(6 + buy1.Length)).CopyTo(buy1, 0);
        BitConverter.GetBytes(0xB9u).CopyTo(buy1, 8);
        BitConverter.GetBytes(1).CopyTo(buy1, 12);            // buyer 1 (GuildStore's g1)
        BitConverter.GetBytes(1).CopyTo(buy1, 16);            // Step 1
        BitConverter.GetBytes(id).CopyTo(buy1, 20);
        var (op1, b1) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_BUY_IT_NOW, buy1, store);
        Hex.True(op1 == BrokerPackets.DBS_TRADE_BROKER_BUY_IT_NOW, $"0x{op1:X4}");
        Hex.True(BitConverter.ToUInt32(b1, 0) == 0x1F
                 && BitConverter.ToUInt32(b1, 4) == BrokerPackets.TradeDataSize
                 && BitConverter.ToUInt32(b1, 12) == 0 && BitConverter.ToUInt32(b1, 20) == 1
                 && b1[24] == 1,
            "seq 1881: the TradeData record, no atoms, Step echoed, Success 1");
        var read = BrokerPackets.ParseTradeData(b1, 25);
        Hex.True(read != null && read.Value.TradeId == id && read.Value.Price == 1
                 && read.Value.SellerName == "Test",
            "and it is the listing, which is what World builds the step-2 atoms from");

        // ---- step 2: commit ----
        var buy2 = BrokerRequest(BrokerPackets.BuyItNowRequestHeader, 0,
            BrokerAtom(0, WarehouseHandlers.TsChangeMoney, 0, 0, -1, 1, 0, 0, 1, 0, 0),
            BrokerAtom(1, WarehouseHandlers.TsBrokerBuy, 0, 0, 1, 1, 0, 0, 0, 0, 0));
        BitConverter.GetBytes(0xB9u).CopyTo(buy2, 8);
        BitConverter.GetBytes(1).CopyTo(buy2, 12);
        BitConverter.GetBytes(2).CopyTo(buy2, 16);
        BitConverter.GetBytes(id).CopyTo(buy2, 20);
        var (_, b2) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_BUY_IT_NOW, buy2, store);
        Hex.True(BitConverter.ToUInt32(b2, 4) == BrokerPackets.TradeDataSize
                 && BitConverter.ToUInt32(b2, 12) == 2 * DbProxyHandlers.ItemAtomSize
                 && BitConverter.ToUInt32(b2, 20) == 2 && b2[24] == 1,
            "seq 1883: the record is STILL there on a buy, plus the atoms echoed");
        Hex.True(store.GetBrokerListing(id)!.State == TeraSharp.Arbiter.Persistence.CharacterStore.BrokerSold
                 && store.GetBrokerListing(id)!.BuyerDbId == 1, "the row is sold to the buyer");

        // A second buyer racing the same TradeId loses, even though step 1 said yes.
        var (_, again) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_BUY_IT_NOW, buy2, store);
        Hex.True(again[24] == 0, "the second commit is refused - and still echoes the DlmId");

        // ---- CALC_SOLD step 2: the seller collects. No record in the reply at all. ----
        // header | CalcList (one i32) | atoms - exactly the seq-1948 shape.
        var calcAtoms = new[]
        {
            BrokerAtom(0, WarehouseHandlers.TsBrokerCalcSold, 0, 0, 0, 2, 0, 0, 0, 0, 0),
            BrokerAtom(1, WarehouseHandlers.TsChangeMoney, 0, 0, 1, 2, 0, 0, 2, 0, 0),
        };
        const int calcHdr = BrokerPackets.CalcRequestHeader;
        var calc = new byte[calcHdr + 4 + calcAtoms.Length * DbProxyHandlers.ItemAtomSize];
        BitConverter.GetBytes((uint)(6 + calcHdr)).CopyTo(calc, 0);          // CalcList offset
        BitConverter.GetBytes(4u).CopyTo(calc, 4);                           // one i32
        BitConverter.GetBytes((uint)(6 + calcHdr + 4)).CopyTo(calc, 8);      // ItemBinary offset
        BitConverter.GetBytes((uint)(calcAtoms.Length * DbProxyHandlers.ItemAtomSize)).CopyTo(calc, 12);
        BitConverter.GetBytes(0xBBu).CopyTo(calc, 16);
        BitConverter.GetBytes(2).CopyTo(calc, 20);
        BitConverter.GetBytes(2).CopyTo(calc, 24);                           // Step 2
        BitConverter.GetBytes(id).CopyTo(calc, calcHdr);
        for (int i = 0; i < calcAtoms.Length; i++)
            calcAtoms[i].CopyTo(calc, calcHdr + 4 + i * DbProxyHandlers.ItemAtomSize);
        var (opC, bC) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_CALC_SOLD_ITEM, calc, store);
        Hex.True(opC == BrokerPackets.DBS_TRADE_BROKER_CALC_SOLD_ITEM, $"0x{opC:X4}");
        Hex.True(BitConverter.ToUInt32(bC, 0) == 0x1F && BitConverter.ToUInt32(bC, 4) == 0,
            "seq 1949: a calc step 2 carries NO record - offset 0x1F, length 0");
        Hex.True(store.GetBrokerListing(id)!.State == TeraSharp.Arbiter.Persistence.CharacterStore.BrokerSellerPaid,
            "and the seller has been paid");

        // ---- UNREGISTER step 2 on a fresh listing: a ZEROED record, not an absent one. ----
        int other = store.CreateBrokerListing(2, "Test", 10027, 200997, 1, 10001);
        var un = BrokerRequest(BrokerPackets.UnregisterRequestHeader, 0,
            BrokerAtom(0, WarehouseHandlers.TsBrokerCancel, 0, 0, 0, 2, 0, 0, 0, 0, 0));
        BitConverter.GetBytes(0xBCu).CopyTo(un, 8);
        BitConverter.GetBytes(2).CopyTo(un, 12);
        BitConverter.GetBytes(2).CopyTo(un, 16);
        BitConverter.GetBytes(other).CopyTo(un, 20);
        var (opU, bU) = RunHandler1(DbProxyHandlers.SDB_TRADE_BROKER_UNREGISTER_ITEM, un, store);
        Hex.True(opU == BrokerPackets.DBS_TRADE_BROKER_UNREGISTER_ITEM, $"0x{opU:X4}");
        Hex.True(BitConverter.ToUInt32(bU, 4) == BrokerPackets.TradeDataSize
                 && bU[25..(25 + BrokerPackets.TradeDataSize)].All(x => x == 0),
            "seq 2003: the record is present and every byte of it is zero");
        Hex.True(store.GetBrokerListing(other)!.State == TeraSharp.Arbiter.Persistence.CharacterStore.BrokerCancelled, "withdrawn");
    }

    /// <summary>The store half: search paging is bounds-checked as unsigned, and the state
    /// machine only moves in the directions the protocol allows.</summary>
    [Test] public static void T71_the_listings_table_round_trips()
    {
        using var store = GuildStore(2);
        int a = store.CreateBrokerListing(2, "Test", 101, 5000, 1, 900);
        int b = store.CreateBrokerListing(2, "Test", 102, 5000, 1, 100);
        Hex.True(a == 1 && b == 2, $"trade ids come off the table: {a}/{b}");

        var page = store.SearchBrokerListings(5000, 0, 10);
        Hex.True(page.Count == 2 && page[0].TradeId == b, "cheapest first");
        Hex.True(store.CountBrokerListings(5000) == 2 && store.CountBrokerListings(0) == 2
                 && store.CountBrokerListings(9999) == 0, "the count matches the filter");
        Hex.True(store.SearchBrokerListings(0, -1, 10).Count == 0,
            "a negative page is read UNSIGNED and lands past the end rather than before the start");

        Hex.True(store.SetBrokerListingPrice(a, 50) && store.GetBrokerListing(a)!.Price == 50, "reprice");
        Hex.True(store.SellBrokerListing(a, 1) && !store.SellBrokerListing(a, 1),
            "a listing sells once");
        Hex.True(!store.SetBrokerListingState(a, TeraSharp.Arbiter.Persistence.CharacterStore.BrokerListed, TeraSharp.Arbiter.Persistence.CharacterStore.BrokerCancelled),
            "and a sold listing cannot then be cancelled");
        Hex.True(store.GetBrokerListingsOf(2).Count == 1, "one still on sale");
        Hex.True(store.GetBrokerPurchasesOf(1).Count == 1, "and one waiting for its buyer");
        Hex.True(store.DeleteBrokerListing(b) && store.GetBrokerListing(b) == null, "delete");
    }

    // ===================== T70: cap_social3.log, broker + EP =====================

    /// <summary>cap_social3.log seq 112, AS_LOAD_EXTRAPOINT_DATA for character 1003, DlmId 0x27.</summary>
    const string Cap70_ExtrapointRsp =
        "27 00 00 00 01 EB 03 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00";

    /// <summary>
    /// The EP panel load. The old builder put the low byte of the player id where Result belongs
    /// and a 1 where the four-byte UserDbId starts, so World read back user 1 for every
    /// character. The length was right by accident; the placement was not.
    /// </summary>
    [Test] public static void T70_the_extrapoint_load_is_byte_exact()
    {
        var req = Hex.B("27 00 00 00 EB 03 00 00");          // seq 111: DlmId 0x27, user 1003
        var rsp = DbProxyHandlers.BuildExtrapointData(req);
        Hex.True(rsp.Length == DbProxyHandlers.ExtrapointReplySize && rsp.Length == 53,
            $"53 payload bytes (frame 0x3B, the reply guard): {rsp.Length}");
        Hex.Eq(rsp, Hex.B(Cap70_ExtrapointRsp), "0x1555, cap_social3.log seq 112");
        Hex.True(rsp[4] == 1 && BitConverter.ToInt32(rsp, 5) == 1003,
            "Result at +4 and the FULL four-byte UserDbId at +5");
        Hex.True(DbProxyHandlers.BuildExtrapointData(Array.Empty<byte>()).Length == 53,
            "a short request still gets a whole frame - it carries a DlmId and must be answered");
    }

    /// <summary>
    /// The broker's TradeData / CalcItemList record, 0x188 bytes. T53 left it undecoded and T55
    /// could only echo; cap_social3.log is the first capture that contains one. Pinned to the
    /// record DBS_TRADE_BROKER_BUY_IT_NOW returns for listing 3 (seq 1881 and 1883, identical).
    /// </summary>
    [Test] public static void T70_the_broker_trade_data_record_is_byte_exact()
    {
        Hex.True(BrokerPackets.TradeDataSize == 0x188, "392 bytes, the length every ref slot declares");

        var rec = BrokerPackets.BuildTradeData(
            tradeId: 3, sellerDbId: 2, sellerName: "Test", itemDbId: 10029, templateId: 139093,
            amount: 1, price: 1, registerTime: new DateTime(2026, 9, 16, 22, 32, 47));

        Hex.True(rec.Length == 0x188, $"{rec.Length}");
        Hex.True(BitConverter.ToInt32(rec, BrokerPackets.TdTradeId) == 3
                 && BitConverter.ToInt32(rec, BrokerPackets.TdSellerDbId) == 2
                 && BitConverter.ToInt64(rec, BrokerPackets.TdItemDbId) == 10029
                 && BitConverter.ToInt32(rec, BrokerPackets.TdTemplateId) == 139093
                 && BitConverter.ToInt32(rec, BrokerPackets.TdAmount) == 1
                 && BitConverter.ToInt64(rec, BrokerPackets.TdPrice) == 1,
            "TradeId/SellerDbId/ItemDbId/TemplateId/Amount/Price at the captured offsets");
        Hex.Eq(rec[BrokerPackets.TdSellerName..(BrokerPackets.TdSellerName + 10)],
            "54 00 65 00 73 00 74 00 00 00", "SellerName is a NUL-terminated wstr at +0x08");
        Hex.Eq(rec[BrokerPackets.TdRegisterTime..(BrokerPackets.TdRegisterTime + 16)],
            "EA 07 09 00 10 00 16 00 20 00 2F 00 00 00 00 00",
            "RegisterTime at +0xB8: {2026, 9, 16, 22, 32, 47, 0, 0}");

        // Price is pinned by the other end: BUY_IT_NOW's TotalPriceWithTax for listing 3 is 1.
        var back = BrokerPackets.ParseTradeData(rec);
        Hex.True(back != null && back.Value.SellerName == "Test" && back.Value.Price == 1
                 && back.Value.TradeId == 3,
            $"round trip: {back?.SellerName} / {back?.Price} / {back?.TradeId}");
        Hex.True(BrokerPackets.ParseTradeData(new byte[0x187]) == null, "one byte short is refused");

        // The two u16s at +0x52 and +0x5C are the real Arbiter's uninitialised stack: they hold
        // 25119 / 25103 across listings AND stay set in the cleared record the Step-2 unregister
        // returns, where every real field is zero. We leave them zero.
        Hex.True(BitConverter.ToUInt16(rec, 0x52) == 0 && BitConverter.ToUInt16(rec, 0x5C) == 0,
            "we do not re-send another server's stack");
    }

    // ===================== T69: cap_social2.log, the real Arbiter =====================

    /// <summary>cap_social2.log seq 1980 (request) and 1982 (the empty-bank reply).</summary>
    const string Cap69_ViewWarehouseReq =
        "B3 00 00 00 02 00 00 00 00 00 00 00 20 E0 4C C8 "
        + "10 02 00 00 01 00 00 00 00 00 00 00";
    const string Cap69_ViewWarehouseRsp =
        "2D 00 00 00 00 00 00 00 B3 00 00 00 01 00 00 00 "
        + "00 48 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
        + "00 00 00 00 00 48 00";

    /// <summary>cap_social2.log seq 1268, SDB_CREATE_GUILD2's 36-byte header plus the three
    /// strings and the one-entry Member list. The 856-byte fee atom that follows is left off.</summary>
    const string Cap69_CreateGuild2Req =
        "2A 00 00 00 34 00 00 00 4E 00 00 00 5E 00 00 00 "
        + "04 00 00 00 62 00 00 00 58 03 00 00 EB 03 00 00 "
        + "A7 00 00 00 74 00 65 00 73 00 74 00 00 00 47 00 "
        + "75 00 69 00 6C 00 64 00 20 00 4D 00 61 00 73 00 "
        + "74 00 65 00 72 00 00 00 52 00 65 00 63 00 72 00 "
        + "75 00 69 00 74 00 00 00 02 00 00 00";

    /// <summary>
    /// DBS_VIEW_WAREHOUSE. Two fields were wrong before T69 and both are visible in every one of
    /// the nine captured views: MaxSlotCount is 0x48, not 0, and EndPos is the index of the LAST
    /// item, not one past it (0 items -&gt; 0, 1 -&gt; 0, 2 -&gt; 1, 3 -&gt; 2).
    /// </summary>
    [Test] public static void T69_the_warehouse_view_is_byte_exact()
    {
        var req = Hex.B(Cap69_ViewWarehouseReq);
        Hex.True(req.Length == WarehouseHandlers.ViewRequestSize, $"28-byte request: {req.Length}");
        Hex.True(BitConverter.ToUInt32(req, WarehouseHandlers.ViewReqDlmId) == 0xB3
                 && BitConverter.ToInt64(req, WarehouseHandlers.ViewReqOwnerDbId) == 2
                 && BitConverter.ToUInt32(req, WarehouseHandlers.ViewReqInvenType) == 1
                 && BitConverter.ToUInt32(req, WarehouseHandlers.ViewReqViewPos) == 0,
            "seq 1980: dlm 0xB3, owner 2, inven type 1, view pos 0");

        Hex.True(WarehouseHandlers.DefaultMaxSlotCount == 0x48,
            $"MaxSlotCount is 0x48 in all nine views: {WarehouseHandlers.DefaultMaxSlotCount}");
        Hex.Eq(WarehouseHandlers.BuildDbsViewWarehouse(0xB3, true, 0, 0, 0, 0,
                   WarehouseHandlers.DefaultMaxSlotCount, null),
               Hex.B(Cap69_ViewWarehouseRsp), "0x274B for an empty bank, seq 1982");

        // The occupied form: header identical bar the list slot, the totals and EndPos.
        var one = WarehouseHandlers.BuildDbsViewWarehouse(0xB5, true, 0, 0, 1, 0,
            WarehouseHandlers.DefaultMaxSlotCount, new[] { new byte[WarehouseHandlers.ItemRecordSize] });
        Hex.True(one.Length == WarehouseHandlers.ViewReplyHeader + WarehouseHandlers.ItemRecordSize
                 && BitConverter.ToUInt32(one, WarehouseHandlers.ViewRspListRef) == 45
                 && BitConverter.ToUInt32(one, WarehouseHandlers.ViewRspListRef + 4) == 0x218
                 && BitConverter.ToUInt32(one, WarehouseHandlers.ViewRspEndPos) == 0
                 && BitConverter.ToUInt32(one, WarehouseHandlers.ViewRspTotalItemNum) == 1,
            "seq 2010: one 0x218 record, EndPos 0, TotalItemNum 1");
    }

    /// <summary>
    /// The store/get pair, and the op the withdraw of a whole stack uses. 0x10 was unmodelled
    /// before T69, so taking a full stack out of the bank left the row sitting in it.
    /// </summary>
    [Test] public static void T69_the_warehouse_transfer_atoms_include_the_get_op()
    {
        Hex.True(WarehouseHandlers.TsWareGetItem == 0x10, "cap_social2.log seq 2085 carries op 16");

        using var store = GuildStore(2);
        store.UpsertItem(10018, 2, 1, 2, 17000, 1);          // in character 2's bank, slot 2
        var rec = GiveTake(0, WarehouseHandlers.TsWareGetItem, 10018, 17000,
                           2, 1, 2, 1, BagItems.Pocket, 2, 0);

        const int hdr = WarehouseHandlers.GetRequestSize;
        var payload = new byte[hdr + DbProxyHandlers.ItemAtomSize];
        BitConverter.GetBytes((uint)(6 + hdr)).CopyTo(payload, WarehouseHandlers.GetReqBinaryRef);
        BitConverter.GetBytes((uint)DbProxyHandlers.ItemAtomSize).CopyTo(payload, WarehouseHandlers.GetReqBinaryRef + 4);
        BitConverter.GetBytes(0xBEu).CopyTo(payload, WarehouseHandlers.GetReqDlmId);
        var atom = new byte[DbProxyHandlers.ItemAtomSize];
        rec.AsSpan(0, 0x58).CopyTo(atom);                     // the head is the same in both strides
        atom.CopyTo(payload, hdr);

        var (op, body) = RunHandler1(DbProxyHandlers.SDB_GET_WAREHOUSE, payload, store);
        Hex.True(op == DbProxyHandlers.DBS_GET_WAREHOUSE, $"replied with 0x{op:X4}");
        Hex.True(BitConverter.ToUInt32(body, WarehouseHandlers.TransferRspBinaryRef) == 31
                 && BitConverter.ToUInt32(body, WarehouseHandlers.TransferRspBinaryRef + 4) == DbProxyHandlers.ItemAtomSize
                 && BitConverter.ToUInt32(body, WarehouseHandlers.TransferRspDlmId) == 0xBE
                 && body[WarehouseHandlers.TransferRspSuccess] == 1,
            "seq 2075's header: [31][atom bytes][dlm][ok=1][error 0][commision 0]");

        var moved = store.GetInventoryItems(1).FirstOrDefault(r => r.ItemDbId == 10018);
        Hex.True(moved != null && moved.InvenType == BagItems.Pocket && moved.Slot == 2,
            "op 16 moves the whole row out of the bank and into the bag");
    }

    /// <summary>
    /// Two per-login loads that were still coming from the replay table. Both echo a DlmId, so a
    /// replayed constant hands World the id of whoever was logged in when the tap was recorded
    /// and the live user's DB queue never drains.
    /// </summary>
    [Test] public static void T69_the_refer_a_friend_loads_are_answered()
    {
        Hex.True(DbProxyHandlers.IsHandledRequest(DbProxyHandlers.SDB_LOAD_REFER_A_FRIEND)
                 && DbProxyHandlers.IsHandledRequest(DbProxyHandlers.SDB_LOAD_28B7),
            "0x28B0 and 0x28B7 are allow-listed now");

        Hex.Eq(DbProxyHandlers.BuildDbsReferAFriendList(0x19),
            "2F 00 00 00 00 00 00 00 2F 00 00 00 00 00 00 00 01 19 00 00 00 "
            + "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00",
            "0x28B1, cap_social2.log seq 125 - two empty lists at offset = frame length");
        Hex.Eq(DbProxyHandlers.BuildDbsInviteFriend(0x1A),
            "01 1A 00 00 00 00 00 00 00 FF FF FF FF FF FF FF FF",
            "0x28B6 (the reply opcode is request-1), seq 127 - AddInviteTime -1");
    }

    /// <summary>
    /// SDB_CREATE_GUILD2. Guild creation arrives on the DB-proxy link, nothing answered it, and
    /// its DlmId went unanswered - the founder's queue head-blocked. The replay table could not
    /// have covered it: no guild was created in any tap it was built from.
    /// </summary>
    [Test] public static void T69_SDB_CREATE_GUILD2_is_read_and_answered()
    {
        var req = Hex.B(Cap69_CreateGuild2Req);
        var r = GuildPackets.ParseSdbCreateGuild2(req);
        Hex.True(r != null, "the captured header parses");
        var v = r!.Value;
        Hex.True(v.GuildName == "test" && v.MasterGroupName == "Guild Master"
                 && v.MemberGroupName == "Recruit",
            $"seq 1268: '{v.GuildName}' / '{v.MasterGroupName}' / '{v.MemberGroupName}'");
        Hex.True(v.ChiefDbId == 1003 && v.DlmId == 0xA7, $"chief {v.ChiefDbId}, dlm 0x{v.DlmId:X}");
        Hex.True(v.MemberDbIds.Count == 1 && v.MemberDbIds[0] == 2,
            "the Member list is the founding co-signers, one u32 each");
        Hex.True(GuildPackets.ParseSdbCreateGuild2(new byte[35]) == null, "one byte short is refused");

        // The reply's block offsets, against the ones seq 1270 carries for 2 groups (0x28 each),
        // 2 members (0xF0 each), one 856-byte fee atom and a 4-character first-reply name.
        var groups = new[] { new byte[GuildPackets.GuildGroupDataSize], new byte[GuildPackets.GuildGroupDataSize] };
        var members = new[] { new byte[GuildPackets.GuildMemberDataSize], new byte[GuildPackets.GuildMemberDataSize] };
        var reply = GuildPackets.BuildDbsCreateGuild2("test", groups, members,
            new byte[DbProxyHandlers.ItemAtomSize], "Test",
            success: true, guildDbId: 1, chiefDbId: 1003, createTime: 0x6AAAF28B, dlmId: 0xA7, errorNo: 0);

        Hex.True(reply.Length == 1493, $"payload 1493 B, as seq 1270 is: {reply.Length}");
        Hex.True(BitConverter.ToUInt32(reply, 0) == 63
                 && BitConverter.ToUInt32(reply, 4) == 73 && BitConverter.ToUInt32(reply, 8) == 80
                 && BitConverter.ToUInt32(reply, 12) == 153 && BitConverter.ToUInt32(reply, 16) == 480
                 && BitConverter.ToUInt32(reply, 20) == 633 && BitConverter.ToUInt32(reply, 24) == 856
                 && BitConverter.ToUInt32(reply, 28) == 1489,
            "name 63, groups (73,80), members (153,480), itemBinary (633,856), firstReplyName 1489");
        Hex.True(reply[32] == 1 && BitConverter.ToInt32(reply, 33) == 1
                 && BitConverter.ToInt32(reply, 37) == 1003
                 && BitConverter.ToInt64(reply, 41) == 0x6AAAF28B
                 && BitConverter.ToUInt32(reply, 49) == 0xA7
                 && BitConverter.ToInt32(reply, 53) == 0,
            "Success/GuildDbId/ChiefDbId/CreateTime/DlmId/ErrorNo at the dumper's offsets");

        // The refusal still drains the queue.
        var no = GuildPackets.BuildDbsCreateGuild2Failure(0xA7, 1003, DbProxyHandlers.CreateGuildErrorGeneric);
        Hex.True(no[32] == 0 && BitConverter.ToUInt32(no, 49) == 0xA7
                 && BitConverter.ToInt32(no, 53) == DbProxyHandlers.CreateGuildErrorGeneric,
            "a refused create still echoes the DlmId");
        Hex.True(DbProxyHandlers.IsHandledRequest(GuildPackets.SDB_CREATE_GUILD2), "0x27D4 is allow-listed");
    }

    /// <summary>
    /// The guild boot load with no guilds. cap_social2.log seq 2 is the real one and it is 9141
    /// bytes: a full default-constructed GuildData with Success 0, not a short frame - and this
    /// time the two uninitialised bytes T51 saw are zero, so ours matches it exactly.
    /// </summary>
    [Test] public static void T69_the_guild_boot_terminator_matches_the_capture()
    {
        var p = GuildPackets.BuildEmptyDbsInitGuildData();
        Hex.True(p.Length == 9135, $"payload 9135 B (frame 9141): {p.Length}");
        Hex.True(BitConverter.ToUInt32(p, 0) == 19 && BitConverter.ToUInt32(p, 4) == GuildPackets.GuildDataSize
                 && BitConverter.ToUInt32(p, 8) == 9139 && p[12] == 0,
            "[19][0x23A0][9139][Success 0] - the logo id is the empty string at the frame end");

        // The six defaults the real Arbiter leaves in an otherwise zero GuildData.
        var blob = p[13..(13 + GuildPackets.GuildDataSize)];
        int nz = 0; foreach (byte b in blob) if (b != 0) nz++;
        Hex.True(nz == 16, $"sixteen non-zero bytes in the blob, as seq 2 has: {nz}");
        Hex.True(BitConverter.ToInt32(blob, 0x64) == 1
                 && BitConverter.ToInt32(blob, 0x235C) == 1
                 && BitConverter.ToInt32(blob, 0x2360) == 70
                 && BitConverter.ToInt32(blob, 0x2364) == 1,
            "GuildLevel 1, JoinMinLevel 1, JoinMaxLevel 70, GuildJoinType 1");
        Hex.True(blob[0x80] == 0xB2 && blob[0x81] == 0x07 && blob[0x82] == 0x01 && blob[0x84] == 0x01
                 && blob[0x2328] == 0xB2 && blob[0x2348] == 0xB2,
            "and the three epoch timestamps at 0x80 / 0x2328 / 0x2348");
    }

    // ===================== T65: the 2026-09-16 live run =====================

    /// <summary>One 568-byte ItemTransactionGiveTake record, at the offsets DO_TS_CHANGE_ITEM_OWNER
    /// reads (Arb_part_037.c:18245) - the same head the 856-byte atom has.</summary>
    static byte[] GiveTake(int index, uint op, long itemDbId, int templateId,
                           long srcOwner, int srcInven, int srcSlot,
                           long dstOwner, int dstInven, int dstSlot, long delta)
    {
        var r = new byte[DbProxyHandlers.ItemGiveTakeSize];
        BitConverter.GetBytes(index).CopyTo(r, 0);
        BitConverter.GetBytes(op).CopyTo(r, WarehouseHandlers.AtomOp);
        BitConverter.GetBytes(itemDbId).CopyTo(r, WarehouseHandlers.AtomItemDbId);
        BitConverter.GetBytes(templateId).CopyTo(r, WarehouseHandlers.AtomTemplateId);
        BitConverter.GetBytes(srcOwner).CopyTo(r, WarehouseHandlers.AtomSrcOwner);
        BitConverter.GetBytes(srcInven).CopyTo(r, WarehouseHandlers.AtomSrcInven);
        BitConverter.GetBytes(srcSlot).CopyTo(r, WarehouseHandlers.AtomSrcSlot);
        BitConverter.GetBytes(dstOwner).CopyTo(r, WarehouseHandlers.AtomDstOwner);
        BitConverter.GetBytes(dstInven).CopyTo(r, WarehouseHandlers.AtomDstInven);
        BitConverter.GetBytes(dstSlot).CopyTo(r, WarehouseHandlers.AtomDstSlot);
        BitConverter.GetBytes(delta).CopyTo(r, WarehouseHandlers.AtomDelta);
        return r;
    }

    /// <summary>
    /// 0x276A SDB_ITEM_TRADE, the frame that wedged a character's DB queue on 2026-09-16 with
    /// "no replay". It is SDB_ITEM_SINGLE's shape at a different stride: a 28-byte header (the
    /// extra i32 is TargetDBID) and 0x238-byte records, not 0x358.
    /// </summary>
    [Test] public static void T65_SDB_ITEM_TRADE_is_answered_at_the_give_take_stride()
    {
        Hex.True(DbProxyHandlers.ItemGiveTakeSize == 0x238,
            "Handler_SDB_ITEM_TRADE divides by 0x238, not 0x358 (Arb_part_063.c:11880)");
        Hex.True(6 + DbProxyHandlers.ItemTradeRequestHeader + 4 * DbProxyHandlers.ItemGiveTakeSize == 2306,
            "and that is what makes the live 2306-byte frame come out whole: 6 + 28 + 4 x 0x238");

        using var store = GuildStore(2);
        var recs = new[]
        {
            GiveTake(0, WarehouseHandlers.TsInsertItem, 0, 6560, 0, 0, 0, 2, BagItems.Pocket, 3, 1),
            GiveTake(1, WarehouseHandlers.TsChangeMoney, 0, 0, 2, 0, 0, 2, 0, 0, 25),
            GiveTake(0, WarehouseHandlers.TsInsertItem, 0, 88, 0, 0, 0, 1, BagItems.Pocket, 4, 1),
            GiveTake(1, WarehouseHandlers.TsChangeMoney, 0, 0, 1, 0, 0, 1, 0, 0, 50),
        };
        const int hdr = DbProxyHandlers.ItemTradeRequestHeader;
        var payload = new byte[hdr + 4 * DbProxyHandlers.ItemGiveTakeSize];
        BitConverter.GetBytes((uint)(6 + hdr)).CopyTo(payload, 0);
        BitConverter.GetBytes((uint)(2 * DbProxyHandlers.ItemGiveTakeSize)).CopyTo(payload, 4);
        BitConverter.GetBytes((uint)(6 + hdr + 2 * DbProxyHandlers.ItemGiveTakeSize)).CopyTo(payload, 8);
        BitConverter.GetBytes((uint)(2 * DbProxyHandlers.ItemGiveTakeSize)).CopyTo(payload, 12);
        BitConverter.GetBytes(0x3Cu).CopyTo(payload, 16);      // DlmId
        BitConverter.GetBytes(1).CopyTo(payload, 20);          // OwnerDBID
        BitConverter.GetBytes(2).CopyTo(payload, 24);          // TargetDBID
        for (int i = 0; i < recs.Length; i++)
            recs[i].CopyTo(payload, hdr + i * DbProxyHandlers.ItemGiveTakeSize);

        long before = store.GetCharacterMoney(2), beforeOwner = store.GetCharacterMoney(1);
        var (op, body) = RunHandler1(DbProxyHandlers.SDB_ITEM_TRADE, payload, store);
        Hex.True(op == DbProxyHandlers.DBS_ITEM_TRADE, $"replied with 0x{op:X4}, want 0x276B");
        Hex.True(body.Length == DbProxyHandlers.ItemSingleReplyHeader + 4 * DbProxyHandlers.ItemGiveTakeSize,
            $"both lists echoed under the 21-byte header: {body.Length} B");
        Hex.True(BitConverter.ToUInt32(body, 0) == 27
                 && BitConverter.ToUInt32(body, 4) == 2 * DbProxyHandlers.ItemGiveTakeSize
                 && BitConverter.ToUInt32(body, 8) == 27 + 2 * DbProxyHandlers.ItemGiveTakeSize
                 && BitConverter.ToUInt32(body, 12) == 2 * DbProxyHandlers.ItemGiveTakeSize,
            "the four backpatch slots FUN_1406ece60 writes, frame-relative");
        Hex.True(BitConverter.ToUInt32(body, 16) == 0x3C && body[20] == 1,
            "DlmId echoed and Success = 1 - an unanswered DlmId head-blocks the character forever");

        int idA = BitConverter.ToInt32(body, DbProxyHandlers.ItemSingleReplyHeader + WarehouseHandlers.AtomItemDbId);
        int idB = BitConverter.ToInt32(body, DbProxyHandlers.ItemSingleReplyHeader
                                            + 2 * DbProxyHandlers.ItemGiveTakeSize + WarehouseHandlers.AtomItemDbId);
        Hex.True(idA > 0 && idB > 0 && idA != idB, $"both inserts were given ids: {idA} / {idB}");
        Hex.True(store.GetInventoryItems(2).Any(r => r.ItemDbId == idA), "and the row exists for the target");
        Hex.True(store.GetInventoryItems(1).Any(r => r.ItemDbId == idB), "and for the owner");
        Hex.True(store.GetCharacterMoney(2) == before + 25 && store.GetCharacterMoney(1) == beforeOwner + 50,
            "the op-9 records moved character money on BOTH sides - list A then list B");
        Hex.True(DbProxyHandlers.IsHandledRequest(DbProxyHandlers.SDB_ITEM_TRADE), "0x276A is allow-listed");
    }

    /// <summary>
    /// 0x13AB is how a party is actually born in 100.02 - cap_social.log has one (seq 747) and no
    /// SA_JOIN_PARTY at all. PartyManager had no case for it, so it fell to the default reject
    /// ("0x13AB is not a party frame") and the party never formed even though the contract accept
    /// had already gone out.
    /// </summary>
    [Test] public static void T65_SA_JOIN_PARTY_IN_ARBITER_forms_the_party()
    {
        var p = Hex.B(Cap_join);
        var j = PartyPackets.ParseSaJoinPartyInArbiter(p);
        Hex.True(j != null && j.Value.MemberName == "Test" && j.Value.InviteeName == "two" && !j.Value.Raid,
            $"parsed: {j?.MemberName} + {j?.InviteeName}, raid {j?.Raid}");
        Hex.True(PartyPackets.ParseSaJoinPartyInArbiter(new byte[8]) == null, "one byte short is refused");

        var pm = NewPartyManager();
        pm.Register(P(10, 2, "Test")); pm.Register(P(11, 1002, "two"));
        var a = pm.OnWorldFrame(PartyPackets.SA_JOIN_PARTY_IN_ARBITER, p);
        Hex.True(a.Rejected == null, $"rejected: {a.Rejected}");
        Hex.True(WorldOps(a) == "0x139E,0x15CD,0x15CD,0x13AD,0x13AD", WorldOps(a));
        Hex.True(a.ToClients.Count == 2 && a.ToClients.All(c => c.PacketName == "S_PARTY_MEMBER_LIST"), Names(a));

        // A name nobody is using is refused rather than half-applying the join.
        var other = NewPartyManager();
        other.Register(P(10, 2, "Test"));
        Hex.True(other.OnWorldFrame(PartyPackets.SA_JOIN_PARTY_IN_ARBITER, p).Rejected != null,
            "with the invitee offline the frame is refused, not half-applied");
    }

    /// <summary>
    /// The inbox row carried parcel id 0, so the client dropped the C_SHOW_PARCEL_MESSAGE it
    /// would have sent and a relog rendered every mail as a blank row. The stored bytes ARE the
    /// SDB_MAKE_PARCEL record, and in that record both ParcelId (+0xA0) and ReceiverDbId (+0x50)
    /// are zero: the sending client knew neither.
    /// </summary>
    [Test] public static void T65_the_inbox_row_carries_its_parcel_id()
    {
        using var store = GuildStore(2);

        // A FULL 0x9e8 record, exactly as World hands it to us: ids still zero.
        var made = new byte[ParcelDbHandlers.ParcelDataNoMsgSize];
        Hex.B(Cap61_MakeParcelDataHead).CopyTo(made, 0);
        Hex.True(ParcelDbHandlers.ParseParcelData(made).ParcelId == 0
                 && ParcelDbHandlers.ParseParcelData(made).ReceiverDbId == 0,
            "the record World sent has neither id");

        int id = store.CreateParcel(2, "Test", 1, "No subject", string.Empty, 100);
        store.SetParcelRecord(id, made);

        var body = ParcelDbHandlers.BuildParcelList(store, 1, out uint count, out uint maxPage);
        Hex.True(count == 1 && maxPage == 1 && body.Length == ParcelDbHandlers.ParcelDataNoMsgSize,
            $"one 0x9e8 row: {count}/{maxPage}/{body.Length}");
        var served = ParcelDbHandlers.ParseParcelData(body);
        Hex.True(served.ParcelId == id, $"+A0 ParcelId is stamped: {served.ParcelId}");
        Hex.True(served.ReceiverDbId == 1, $"+50 ReceiverDbId is stamped: {served.ReceiverDbId}");
        Hex.True(served.SenderName == "Test" && served.Money == 100,
            "and the bytes World owns are untouched");

        // The empty form is unchanged: offset = frame length, count 0 (MAIL-WAREHOUSE.md 10).
        var empty = ParcelDbHandlers.BuildEmptyDbsListParcel(0xA7, 0, 0);
        Hex.True(empty.Length == ParcelDbHandlers.ListReplyHeader
                 && BitConverter.ToUInt32(empty, 0) == 35 && BitConverter.ToUInt32(empty, 4) == 0,
            "an empty inbox is still the 35-byte frame");

        // And the header around a real row is the one seq 1539 shows.
        var full = ParcelDbHandlers.BuildDbsListParcel(0xA7, true, 0, 0, maxPage, count, body);
        Hex.True(BitConverter.ToUInt32(full, 0) == 35
                 && BitConverter.ToUInt32(full, 4) == ParcelDbHandlers.ParcelDataNoMsgSize
                 && BitConverter.ToUInt32(full, ParcelDbHandlers.ListRspDlmId) == 0xA7
                 && full[ParcelDbHandlers.ListRspSuccess] == 1
                 && BitConverter.ToUInt32(full, ParcelDbHandlers.ListRspMaxPage) == 1
                 && BitConverter.ToUInt32(full, ParcelDbHandlers.ListRspParcelCount) == 1,
            "cap_social.log seq 1539: [35][0x9E8][dlm][1][view][page][1][1]");
    }

    /// <summary>
    /// parcels.money is the Arbiter's own column - World sets it in the ParcelData it sends and
    /// never sees it again - so nothing credited it and attached gold vanished when the mail was
    /// opened. It is paid once, and only when the request's own atoms did not already move
    /// character money.
    /// </summary>
    [Test] public static void T65_attached_gold_is_paid_when_the_parcel_is_claimed()
    {
        using var store = GuildStore(2);
        int id = store.CreateParcel(2, "g2", 1, "here", string.Empty, 500);
        long before = store.GetCharacterMoney(1);

        var payload = new byte[ParcelDbHandlers.RecvRequestSize];
        BitConverter.GetBytes((uint)(6 + ParcelDbHandlers.RecvRequestSize))
            .CopyTo(payload, ParcelDbHandlers.RecvReqTransListRef);
        BitConverter.GetBytes(0u).CopyTo(payload, ParcelDbHandlers.RecvReqTransListRef + 4);
        BitConverter.GetBytes(0x51u).CopyTo(payload, ParcelDbHandlers.RecvReqDlmId);
        BitConverter.GetBytes(1u).CopyTo(payload, ParcelDbHandlers.RecvReqStep);
        BitConverter.GetBytes((uint)id).CopyTo(payload, ParcelDbHandlers.RecvReqParcelId);

        var (op, body) = RunHandler1(DbProxyHandlers.SDB_RECV_PARCEL, payload, store);
        Hex.True(op == DbProxyHandlers.DBS_RECV_PARCEL, $"replied with 0x{op:X4}");
        Hex.True(body[ParcelDbHandlers.RecvRspSuccess] == 1, "Success = 1 for a parcel that exists");
        Hex.True(store.GetCharacterMoney(1) == before + 500,
            $"the 500 gold landed on the receiver: {store.GetCharacterMoney(1)} (was {before})");

        // Claimed once. A second receive of the same parcel pays nothing.
        RunHandler1(DbProxyHandlers.SDB_RECV_PARCEL, payload, store);
        Hex.True(store.GetCharacterMoney(1) == before + 500, "and only once");
    }

    /// <summary>
    /// The friend-added line printed the literal "{usernames}". cap_social_client.log seq 1436 is
    /// the real one: SMT 433 with a UserName parameter, not 432. 432 is a different string whose
    /// own parameter is spelled differently in this client's table, which is why the placeholder
    /// came through untouched.
    /// </summary>
    /// <summary>cap_social_client.log seq 1436, the S_SYSTEM_MESSAGE string block (packet + 6).</summary>
    const string Cap65_SmtFriendAccepted =
        "40 00 34 00 33 00 33 00 0B 00 55 00 73 00 65 00 72 00 4E 00 61 00 6D 00 65 00 "
        + "0B 00 74 00 77 00 6F 00 00 00";

    [Test] public static void T65_the_friend_accepted_message_is_smt_433()
    {
        var cap = Hex.B(Cap65_SmtFriendAccepted);
        string seen = System.Text.Encoding.Unicode.GetString(cap).TrimEnd('\0');
        Hex.True(SocialHandlers.SmtAcceptedToRequester == 433,
            $"SMT 433, not 432: {SocialHandlers.SmtAcceptedToRequester}");
        Hex.True(seen == SocialHandlers.Smt(SocialHandlers.SmtAcceptedToRequester, "UserName", "two"),
            $"the captured message is '{seen}'");
    }



    /// <summary>
    /// T58. The deploy-side wiring checks: the allow-list is enumerable, every opcode in it has a
    /// PERSISTENCE-MAP row, and a missing row is reported rather than thrown. This is the direction
    /// Every_per_user_request_opcode_is_answered does NOT cover (that one asks documented =&gt;
    /// answered; T54 found 27 answered opcodes with no row).
    /// </summary>
    [Test] public static void T58_selftest_checks_the_allow_list_against_the_persistence_map()
    {
        var allow = SelfTest.AllowListOpcodes();
        Hex.True(allow.Count > 0, "the allow-list enumerates");
        Hex.True(allow.All(DbProxyHandlers.IsHandledRequest),
            "and every opcode it yields is one IsHandledRequest answers");
        Hex.True(allow.Contains((ushort)0x1463) == DbProxyHandlers.IsHandledRequest(0x1463),
            "spot check: 0x1463 SA_LEARN_ALL_CREST_ACQUIRABLE agrees with the switch");

        // a map that documents everything -> PASS
        string full = Path.GetTempFileName();
        string thin = Path.GetTempFileName();
        try
        {
            var rows = new System.Text.StringBuilder();
            rows.AppendLine("| write (W->A) | reply | shape | count | feeds |");
            rows.AppendLine("|---|---|---|---|---|");
            foreach (var op in allow)
                rows.AppendLine($"| 0x{op:X4} SDB_TEST ({op} B) | 0xDEAD | [x] | 1 | nothing |");
            File.WriteAllText(full, rows.ToString());
            var ok = SelfTest.CheckPersistenceMap(full);
            Hex.True(ok.Pass, $"a complete map passes: {ok.Detail}");
            Hex.True(!ok.Required, "and it is optional - a published build does not ship status/");

            // drop ONE row -> FAIL, naming exactly that opcode
            var dropped = allow[0];
            var kept = rows.ToString().Split('\n')
                .Where(l => !l.TrimStart().StartsWith($"| 0x{dropped:X4} ", StringComparison.Ordinal));
            File.WriteAllText(thin, string.Join("\n", kept));
            var bad = SelfTest.CheckPersistenceMap(thin);
            Hex.True(!bad.Pass, "one missing row fails the check");
            Hex.True(bad.Detail.Contains($"0x{dropped:X4}", StringComparison.Ordinal),
                $"and names it: {bad.Detail}");

            // backticked first cells are skipped, the way the one-way tables opt out
            Hex.True(SelfTest.ParseDocumentedOpcodes("| `0x2809` | none | x | 1 | x |").Count == 0,
                "a backticked row documents nothing");
        }
        finally { File.Delete(full); File.Delete(thin); }

        // an absent map warns, it does not throw and does not fail the deploy
        var none = SelfTest.CheckPersistenceMap(null);
        Hex.True(!none.Pass && !none.Required, "no map: WARN, not FAIL");

        // the ArbiterOwned check has no exemptions - every one must reach a handler, or
        // PacketDispatcher logs it and drops it instead of forwarding (status/CLIENT-REJECTS.md)
        Hex.True(SelfTest.ArbiterOwnedWithoutHandler.Length == 0,
            "no ArbiterOwned opcode is deliberately handler-less");

        // and a missing data.json yields two FAIL lines rather than an exception at startup
        var handlers = SelfTest.CheckHandlers(@"Z:\nope\data.json", "376012", @"Z:\nope\defs");
        Hex.True(handlers.Count == 2 && handlers.All(r => !r.Pass),
            $"a bad deploy path reports {handlers.Count} failure(s), no throw");
    }

    // ===================== T75: the 2026-09-16 live pass =====================

    /// <summary>
    /// T75 (1). The friend-accept notice printed its own placeholder because the accepter's copy
    /// of SMT 433 was sent with NO parameter. Both sides get the other party's name, keyed
    /// <c>UserName</c> - capitalised exactly like this, because the client substitutes by key and a
    /// miss leaves the placeholder in the text. Pinned to the real Arbiter's own frame 1436 in
    /// D:\packetlogs\cap_social_client.log.
    /// </summary>
    [Test] public static void T75_friend_accept_smt_names_the_other_party()
    {
        const string expected = "@433\vUserName\vtwo";
        Hex.True(SocialHandlers.Smt(SocialHandlers.SmtAcceptedToRequester, "UserName", "two") == expected,
            SocialHandlers.Smt(SocialHandlers.SmtAcceptedToRequester, "UserName", "two"));
        Hex.True(SocialHandlers.SmtAcceptedToRequester == 0x1B1, "SMT 433");

        // and the same string on the wire, byte for byte: [u16 msgOffset=6][NUL-terminated UTF-16LE]
        var body = new byte[2 + (expected.Length + 1) * 2];
        BitConverter.GetBytes((ushort)6).CopyTo(body, 0);
        System.Text.Encoding.Unicode.GetBytes(expected).CopyTo(body, 2);
        Hex.Eq(body,
            "06 00  40 00 34 00 33 00 33 00  0B 00  "
            + "55 00 73 00 65 00 72 00 4E 00 61 00 6D 00 65 00  0B 00  74 00 77 00 6F 00  00 00",
            "S_SYSTEM_MESSAGE body, cap_social_client frame 1436");

        // a parameterless 433 is what produced the literal placeholder - it must not come back
        Hex.True(SocialHandlers.Smt(SocialHandlers.SmtAcceptedToRequester) == "@433",
            "the unparameterised form still builds, and is what the bug looked like");
    }

    /// <summary>
    /// T75 (4). The intro cinematic replayed on every relog because the client was never told what
    /// it had already visited: T45 stored the rows and pushed them to World, but nothing sent
    /// S_VISITED_SECTION_LIST. The real Arbiter sends it immediately after C_LOAD_TOPO_FIN -
    /// cap_social_client frames 256 -&gt; 257, pinned here byte for byte.
    /// </summary>
    [Test] public static void T75_visited_section_list_matches_the_relog_capture()
    {
        var rows = new[]
        {
            new TeraSharp.Arbiter.Persistence.CharacterStore.VisitedSection(1, 25, 0x000923D9),
            new TeraSharp.Arbiter.Persistence.CharacterStore.VisitedSection(9999, 25, 9827),
        };
        Hex.Eq(ArbiterClientHandlers.BuildVisitedSectionList(rows),
            "28 00  53 A8  02 00  08 00  "
            + "08 00 18 00  01 00 00 00  19 00 00 00  D9 23 09 00  "
            + "18 00 00 00  0F 27 00 00  19 00 00 00  63 26 00 00",
            "S_VISITED_SECTION_LIST, cap_social_client frame 257");

        Hex.Eq(ArbiterClientHandlers.BuildVisitedSectionList(null),
            "08 00  53 A8  00 00  00 00",
            "nothing visited yet: count 0, offset 0 - still an answer, so no intro replays");
        Hex.True(ArbiterClientHandlers.VisitedSectionListEntrySize == 16
                 && ArbiterClientHandlers.VisitedSectionListFixedSize == 8,
            "16-byte entries after an 8-byte fixed part");

        // the same (mapId, guardId, sectionId) triple S_VISIT_NEW_SECTION carries, so one stored
        // row feeds both packets - cap_social_client frame 374 is the 0x5A23 for the first entry
        Hex.Eq(ArbiterClientHandlers.BuildVisitNewSection(false, 1, 25, 0x000923D9),
            "11 00  23 5A  00  01 00 00 00  19 00 00 00  D9 23 09 00",
            "S_VISIT_NEW_SECTION, cap_social_client frame 374");
    }

